/* =========================================================
  직원 엑셀 업로드 알림
========================================================= */

function showEmployeeUploadMessage(message) {
  if (
    typeof showToast === "function"
  ) {
    showToast(message);
    return;
  }

  alert(message);
}


/* =========================================================
  직원 엑셀 파일 선택창 열기
========================================================= */

function openEmployeeExcelUpload() {
  const fileInput =
    document.getElementById(
      "employeeExcelFileInput"
    );

  if (!fileInput) {
    console.error(
      "employeeExcelFileInput 요소를 찾을 수 없습니다."
    );

    showEmployeeUploadMessage(
      "엑셀 파일 선택창을 찾을 수 없습니다."
    );

    return;
  }

  /*
    같은 파일을 연속으로 선택해도
    change 이벤트가 다시 실행되도록 초기화
  */
  fileInput.value = "";

  fileInput.click();
}


/* =========================================================
  직원 엑셀 파일 읽기

  현재 단계:
  - 직원명단 시트 읽기
  - 사번 / 이름 / 파트장 / 비고 변환
  - 유효하지 않은 행 제거
  - 중복 사번 제거
  - 아직 서버에는 저장하지 않음
========================================================= */

async function handleEmployeeExcelUpload(event) {
  const file =
    event.target.files?.[0];

  if (!file) {
    return;
  }

  if (
    typeof XLSX === "undefined"
  ) {
    console.error(
      "SheetJS XLSX 라이브러리가 연결되지 않았습니다."
    );

    showEmployeeUploadMessage(
      "엑셀 라이브러리를 불러오지 못했습니다."
    );

    event.target.value = "";

    return;
  }

  try {
    const arrayBuffer =
      await file.arrayBuffer();

    const workbook =
      XLSX.read(
        arrayBuffer,
        {
          type: "array"
        }
      );

    const sheetName =
      workbook.SheetNames.includes(
        "직원명단"
      )
        ? "직원명단"
        : workbook.SheetNames[0];

    const worksheet =
      workbook.Sheets[
        sheetName
      ];

    if (!worksheet) {
      throw new Error(
        "직원명단 시트를 찾을 수 없습니다."
      );
    }

    const rawRows =
      XLSX.utils.sheet_to_json(
        worksheet,
        {
          defval: "",
          raw: false
        }
      );

    const parsedEmployees =
      rawRows
        .map(
          (
            row,
            index
          ) => {
            const employeeNo =
              String(
                row["사번"] ?? ""
              )
                .trim()
                .replace(
                  /[^0-9]/g,
                  ""
                );

            const name =
              String(
                row["이름"] ?? ""
              ).trim();

            const leaderValue =
              String(
                row["파트장"] ?? ""
              ).trim();

            const note =
              String(
                row["비고"] ?? ""
              ).trim();

            return {
              rowNumber:
                index + 2,

              employeeNo,

              name,

              isLeader:
                leaderValue ===
                "파트장",

              note
            };
          }
        )
        .filter(
          employee => {
            return (
              employee.employeeNo ||
              employee.name
            );
          }
        );

    const invalidEmployees =
      parsedEmployees.filter(
        employee => {
          return (
            !employee.employeeNo ||
            !employee.name
          );
        }
      );

    if (
      invalidEmployees.length >
      0
    ) {
      const invalidRows =
        invalidEmployees
          .map(
            employee =>
              employee.rowNumber
          )
          .join(", ");

      throw new Error(
        `사번 또는 이름이 비어 있는 행이 있습니다. 행 번호: ${invalidRows}`
      );
    }

    const employeeMap =
      new Map();

    const duplicateEmployeeNumbers =
      [];

    parsedEmployees.forEach(
      employee => {
        if (
          employeeMap.has(
            employee.employeeNo
          )
        ) {
          duplicateEmployeeNumbers.push(
            employee.employeeNo
          );

          return;
        }

        employeeMap.set(
          employee.employeeNo,
          employee
        );
      }
    );

    const employees =
      Array.from(
        employeeMap.values()
      ).map(
        employee => {
          return {
            employeeNo:
              employee.employeeNo,

            name:
              employee.name,

            /*
              파트장은 관리자 권한으로 저장한다.
              추후 leader 권한을 만들면 여기만 변경하면 된다.
            */
            defaultRole:
              employee.isLeader
                ? "admin"
                : "user",

            /*
              엑셀 등록 직원은 모두 가입 허용
            */
            isAllowed:
              true
          };
        }
      );

    if (
      employees.length === 0
    ) {
      throw new Error(
        "등록할 직원 정보가 없습니다."
      );
    }

    const leaderCount =
      employees.filter(
        employee => {
          return (
            employee.defaultRole ===
            "admin"
          );
        }
      ).length;

    const shouldSave =
      window.confirm(
        [
          `직원 ${employees.length}명을 저장하시겠습니까?`,
          "",
          `파트장 ${leaderCount}명`,
          "기존 사번은 이름과 권한만 갱신됩니다."
        ].join("\n")
      );

    if (!shouldSave) {
      showEmployeeUploadMessage(
        "직원 명단 저장을 취소했습니다."
      );

      return;
    }

    showEmployeeUploadMessage(
      "직원 명단을 저장하고 있습니다."
    );

    const response =
      await fetch(
        "/api/employees",
        {
          method:
            "POST",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json"
          },

          cache:
            "no-store",

          body:
            JSON.stringify({
              employees
            })
        }
      );

    let result = {};

    try {
      result =
        await response.json();
    } catch (error) {
      throw new Error(
        "직원 저장 서버의 응답을 확인할 수 없습니다."
      );
    }

    if (
      !response.ok ||
      !result.ok
    ) {
      throw new Error(
        result.message ||
        "직원 명단 저장에 실패했습니다."
      );
    }

    window.pendingEmployeeExcelData =
      [];

    const successMessage =
      result.message ||
      `직원 ${employees.length}명 저장을 완료했습니다.`;

    showEmployeeUploadMessage(
      successMessage
    );

    /*
      최신 직원 목록 다시 불러오기
    */
    if (
      typeof loadEmployeeManagement ===
      "function"
    ) {
      await loadEmployeeManagement();
    }

    if (
      typeof loadEmployeeDirectory ===
      "function"
    ) {
      await loadEmployeeDirectory();
    }

    console.log(
      "직원 엑셀 저장 완료:",
      result
    );

    if (
      duplicateEmployeeNumbers.length >
      0
    ) {
      console.warn(
        "엑셀 내부 중복으로 제외된 사번:",
        duplicateEmployeeNumbers
      );
    }

  } catch (error) {
    console.error(
      "직원 엑셀 업로드 오류:",
      error
    );

    showEmployeeUploadMessage(
      error.message ||
      "직원 엑셀 파일을 처리하지 못했습니다."
    );

  } finally {
    event.target.value =
      "";
  }
}

/* =========================================================
  TO·BO1·BO2 전 근무 운전현황 가져오기 최종본

  사용 가능:
  - TO
  - BO1
  - BO2

  사용 불가:
  - TGO
  - BCO1
  - BCO2
  - 파트장

  적용 방식:
  - 같은 보직의 직전 근무 운전현황 조회
  - 줄바꿈과 내용 그대로 적용
  - 현재 작성 내용이 있으면 덮어쓰기 확인
  - 운전현황 저장 버튼을 눌러야 현재 근무에 확정
========================================================= */

async function handleLoadPreviousOperationStatus() {
  const loadButton =
    document.getElementById(
      "loadPreviousOperationStatusBtn"
    );


  const currentRole =
    normalizeMemberLogRole(
      elements.logRole?.value ||
      ""
    );


  const allowedRoles = [
    "TO",
    "BO1",
    "BO2"
  ];


  if (
    !allowedRoles.includes(
      currentRole
    )
  ) {
    showToast(
      "TO·BO1·BO2 업무일지에서만 전 근무 운전현황을 가져올 수 있습니다."
    );

    return;
  }


  if (
    !elements.operationStatus
  ) {
    showToast(
      "운전현황 입력창을 찾을 수 없습니다."
    );

    return;
  }


  const currentDate =
    String(
      elements.logDate?.value ||
      ""
    ).trim();


  const currentShift =
    String(
      elements.logShift?.value ||
      ""
    )
      .trim()
      .toUpperCase();


  if (
    !currentDate ||
    !currentShift
  ) {
    showToast(
      "업무일지 날짜와 근무를 확인해 주세요."
    );

    return;
  }


  const currentContent =
    String(
      elements.operationStatus.value ||
      ""
    )
      .replace(
        /\r\n/g,
        "\n"
      )
      .replace(
        /\r/g,
        "\n"
      )
      .trim();


  if (
    currentContent
  ) {
    const shouldOverwrite =
      window.confirm(
        [
          "현재 작성된 운전현황이 있습니다.",
          "",
          "전 근무 운전현황으로 덮어쓰시겠습니까?",
          "",
          "아직 업무일지는 저장되지 않습니다."
        ].join(
          "\n"
        )
      );


    if (
      !shouldOverwrite
    ) {
      return;
    }
  }


  const originalButtonText =
    String(
      loadButton?.textContent ||
      "전 근무자 운전현황 가져오기"
    ).trim();


  if (
    loadButton
  ) {
    loadButton.disabled =
      true;

    loadButton.textContent =
      "불러오는 중...";
  }


  try {
    const previousStatus =
      await getPreviousShiftOperationStatus(
        currentRole,
        currentDate,
        currentShift
      );


    const previousContent =
      String(
        previousStatus?.content ||
        ""
      )
        .replace(
          /\r\n/g,
          "\n"
        )
        .replace(
          /\r/g,
          "\n"
        )
        .trim();


    if (
      !previousStatus ||
      !previousContent
    ) {
      showToast(
        `${currentRole} 전 근무 운전현황을 찾을 수 없습니다.`
      );

      return;
    }


    /*
      자유 텍스트 입력창에 전 근무 내용을 그대로 적용한다.
    */
    elements.operationStatus.value =
      previousContent;


    /*
      업무일지 저장용 숨김값도 함께 갱신한다.
    */
    if (
      elements.operationStatusSnapshot
    ) {
      elements.operationStatusSnapshot.value =
        previousContent;
    }


    if (
      elements.operationStatusType
    ) {
      elements.operationStatusType.value =
        "normal";
    }


    /*
      현재 작성창 운전현황 객체 갱신
    */
    appState.currentOperationStatus = {
      role:
        currentRole,

      type:
        "normal",

      content:
        previousContent,

      operationItems:
        [],

      items:
        [],

      /*
        아직 현재 근무 운전현황으로 저장한 것이 아니므로
        수정시간과 수정자는 비워둔다.
      */
      updatedAt:
        "",

      updatedBy:
        "",

      inheritedFromDate:
        String(
          previousStatus.date ||
          ""
        ).trim(),

      inheritedFromShift:
        String(
          previousStatus.shift ||
          ""
        )
          .trim()
          .toUpperCase(),

      inheritedFromAuthor:
        String(
          previousStatus.author ||
          ""
        ).trim()
    };


    elements.operationStatus
      .dispatchEvent(
        new Event(
          "input",
          {
            bubbles:
              true
          }
        )
      );


    elements.operationStatus.focus();


    const previousShiftName =
      getShiftDisplayName(
        previousStatus.shift
      );


    showToast(
      [
        previousStatus.date,
        previousShiftName,
        currentRole,
        "운전현황을 가져왔습니다."
      ].join(
        " "
      )
    );

  } catch (
    error
  ) {
    console.error(
      `${currentRole} 전 근무 운전현황 조회 오류:`,
      error
    );


    showToast(
      error.message ||
      "전 근무 운전현황을 불러오지 못했습니다."
    );

  } finally {
    if (
      loadButton
    ) {
      loadButton.disabled =
        false;

      loadButton.textContent =
        originalButtonText;
    }
  }
}
/* =========================================================
  로그인 사용자 → 업무일지 작성자 자동 연결

  적용 규칙:
  - 작성자는 현재 로그인한 사용자 이름
  - 작성자 입력창 직접 수정 불가
  - 임시저장 또는 기존 자료를 불러와도
    현재 로그인 사용자 이름으로 다시 고정
========================================================= */

function getCurrentShiftLogUserIdentity() {
  const currentUser =
    loadCurrentUser();


  if (
    !currentUser
  ) {
    return {
      employeeNo:
        "",

      name:
        "",

      role:
        ""
    };
  }


  const employeeNo =
    String(
      currentUser.employeeNo ||
      currentUser.employee_no ||
      currentUser.employeeId ||
      currentUser.employee_id ||
      ""
    ).trim();


  const name =
    String(
      currentUser.name ||
      currentUser.employeeName ||
      currentUser.employee_name ||
      ""
    ).trim();


  const role =
    String(
      currentUser.role ||
      ""
    )
      .trim()
      .toLowerCase();


  return {
    employeeNo,

    name,

    role
  };
}


/* =========================================================
  작성자 입력창 잠금
========================================================= */

function applyCurrentUserToLogAuthor() {
  const authorInput =
    document.getElementById(
      "logAuthor"
    );


  if (
    !authorInput
  ) {
    return;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  /*
    로그인 사용자 이름이 정상적으로 있을 때만 적용
  */
  if (
    currentUser.name
  ) {
    authorInput.value =
      currentUser.name;
  }


  /*
    작성자 직접 수정 금지
  */
  authorInput.readOnly =
    true;


  authorInput.setAttribute(
    "aria-readonly",
    "true"
  );


  authorInput.setAttribute(
    "tabindex",
    "-1"
  );


  authorInput.setAttribute(
    "title",
    "작성자는 현재 로그인한 사용자로 자동 지정됩니다."
  );


  /*
    브라우저 자동완성 방지
  */
  authorInput.setAttribute(
    "autocomplete",
    "off"
  );
}


/* =========================================================
  업무일지 작성창이 열릴 때마다 작성자 재적용

  fillLogEditor()
  restoreDraftIfAvailable()
  resetLogEditor()

  위 함수들이 작성자 값을 바꾸더라도
  모달이 열리는 순간 현재 로그인 사용자로 다시 고정한다.
========================================================= */

function initializeCurrentUserLogAuthorLock() {
  const logEditorModal =
    document.getElementById(
      "logEditorModal"
    );


  /*
    최초 한 번 적용
  */
  applyCurrentUserToLogAuthor();


  if (
    !logEditorModal
  ) {
    return;
  }


  const observer =
    new MutationObserver(
      () => {
        const isOpen =
          logEditorModal
            .classList
            .contains(
              "is-open"
            ) ||

          logEditorModal.getAttribute(
            "aria-hidden"
          ) ===
            "false";


        if (
          !isOpen
        ) {
          return;
        }


        /*
          기존 함수들의 입력 처리가 끝난 다음
          로그인 사용자 이름을 최종 적용한다.
        */
        window.requestAnimationFrame(
          () => {
            applyCurrentUserToLogAuthor();
          }
        );
      }
    );


  observer.observe(
    logEditorModal,
    {
      attributes:
        true,

      attributeFilter: [
        "class",
        "aria-hidden"
      ]
    }
  );


  /*
    사용자가 개발자 도구 등으로 값을 변경하거나
    브라우저 자동완성이 값을 덮어쓰는 경우도 방지한다.
  */
  const authorInput =
    document.getElementById(
      "logAuthor"
    );


  authorInput
    ?.addEventListener(
      "input",
      () => {
        const currentUser =
          getCurrentShiftLogUserIdentity();


        if (
          currentUser.name &&
          authorInput.value !==
            currentUser.name
        ) {
          authorInput.value =
            currentUser.name;
        }
      }
    );
}


document.addEventListener(
  "DOMContentLoaded",
  initializeCurrentUserLogAuthorLock
);

/* =========================================================
  업무일지 작성자 정보 로그인 계정 강제 연결

  저장되는 값:
  - author     : 로그인 사용자 이름
  - authorId   : 로그인 사용자 사번
  - authorRole : 로그인 사용자 권한

  상태 기본 규칙:
  - 파트장 본인 업무일지 → 저장완료
  - 일반 파트원 업무일지 → 임시저장
  - 결재요청은 요청된 경우 그대로 유지

  기존 collectEditorData()의
  TM·인계사항·비고·첨부파일 수집 구조는 그대로 유지한다.
========================================================= */

function normalizeShiftLogAccountRole(
  role
) {
  return String(
    role || ""
  )
    .trim()
    .toLowerCase();
}


/* =========================================================
  현재 로그인 사용자가 파트장인지 확인
========================================================= */

function isCurrentShiftLogLeader() {
  const currentUser =
    getCurrentShiftLogUserIdentity();


  const accountRole =
    normalizeShiftLogAccountRole(
      currentUser.role
    );


  return (
    accountRole ===
      "admin" ||
    accountRole ===
      "leader"
  );
}

/* =========================================================
  업무일지 저장 상태 최종 결정

  일반 보직:
  - 작성중·임시저장 → 임시저장
  - 작성완료·결재요청 → 결재요청
  - 결재요청 상태 → 일반 저장으로 상태 변경 금지
  - 결재완료 상태 → 일반 저장으로 상태 변경 금지

  파트장:
  - 일반 저장은 임시저장
  - 결재완료는 별도 approve API 사용
  - 결재취소는 별도 cancel API 사용

  최고관리자 계정이어도
  현재 작성 중인 보직과 누른 버튼을 기준으로 처리한다.
========================================================= */

function resolveShiftLogSaveStatus(
  requestedStatus
) {
  const rawRequestedStatus =
    String(
      requestedStatus ||
      ""
    ).trim();


  const normalizedRequestedStatus =
    typeof normalizeShiftLogApprovalStatus ===
      "function"
      ? normalizeShiftLogApprovalStatus(
          rawRequestedStatus
        )
      : rawRequestedStatus;


  const currentEditorRole =
    normalizeMemberLogRole(
      elements?.logRole?.value ||
      ""
    );


  const editingId =
    String(
      elements?.logEditorForm
        ?.dataset
        ?.editingId ||
      ""
    ).trim();


  const existingLog =
    editingId
      ? (
          appState.logs.find(
            log => {
              return (
                String(
                  log?.id ||
                  ""
                ).trim() ===
                editingId
              );
            }
          ) ||
          null
        )
      : null;


  const existingStatus =
    existingLog
      ? normalizeShiftLogApprovalStatus(
          existingLog.status
        )
      : "";


  /* =====================================================
    파트장 업무일지

    임시저장 후 별도 결재완료 기능을 사용한다.
  ====================================================== */

  if (
    currentEditorRole ===
      "파트장"
  ) {
    /*
      이미 결재완료된 파트장 일지는
      일반 저장으로 상태를 낮추지 않는다.
    */
    if (
      existingStatus ===
        "결재완료"
    ) {
      return "결재완료";
    }


    return "임시저장";
  }


  /* =====================================================
    일반 보직 결재완료 상태 보호
  ====================================================== */

  if (
    existingStatus ===
      "결재완료"
  ) {
    return "결재완료";
  }


  /* =====================================================
    일반 보직 결재요청

    기존 코드에서는 작성완료를 사용하므로
    작성완료도 결재요청으로 변환한다.
  ====================================================== */

  if (
    rawRequestedStatus ===
      "작성완료" ||
    normalizedRequestedStatus ===
      "결재요청"
  ) {
    return "결재요청";
  }


  /* =====================================================
    이미 결재요청된 일지 보호

    결재요청 취소는 별도 cancel API만 사용한다.
  ====================================================== */

  if (
    existingStatus ===
      "결재요청"
  ) {
    return "결재요청";
  }


  /* =====================================================
    신규 작성·임시저장
  ====================================================== */

  return "임시저장";
}

/* =========================================================
  현재 업무일지 작성·수정창 버튼 유형 결정

  기준은 로그인 계정 권한이 아니라
  현재 작성·수정 중인 업무일지의 보직이다.

  파트장:
  - 저장 버튼

  나머지 보직:
  - 임시저장
  - 결재요청

  최고관리자가 다른 보직 업무일지를 수정해도
  해당 보직의 일반적인 저장 흐름을 그대로 사용한다.
========================================================= */

function getCurrentShiftLogPermissionType() {
  const currentEditorRole =
    normalizeMemberLogRole(
      elements.logRole?.value ||
      ""
    );


  if (
    currentEditorRole ===
    "파트장"
  ) {
    return "leader";
  }


  return "member";
}


/* =========================================================
  업무일지 작성·수정창 하단 버튼 표시

  파트장:
  - 저장 표시
  - 임시저장 숨김
  - 결재요청 숨김

  TGO·BCO1·BCO2·TO·BO1·BO2:
  - 저장 숨김
  - 임시저장 표시
  - 결재요청 표시

  최고관리자가 수정해도
  현재 업무일지 보직 기준으로 동일하게 표시한다.
========================================================= */

function updateLogEditorActionButtons() {
  const permissionType =
    getCurrentShiftLogPermissionType();


  const submitButton =
    getShiftLogEditorSubmitButton();


  const saveDraftButton =
    elements.saveDraftButton ||
    document.getElementById(
      "saveDraftButton"
    );


  const requestApprovalButton =
    elements.requestApprovalButton ||
    document.getElementById(
      "requestApprovalButton"
    );


  const isLeaderMode =
    permissionType ===
    "leader";


  /*
    파트장 저장 버튼
  */
  if (
    submitButton
  ) {
    submitButton.hidden =
      !isLeaderMode;


    submitButton.disabled =
      !isLeaderMode;


    submitButton.textContent =
      "저장";


    submitButton.title =
      isLeaderMode
        ? "파트장 업무일지를 저장완료 상태로 저장합니다."
        : "";
  }


  /*
    파트원 임시저장 버튼
  */
  if (
    saveDraftButton
  ) {
    saveDraftButton.hidden =
      isLeaderMode;


    saveDraftButton.disabled =
      isLeaderMode;


    saveDraftButton.textContent =
      "임시저장";


    saveDraftButton.title =
      isLeaderMode
        ? ""
        : "현재 작성 내용을 임시저장합니다.";
  }


  /*
    파트원 결재요청 버튼
  */
  if (
    requestApprovalButton
  ) {
    requestApprovalButton.hidden =
      isLeaderMode;


    requestApprovalButton.disabled =
      isLeaderMode;


    requestApprovalButton.textContent =
      "결재요청";


    requestApprovalButton.title =
      isLeaderMode
        ? ""
        : "업무일지를 저장하고 결재를 요청합니다.";
  }


  /*
    hidden 속성이 기존 CSS에 의해 무시되는 경우를 막기 위해
    실제 표시 상태도 함께 고정한다.
  */
  if (
    submitButton
  ) {
    submitButton.style.setProperty(
      "display",
      isLeaderMode
        ? "inline-flex"
        : "none",
      "important"
    );
  }


  if (
    saveDraftButton
  ) {
    saveDraftButton.style.setProperty(
      "display",
      isLeaderMode
        ? "none"
        : "inline-flex",
      "important"
    );
  }


  if (
    requestApprovalButton
  ) {
    requestApprovalButton.style.setProperty(
      "display",
      isLeaderMode
        ? "none"
        : "inline-flex",
      "important"
    );
  }
}

/* =========================================================
  업무일지 수정·이어쓰기 가능 여부

  최고관리자:
  - 파트장 포함 모든 보직 수정 가능
  - 결재 상태와 관계없이 수정 가능
  - 과거 연동 업무일지는 수정 불가
========================================================= */

function canCurrentUserEditShiftLog(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    return false;
  }


  /*
    과거 연동 업무일지는
    기존대로 조회만 허용
  */
  if (
    isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    return false;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  const currentEmployeeNo =
    String(
      currentUser?.employeeNo ||
      ""
    ).trim();


  const currentUserName =
    String(
      currentUser?.name ||
      ""
    ).trim();


  if (
    !currentEmployeeNo ||
    !currentUserName
  ) {
    return false;
  }


  /*
    최고관리자는 파트장·TGO·BCO1·BCO2·
    TO·BO1·BO2 업무일지를 모두 수정할 수 있다.
  */
  if (
    isCurrentUserSuperAdmin()
  ) {
    return true;
  }


  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  /*
    임시저장은 기존 규칙대로
    로그인한 직원이 이어쓸 수 있다.
  */
  if (
    normalizedStatus ===
      "임시저장"
  ) {
    return true;
  }


  if (
    !isCurrentUserShiftLogAuthor(
      log
    )
  ) {
    return false;
  }


  const logRole =
    normalizeMemberLogRole(
      log.role
    );


  /*
    파트장 본인의 저장완료 업무일지
  */
  if (
    isCurrentShiftLogLeader() &&
    logRole ===
      "파트장" &&
    normalizedStatus ===
      "저장완료"
  ) {
    return true;
  }


  return false;
}


/* =========================================================
  기존 업무일지 데이터 수집 함수 보존
========================================================= */

const collectEditorDataBeforeAccountLink =
  collectEditorData;


/* =========================================================
  로그인 계정 연결이 적용된 최종 데이터 수집 함수

  신규 작성:
  - 현재 로그인 사용자를 작성자로 저장

  임시저장 이어쓰기:
  - 누가 작성했든 저장한 사람으로 작성자 변경
  - 최초 작성자는 내부 기록으로 유지

  최고관리자 일반 수정:
  - 임시저장 이외 상태는 원 작성자 유지
  - 최종 수정자만 최고관리자로 기록
========================================================= */

collectEditorData =
  function collectEditorData(
    requestedStatus
  ) {
    const log =
      collectEditorDataBeforeAccountLink(
        requestedStatus
      );


    const currentUser =
      getCurrentShiftLogUserIdentity();


    const currentEmployeeNo =
      String(
        currentUser?.employeeNo ||
        ""
      ).trim();


    const currentUserName =
      String(
        currentUser?.name ||
        ""
      ).trim();


    const currentAccountRole =
      normalizeShiftLogAccountRole(
        currentUser?.role ||
        ""
      );


    if (
      !currentEmployeeNo ||
      !currentUserName
    ) {
      showToast(
        "로그인 사용자 정보를 확인할 수 없습니다. 다시 로그인해 주세요."
      );


      return {
        ...log,

        author:
          "",

        authorId:
          "",

        authorRole:
          "",

        status:
          "임시저장"
      };
    }


    /* =====================================================
      현재 수정 중인 기존 업무일지 확인
    ====================================================== */

    const editingId =
      String(
        elements.logEditorForm
          ?.dataset.editingId ||
        log?.id ||
        ""
      ).trim();


    const existingLog =
      editingId
        ? (
            appState.logs.find(
              (
                currentLog
              ) => {
                return (
                  String(
                    currentLog?.id ||
                    ""
                  ).trim() ===
                  editingId
                );
              }
            ) ||
            null
          )
        : null;


    const now =
      new Date()
        .toISOString();


    const resolvedStatus =
      resolveShiftLogSaveStatus(
        requestedStatus
      );


    /* =====================================================
      1. 신규 업무일지

      현재 로그인 사용자가 작성자
    ====================================================== */

    if (
      !existingLog
    ) {
      return {
        ...log,

        author:
          currentUserName,

        authorId:
          currentEmployeeNo,

        authorRole:
          currentAccountRole,

        status:
          resolvedStatus,

        createdAt:
          log.createdAt ||
          now,

        lastModifiedBy:
          currentUserName,

        lastModifiedById:
          currentEmployeeNo,

        lastModifiedByRole:
          currentAccountRole,

        updatedAt:
          now
      };
    }


    const existingStatus =
      normalizeShiftLogApprovalStatus(
        existingLog.status
      );


    const existingAuthor =
      String(
        existingLog.author ||
        ""
      ).trim();


    const existingAuthorId =
      String(
        existingLog.authorId ||
        existingLog.writerId ||
        existingLog.employeeNo ||
        ""
      ).trim();


    const existingAuthorRole =
      String(
        existingLog.authorRole ||
        ""
      ).trim();


    const isDifferentAuthor =
      existingAuthorId
        ? (
            existingAuthorId !==
            currentEmployeeNo
          )
        : (
            Boolean(
              existingAuthor
            ) &&
            existingAuthor !==
              currentUserName
          );


    /* =====================================================
      2. 임시저장 업무일지 이어쓰기

      최고관리자인지 관계없이
      실제 저장한 로그인 사용자로 작성자 변경

      열기만 하고 닫으면 이 함수가 저장되지 않으므로
      기존 작성자가 그대로 유지된다.
    ====================================================== */

    if (
      existingStatus ===
      "임시저장"
    ) {
      return {
        ...log,


        /*
          최초 작성자는 계속 보존한다.
        */
        originalAuthor:
          String(
            existingLog.originalAuthor ||
            existingAuthor ||
            ""
          ).trim(),

        originalAuthorId:
          String(
            existingLog.originalAuthorId ||
            existingAuthorId ||
            ""
          ).trim(),

        originalAuthorRole:
          String(
            existingLog.originalAuthorRole ||
            existingAuthorRole ||
            ""
          ).trim(),


        /*
          작성자가 바뀌는 경우 직전 작성자 기록
        */
        previousAuthor:
          isDifferentAuthor
            ? existingAuthor
            : String(
                existingLog.previousAuthor ||
                ""
              ).trim(),

        previousAuthorId:
          isDifferentAuthor
            ? existingAuthorId
            : String(
                existingLog.previousAuthorId ||
                ""
              ).trim(),

        previousAuthorRole:
          isDifferentAuthor
            ? existingAuthorRole
            : String(
                existingLog.previousAuthorRole ||
                ""
              ).trim(),


        /*
          현재 저장한 사람이 새 작성자가 된다.
        */
        author:
          currentUserName,

        authorId:
          currentEmployeeNo,

        authorRole:
          currentAccountRole,


        /*
          임시저장 또는 결재요청
        */
        status:
          resolvedStatus,


        /*
          최초 생성시간 유지
        */
        createdAt:
          existingLog.createdAt ||
          log.createdAt ||
          now,


        /*
          작성자 변경 이력
        */
        authorChanged:
          Boolean(
            existingLog.authorChanged ||
            isDifferentAuthor
          ),

        authorChangedAt:
          isDifferentAuthor
            ? now
            : String(
                existingLog.authorChangedAt ||
                ""
              ),

        authorChangedBy:
          isDifferentAuthor
            ? currentUserName
            : String(
                existingLog.authorChangedBy ||
                ""
              ).trim(),

        authorChangedById:
          isDifferentAuthor
            ? currentEmployeeNo
            : String(
                existingLog.authorChangedById ||
                ""
              ).trim(),


        /*
          최종 수정자
        */
        lastModifiedBy:
          currentUserName,

        lastModifiedById:
          currentEmployeeNo,

        lastModifiedByRole:
          currentAccountRole,

        updatedAt:
          now
      };
    }


    /* =====================================================
      3. 최고관리자가 임시저장 이외 상태 수정

      결재요청·결재완료·저장완료는
      관리자 수정만으로 작성자를 바꾸지 않는다.
    ====================================================== */

    if (
      isCurrentUserSuperAdmin()
    ) {
      return {
        ...log,

        author:
          existingAuthor ||
          log.author ||
          "",

        authorId:
          existingAuthorId ||
          log.authorId ||
          "",

        authorRole:
          existingAuthorRole ||
          log.authorRole ||
          "",

        originalAuthor:
          String(
            existingLog.originalAuthor ||
            ""
          ).trim(),

        originalAuthorId:
          String(
            existingLog.originalAuthorId ||
            ""
          ).trim(),

        /*
          관리자가 내용을 수정해도
          기존 결재 상태는 유지한다.
        */
        status:
          existingStatus,

        createdAt:
          existingLog.createdAt ||
          log.createdAt ||
          now,

        lastModifiedBy:
          currentUserName,

        lastModifiedById:
          currentEmployeeNo,

        lastModifiedByRole:
          currentAccountRole,

        updatedAt:
          now
      };
    }


    /* =====================================================
      4. 일반적인 본인 업무일지 수정
    ====================================================== */

    return {
      ...log,

      author:
        currentUserName,

      authorId:
        currentEmployeeNo,

      authorRole:
        currentAccountRole,

      originalAuthor:
        String(
          existingLog.originalAuthor ||
          existingAuthor ||
          ""
        ).trim(),

      originalAuthorId:
        String(
          existingLog.originalAuthorId ||
          existingAuthorId ||
          ""
        ).trim(),

      originalAuthorRole:
        String(
          existingLog.originalAuthorRole ||
          existingAuthorRole ||
          ""
        ).trim(),

      status:
        resolvedStatus,

      createdAt:
        existingLog.createdAt ||
        log.createdAt ||
        now,

      lastModifiedBy:
        currentUserName,

      lastModifiedById:
        currentEmployeeNo,

      lastModifiedByRole:
        currentAccountRole,

      updatedAt:
        now
    };
  };

  /* =========================================================
  업무일지 작성창 버튼 권한 분리

  파트장:
  - 저장 버튼만 표시
  - 저장 시 저장완료
  - 임시저장 / 결재요청 숨김

  파트원:
  - 임시저장 표시
  - 결재요청 표시
  - 일반 저장 버튼 숨김
========================================================= */

function getShiftLogEditorSubmitButton() {
  return (
    elements.logEditorForm
      ?.querySelector(
        'button[type="submit"]'
      ) ||
    document.querySelector(
      '#logEditorForm button[type="submit"]'
    )
  );
}


/* =========================================================
  현재 로그인 사용자의 업무일지 권한 구분
========================================================= */

function getCurrentShiftLogPermissionType() {
  const currentUser =
    getCurrentShiftLogUserIdentity();


  const accountRole =
    String(
      currentUser.role ||
      ""
    )
      .trim()
      .toLowerCase();


  if (
    accountRole ===
      "admin" ||
    accountRole ===
      "leader"
  ) {
    return "leader";
  }


  return "member";
}


/* =========================================================
  작성창 하단 버튼 표시 갱신
========================================================= */

function updateLogEditorActionButtons() {
  const permissionType =
    getCurrentShiftLogPermissionType();


  const submitButton =
    getShiftLogEditorSubmitButton();


  const saveDraftButton =
    elements.saveDraftButton ||
    document.getElementById(
      "saveDraftButton"
    );


  const requestApprovalButton =
    elements.requestApprovalButton ||
    document.getElementById(
      "requestApprovalButton"
    );


  const isLeader =
    permissionType ===
      "leader";


  /*
    파트장 저장 버튼
  */
  if (
    submitButton
  ) {
    submitButton.hidden =
      !isLeader;

    submitButton.disabled =
      !isLeader;

    submitButton.textContent =
      "저장";

    submitButton.title =
      isLeader
        ? "파트장 업무일지를 저장완료 상태로 저장합니다."
        : "";
  }


  /*
    파트원 임시저장 버튼
  */
  if (
    saveDraftButton
  ) {
    saveDraftButton.hidden =
      isLeader;

    saveDraftButton.disabled =
      isLeader;

    saveDraftButton.textContent =
      "임시저장";
  }


  /*
    파트원 결재요청 버튼
  */
  if (
    requestApprovalButton
  ) {
    requestApprovalButton.hidden =
      isLeader;

    requestApprovalButton.disabled =
      isLeader;

    requestApprovalButton.textContent =
      "결재요청";
  }
}


/* =========================================================
  작성창이 열릴 때마다 버튼 권한 적용
========================================================= */

function initializeLogEditorActionButtonPermissions() {
  const logEditorModal =
    elements.logEditorModal ||
    document.getElementById(
      "logEditorModal"
    );


  /*
    최초 한 번 적용
  */
  updateLogEditorActionButtons();


  if (
    !logEditorModal
  ) {
    return;
  }


  const observer =
    new MutationObserver(
      () => {
        const isOpen =
          logEditorModal
            .classList
            .contains(
              "is-open"
            ) ||

          logEditorModal.getAttribute(
            "aria-hidden"
          ) ===
            "false";


        if (
          !isOpen
        ) {
          return;
        }


        window.requestAnimationFrame(
          () => {
            updateLogEditorActionButtons();
          }
        );
      }
    );


  observer.observe(
    logEditorModal,
    {
      attributes:
        true,

      attributeFilter: [
        "class",
        "aria-hidden"
      ]
    }
  );


  /*
    보직값이 화면 처리 과정에서 변경되더라도
    로그인 계정 권한 기준으로 버튼을 다시 맞춘다.
  */
  elements.logRole
    ?.addEventListener(
      "change",
      updateLogEditorActionButtons
    );
}


document.addEventListener(
  "DOMContentLoaded",
  initializeLogEditorActionButtonPermissions
);

/* =========================================================
  업무일지 수정 권한 및 결재 상태 잠금

  파트원:
  - 임시저장: 본인 수정 가능
  - 결재요청: 수정 불가
  - 결재완료: 수정 불가

  파트장:
  - 본인 저장완료 업무일지 수정 가능
  - 다른 사람 업무일지 직접 수정 불가
  - 결재는 상세보기의 결재 버튼으로만 처리

  과거 업무일지:
  - 수정 및 삭제 불가
========================================================= */


/* =========================================================
  업무일지 상태 정규화

  기존 상태값도 새 상태값으로 호환한다.
========================================================= */

function normalizeShiftLogApprovalStatus(
  status
) {
  const normalizedStatus =
    String(
      status ||
      ""
    ).trim();


  const statusMap = {
    작성중:
      "임시저장",

    임시저장:
      "임시저장",

    작성완료:
      "결재요청",

    결재요청:
      "결재요청",

    결재완료:
      "결재완료",

    저장완료:
      "저장완료"
  };


  return (
    statusMap[
      normalizedStatus
    ] ||
    normalizedStatus ||
    "임시저장"
  );
}


/* =========================================================
  현재 로그인 사용자가 해당 업무일지 작성자인지 확인

  신규 업무일지:
  - authorId 사용

  기존 신규 업무일지:
  - writerId 사용

  authorId가 없던 과거 저장자료:
  - 작성자 이름으로 보조 비교
========================================================= */

function isCurrentUserShiftLogAuthor(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    return false;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  const currentEmployeeNo =
    String(
      currentUser.employeeNo ||
      ""
    ).trim();


  const currentUserName =
    String(
      currentUser.name ||
      ""
    ).trim();


  const logAuthorId =
    String(
      log.authorId ||
      log.writerId ||
      log.employeeNo ||
      ""
    ).trim();


  const logAuthorName =
    String(
      log.author ||
      ""
    ).trim();


  /*
    사번이 양쪽에 존재하면
    반드시 사번으로 비교한다.
  */
  if (
    currentEmployeeNo &&
    logAuthorId
  ) {
    return (
      currentEmployeeNo ===
      logAuthorId
    );
  }


  /*
    authorId가 저장되기 전 자료만
    이름을 보조 기준으로 사용한다.
  */
  if (
    currentUserName &&
    logAuthorName
  ) {
    return (
      currentUserName ===
      logAuthorName
    );
  }


  return false;
}


/* =========================================================
  과거 업무일지 여부 확인
========================================================= */

function isReadOnlyLegacyShiftLog(
  log
) {
  const source =
    String(
      log?.source ||
      ""
    )
      .trim()
      .toLowerCase();


  return (
    source ===
      "legacy" ||
    source.startsWith(
      "legacy-"
    )
  );
}

/* =========================================================
  업무일지 수정·이어쓰기 가능 여부 최종본

  공통:
  - 과거 업무일지는 조회 전용

  임시저장:
  - 로그인한 직원 누구나 이어쓰기 가능
  - 실제 저장 시 작성자가 현재 로그인 사용자로 변경

  결재요청·결재완료:
  - 일반 사용자는 수정 불가
  - 최고관리자만 수정 가능

  저장완료:
  - 파트장 본인 업무일지는 수정 가능
  - 최고관리자는 전체 수정 가능
========================================================= */

function canCurrentUserEditShiftLog(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    return false;
  }


  /*
    과거 D1 업무일지는
    현재 저장 기능과 연결되지 않으므로 조회 전용
  */
  if (
    isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    return false;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  const currentEmployeeNo =
    String(
      currentUser?.employeeNo ||
      ""
    ).trim();


  const currentUserName =
    String(
      currentUser?.name ||
      ""
    ).trim();


  /*
    로그인 사용자 정보를 확인할 수 없으면
    작성창을 열 수 없다.
  */
  if (
    !currentEmployeeNo ||
    !currentUserName
  ) {
    return false;
  }


  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  /* =====================================================
    임시저장 업무일지

    작성자가 누구인지 관계없이
    로그인한 직원이면 이어쓰기 가능
  ====================================================== */

  if (
    normalizedStatus ===
    "임시저장"
  ) {
    return true;
  }


  /* =====================================================
    최고관리자

    과거 업무일지를 제외한 모든 상태 수정 가능
  ====================================================== */

  if (
    isCurrentUserSuperAdmin()
  ) {
    return true;
  }


  /* =====================================================
    임시저장이 아닌 업무일지는
    원 작성자 여부를 확인한다.
  ====================================================== */

  if (
    !isCurrentUserShiftLogAuthor(
      log
    )
  ) {
    return false;
  }


  const isLeader =
    isCurrentShiftLogLeader();


  const logRole =
    normalizeMemberLogRole(
      log.role
    );


  /*
    파트장 본인의 저장완료 업무일지
  */
  if (
    isLeader &&
    logRole ===
      "파트장" &&
    normalizedStatus ===
      "저장완료"
  ) {
    return true;
  }


  return false;
}


/* =========================================================
  업무일지 수정 불가 사유 안내 최종본
========================================================= */

function showShiftLogEditDeniedMessage(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    showToast(
      "업무일지 정보를 확인할 수 없습니다."
    );

    return;
  }


  /*
    과거 업무일지
  */
  if (
    isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    showToast(
      "과거 업무일지는 조회만 가능하며 수정할 수 없습니다."
    );

    return;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  if (
    !String(
      currentUser?.employeeNo ||
      ""
    ).trim() ||
    !String(
      currentUser?.name ||
      ""
    ).trim()
  ) {
    showToast(
      "로그인 사용자 정보를 확인할 수 없습니다. 다시 로그인해 주세요."
    );

    return;
  }


  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  /*
    임시저장은 누구나 이어쓸 수 있으므로
    이 메시지까지 도달하면 비정상 상태다.
  */
  if (
    normalizedStatus ===
    "임시저장"
  ) {
    showToast(
      "업무일지를 이어서 작성할 수 없습니다. 화면을 새로고침해 주세요."
    );

    return;
  }


  if (
    normalizedStatus ===
    "결재요청"
  ) {
    showToast(
      "결재요청 중인 업무일지입니다. 결재요청을 취소한 후 수정해 주세요."
    );

    return;
  }


  if (
    normalizedStatus ===
    "결재완료"
  ) {
    showToast(
      "결재가 완료된 업무일지입니다. 결재취소 후 수정할 수 있습니다."
    );

    return;
  }


  if (
    normalizedStatus ===
    "저장완료"
  ) {
    showToast(
      "저장완료된 파트장 업무일지는 작성자 또는 최고관리자만 수정할 수 있습니다."
    );

    return;
  }


  showToast(
    "현재 상태에서는 업무일지를 수정할 수 없습니다."
  );
}


/* =========================================================
  기존 업무일지 작성창 열기 함수 보존
========================================================= */

const openLogEditorBeforeApprovalLock =
  openLogEditor;


/* =========================================================
  결재 잠금이 적용된 업무일지 작성창 열기

  기존 업무일지 수정:
  - 권한과 상태를 먼저 검사

  신규 업무일지 작성:
  - 기존 openLogEditor 기능 그대로 실행
========================================================= */

openLogEditor =
  function openLogEditor(
    log = null,
    preset = null
  ) {
    /*
      기존 업무일지 수정 요청일 때만
      수정 권한을 검사한다.
    */
    if (
      log &&
      !canCurrentUserEditShiftLog(
        log
      )
    ) {
      showShiftLogEditDeniedMessage(
        log
      );

      /*
        수정창 대신 상세보기로 이동한다.
      */
      openLogDetail(
        log
      );

      return;
    }


    openLogEditorBeforeApprovalLock(
      log,
      preset
    );
  };


/* =========================================================
  기존 업무일지 삭제 함수 보존
========================================================= */

const deleteLogByIdBeforeApprovalLock =
  deleteLogById;


/* =========================================================
  결재 잠금이 적용된 업무일지 삭제
========================================================= */

deleteLogById =
  function deleteLogById(
    logId
  ) {
    const targetLog =
      appState.logs.find(
        (
          log
        ) => {
          return (
            String(
              log?.id ||
              ""
            ).trim() ===
            String(
              logId ||
              ""
            ).trim()
          );
        }
      );


    if (
      !targetLog
    ) {
      showToast(
        "삭제할 업무일지를 찾을 수 없습니다."
      );

      return;
    }


    if (
      !canCurrentUserEditShiftLog(
        targetLog
      )
    ) {
      showShiftLogEditDeniedMessage(
        targetLog
      );

      return;
    }


    deleteLogByIdBeforeApprovalLock(
      logId
    );
  };

  /* =========================================================
  상세보기 결재 버튼 권한 및 상태 제어

  파트원 본인:
  - 임시저장: 수정
  - 결재요청: 결재취소
  - 결재완료: 버튼 없음

  파트장:
  - 결재요청: 결재완료 + 결재취소
  - 결재완료: 결재취소
  - 파트장 본인 저장완료: 수정

  과거 업무일지:
  - 조회만 가능
========================================================= */


/* =========================================================
  현재 상세보기 업무일지 찾기
========================================================= */

function getCurrentDetailShiftLog() {
  const currentLogId =
    String(
      appState.currentDetailLogId ||
      ""
    ).trim();


  if (
    !currentLogId
  ) {
    return null;
  }


  return (
    appState.logs.find(
      (
        log
      ) => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          currentLogId
        );
      }
    ) ||
    null
  );
}


/* =========================================================
  결재취소 버튼 생성

  HTML 수정 없이 기존 상세보기 하단에 자동으로 추가한다.
========================================================= */

function ensureCancelApprovalDetailButton() {
  let cancelButton =
    document.getElementById(
      "cancelApprovalFromDetailButton"
    );


  if (
    cancelButton
  ) {
    return cancelButton;
  }


  const approveButton =
    elements.approveFromDetailButton ||
    document.getElementById(
      "approveFromDetailButton"
    );


  if (
    !approveButton
  ) {
    return null;
  }


  cancelButton =
    document.createElement(
      "button"
    );


  cancelButton.type =
    "button";


  cancelButton.id =
    "cancelApprovalFromDetailButton";


  cancelButton.className =
    "secondary-button";


  cancelButton.textContent =
    "결재취소";


  cancelButton.hidden =
    true;


  approveButton.insertAdjacentElement(
    "afterend",
    cancelButton
  );


  return cancelButton;
}


/* =========================================================
  상세보기 결재 버튼 표시 규칙
========================================================= */

function updateShiftLogDetailActionButtons(
  log
) {
  const approveButton =
    elements.approveFromDetailButton ||
    document.getElementById(
      "approveFromDetailButton"
    );


  const cancelApprovalButton =
    ensureCancelApprovalDetailButton();


  const editButton =
    elements.editFromDetailButton ||
    document.getElementById(
      "editFromDetailButton"
    );


  /*
    상세보기를 열 때마다
    모든 작업 버튼을 먼저 숨긴다.
  */
  if (
    approveButton
  ) {
    approveButton.hidden =
      true;

    approveButton.disabled =
      true;

    approveButton.textContent =
      "결재완료";
  }


  if (
    cancelApprovalButton
  ) {
    cancelApprovalButton.hidden =
      true;

    cancelApprovalButton.disabled =
      true;

    cancelApprovalButton.textContent =
      "결재취소";
  }


  if (
    editButton
  ) {
    editButton.hidden =
      true;

    editButton.disabled =
      true;

    editButton.textContent =
      "수정";
  }


  /*
    업무일지가 없거나 과거 연동 일지이면
    작업 버튼을 표시하지 않는다.
  */
  if (
    !log ||
    isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    return;
  }


  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  const normalizedLogRole =
    normalizeMemberLogRole(
      log.role
    );


  const isLeaderLog =
    normalizedLogRole ===
      "파트장";


  const isLeaderOrSuperAdmin =
    isCurrentShiftLogLeader() ||
    isCurrentUserSuperAdmin();


  /*
    수정 가능 여부는 앞 단계에서 교체한
    최종 수정 권한 함수를 그대로 사용한다.

    - 일반회원: 일반 보직의 임시저장 일지
    - 파트장: 본인의 파트장 저장완료 일지
    - 최고관리자: 관리 가능한 일지
  */
  if (
    editButton &&
    canCurrentUserEditShiftLog(
      log
    )
  ) {
    editButton.hidden =
      false;

    editButton.disabled =
      false;
  }


  /*
    파트장 업무일지는 결재 대상이 아니다.
  */
  if (
    isLeaderLog
  ) {
    return;
  }


  /*
    파트장 또는 최고관리자는
    결재요청 상태를 결재완료할 수 있다.
  */
  if (
    approveButton &&
    isLeaderOrSuperAdmin &&
    normalizedStatus ===
      "결재요청"
  ) {
    approveButton.hidden =
      false;

    approveButton.disabled =
      false;
  }


  /*
    결재취소 버튼은 앞 단계에서 교체한
    최종 결재취소 권한 함수로 표시한다.

    - 일반회원: 모든 일반 보직의 결재요청 취소 가능
    - 파트장·최고관리자: 결재요청·결재완료 취소 가능
  */
  if (
    cancelApprovalButton &&
    canCurrentUserCancelShiftLogApproval(
      log
    )
  ) {
    cancelApprovalButton.hidden =
      false;

    cancelApprovalButton.disabled =
      false;
  }
}


/* =========================================================
  파트장 결재완료 처리
========================================================= */

function completeCurrentDetailShiftLogApproval() {
  const targetLog =
    getCurrentDetailShiftLog();


  if (
    !targetLog
  ) {
    showToast(
      "결재할 업무일지를 찾을 수 없습니다."
    );

    return;
  }


  if (
    !(
      isCurrentShiftLogLeader() ||
      isCurrentUserSuperAdmin()
    )
  ) {
    showToast(
      "파트장 또는 최고관리자만 업무일지를 결재할 수 있습니다."
    );

    return;
  }


  if (
    isReadOnlyLegacyShiftLog(
      targetLog
    )
  ) {
    showToast(
      "과거 업무일지는 결재 상태를 변경할 수 없습니다."
    );

    return;
  }


  if (
    normalizeMemberLogRole(
      targetLog.role
    ) ===
      "파트장"
  ) {
    showToast(
      "파트장 업무일지는 결재 대상이 아닙니다."
    );

    return;
  }


  const currentStatus =
    normalizeShiftLogApprovalStatus(
      targetLog.status
    );


  if (
    currentStatus !==
      "결재요청"
  ) {
    showToast(
      currentStatus ===
        "결재완료"
        ? "이미 결재가 완료된 업무일지입니다."
        : "결재요청 상태의 업무일지만 결재할 수 있습니다."
    );

    return;
  }


  const shouldApprove =
    window.confirm(
      [
        "이 업무일지를 결재완료 처리하시겠습니까?",
        "",
        `작성일: ${targetLog.date || "-"}`,
        `근무: ${getShiftDisplayName(
          targetLog.shift
        )}`,
        `보직: ${targetLog.role || "-"}`,
        `작성자: ${targetLog.author || "-"}`
      ].join("\n")
    );


  if (
    !shouldApprove
  ) {
    return;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  const now =
    new Date()
      .toISOString();


  targetLog.status =
    "결재완료";


  targetLog.approvedAt =
    now;


  targetLog.approvedBy =
    currentUser.name;


  targetLog.approvedById =
    currentUser.employeeNo;


  targetLog.approvedByRole =
    normalizeShiftLogAccountRole(
      currentUser.role
    );


  targetLog.lastModifiedBy =
    currentUser.name;


  targetLog.lastModifiedById =
    currentUser.employeeNo;


  targetLog.updatedAt =
    now;


  persistLogs();


  renderLogTable();

  updateShiftMemberCardStates();


  openLogDetail(
    targetLog
  );


  showToast(
    "업무일지 결재가 완료되었습니다."
  );
}


/* =========================================================
  결재취소 가능 여부

  파트원:
  - 본인의 결재요청 상태만 가능

  파트장:
  - 결재요청
  - 결재완료
========================================================= */

function canCurrentUserCancelShiftLogApproval(
  log
) {
  if (
    !log ||
    isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    return false;
  }


  const normalizedLogRole =
    normalizeMemberLogRole(
      log.role
    );


  /*
    파트장 업무일지는
    결재 대상이 아니다.
  */
  if (
    normalizedLogRole ===
      "파트장"
  ) {
    return false;
  }


  const memberRoles = [
    "TGO",
    "BCO1",
    "BCO2",
    "TO",
    "BO1",
    "BO2"
  ];


  if (
    !memberRoles.includes(
      normalizedLogRole
    )
  ) {
    return false;
  }


  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  /*
    결재요청 상태

    - 결재요청한 현재 작성자 본인만 취소 가능
    - 다른 일반회원은 취소 불가
    - 파트장과 최고관리자도 취소 불가
  */
  if (
    normalizedStatus ===
      "결재요청"
  ) {
    return isCurrentUserShiftLogAuthor(
      log
    );
  }


  /*
    결재완료 상태

    - 파트장 또는 최고관리자만
      완료된 결재를 취소할 수 있다.
  */
  if (
    normalizedStatus ===
      "결재완료"
  ) {
    return (
      isCurrentShiftLogLeader() ||
      isCurrentUserSuperAdmin()
    );
  }


  return false;
}

/* =========================================================
  결재취소 처리

  결재요청 또는 결재완료
  → 임시저장

  다시 작성자 본인이 수정할 수 있게 된다.
========================================================= */

function cancelCurrentDetailShiftLogApproval() {
  const targetLog =
    getCurrentDetailShiftLog();


  if (
    !targetLog
  ) {
    showToast(
      "결재취소할 업무일지를 찾을 수 없습니다."
    );

    return;
  }


  if (
    !canCurrentUserCancelShiftLogApproval(
      targetLog
    )
  ) {
    showToast(
      "현재 계정으로는 이 업무일지의 결재를 취소할 수 없습니다."
    );

    return;
  }


  const previousStatus =
    normalizeShiftLogApprovalStatus(
      targetLog.status
    );


  const shouldCancel =
    window.confirm(
      previousStatus ===
        "결재완료"
        ? [
            "완료된 결재를 취소하시겠습니까?",
            "",
            "업무일지는 임시저장 상태로 돌아가며",
            "작성자가 다시 수정할 수 있게 됩니다."
          ].join("\n")
        : [
            "결재요청을 취소하시겠습니까?",
            "",
            "업무일지는 임시저장 상태로 돌아가며",
            "작성자가 다시 수정할 수 있게 됩니다."
          ].join("\n")
    );


  if (
    !shouldCancel
  ) {
    return;
  }


  const currentUser =
    getCurrentShiftLogUserIdentity();


  const now =
    new Date()
      .toISOString();


  targetLog.status =
    "임시저장";


  /*
    기존 결재완료 정보 제거
  */
  delete targetLog.approvedAt;

  delete targetLog.approvedBy;

  delete targetLog.approvedById;

  delete targetLog.approvedByRole;


  /*
    취소 이력 기록
  */
  targetLog.approvalCancelledAt =
    now;


  targetLog.approvalCancelledBy =
    currentUser.name;


  targetLog.approvalCancelledById =
    currentUser.employeeNo;


  targetLog.approvalCancelledFrom =
    previousStatus;


  targetLog.lastModifiedBy =
    currentUser.name;


  targetLog.lastModifiedById =
    currentUser.employeeNo;


  targetLog.updatedAt =
    now;


  persistLogs();


  renderLogTable();

  updateShiftMemberCardStates();


  openLogDetail(
    targetLog
  );


  showToast(
    previousStatus ===
      "결재완료"
      ? "완료된 결재를 취소했습니다. 작성자가 다시 수정할 수 있습니다."
      : "결재요청을 취소했습니다. 업무일지를 다시 수정할 수 있습니다."
  );
}


/* =========================================================
  기존 상세보기 함수 보존
========================================================= */

const openLogDetailBeforeApprovalActions =
  openLogDetail;


/* =========================================================
  결재 버튼 표시가 적용된 상세보기
========================================================= */

openLogDetail =
  function openLogDetail(
    log
  ) {
    openLogDetailBeforeApprovalActions(
      log
    );


    updateShiftLogDetailActionButtons(
      log
    );
  };


/* =========================================================
  상세보기 결재 버튼 이벤트 초기화

  기존 결재확인 버튼을 복제하여
  이전 클릭 이벤트를 완전히 제거한 뒤 새 기능을 연결한다.
========================================================= */

function initializeShiftLogDetailApprovalActions() {
  const oldApproveButton =
    document.getElementById(
      "approveFromDetailButton"
    );


  if (
    !oldApproveButton
  ) {
    return;
  }


  /*
    기존 approveCurrentDetailLog 이벤트 제거
  */
  const newApproveButton =
    oldApproveButton.cloneNode(
      true
    );


  oldApproveButton.replaceWith(
    newApproveButton
  );


  /*
    elements 참조도 새 버튼으로 갱신한다.
  */
  elements.approveFromDetailButton =
    newApproveButton;


  newApproveButton.textContent =
    "결재완료";


  newApproveButton.hidden =
    true;


  newApproveButton.disabled =
    true;


  newApproveButton.addEventListener(
    "click",
    completeCurrentDetailShiftLogApproval
  );


  const cancelApprovalButton =
    ensureCancelApprovalDetailButton();


  cancelApprovalButton
    ?.addEventListener(
      "click",
      cancelCurrentDetailShiftLogApproval
    );
}


document.addEventListener(
  "DOMContentLoaded",
  initializeShiftLogDetailApprovalActions
);

/* =========================================================
  업무일지 상태 표시 통일

  신규 상태:
  - 임시저장
  - 결재요청
  - 결재완료
  - 저장완료

  기존 상태 호환:
  - 작성중   → 임시저장
  - 작성완료 → 결재요청
========================================================= */


/* =========================================================
  화면에 표시할 상태명
========================================================= */

function getShiftLogStatusDisplayName(
  status
) {
  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      status
    );


  const displayNameMap = {
    임시저장:
      "임시저장",

    결재요청:
      "결재요청",

    결재완료:
      "결재완료",

    저장완료:
      "저장완료"
  };


  return (
    displayNameMap[
      normalizedStatus
    ] ||
    normalizedStatus ||
    "임시저장"
  );
}


/* =========================================================
  상태별 공통 CSS 클래스

  기존 CSS 클래스 이름을 최대한 재사용한다.
========================================================= */

getStatusClass =
  function getStatusClass(
    status
  ) {
    const normalizedStatus =
      normalizeShiftLogApprovalStatus(
        status
      );


    const statusClassMap = {
      임시저장:
        "is-writing",

      결재요청:
        "is-requested",

      결재완료:
        "is-approved",

      저장완료:
        "is-complete"
    };


    return (
      statusClassMap[
        normalizedStatus
      ] ||
      "is-writing"
    );
  };


/* =========================================================
  기존 목록 행 생성 함수 보존
========================================================= */

const createLogRowHtmlBeforeStatusDisplay =
  createLogRowHtml;


/* =========================================================
  목록 상태명을 통일한 행 생성 함수

  실제 원본 데이터는 변경하지 않고
  화면에 전달하는 복사본의 상태만 정규화한다.
========================================================= */

createLogRowHtml =
  function createLogRowHtml(
    log
  ) {
    const displayLog = {
      ...log,

      status:
        getShiftLogStatusDisplayName(
          log?.status
        )
    };


    let rowHtml =
      createLogRowHtmlBeforeStatusDisplay(
        displayLog
      );


    const isSuperAdmin =
      isCurrentUserSuperAdmin();


    const isLegacyLog =
      isReadOnlyLegacyShiftLog(
        log
      );


    const isAuthor =
      isCurrentUserShiftLogAuthor(
        log
      );


    const normalizedStatus =
      normalizeShiftLogApprovalStatus(
        log?.status
      );


    const normalizedRole =
      normalizeMemberLogRole(
        log?.role
      );


    let canDeleteLog =
      false;


    /*
      최고관리자는 관리 가능한 일지를
      기존 권한대로 삭제할 수 있다.
    */
    if (
      isSuperAdmin
    ) {
      canDeleteLog =
        isLegacyLog
          ? isSuperAdminManageableLegacyLog(
              log
            )
          : true;

    /*
      일반 사용자는 본인이 작성한
      업무일지만 삭제할 수 있다.
    */
    } else if (
      !isLegacyLog &&
      isAuthor
    ) {
      if (
        normalizedRole ===
          "파트장"
      ) {
        canDeleteLog =
          isCurrentShiftLogLeader() &&
          normalizedStatus ===
            "저장완료";

      } else {
        canDeleteLog =
          normalizedStatus ===
            "임시저장";
      }
    }


    /*
      다른 사람의 작성중 일지는
      이어쓰기만 허용하고 삭제 버튼은 제거한다.
    */
    if (
      !canDeleteLog
    ) {
      rowHtml =
        rowHtml.replace(
          /\s*<button\b(?=[^>]*\bdata-action\s*=\s*"delete")[^>]*>[\s\S]*?<\/button>/i,
          ""
        );
    }


    return rowHtml;
  };


/* =========================================================
  같은 날짜·근무·보직의 최신 업무일지 찾기

  과거 자료가 여러 건 존재해도
  가장 최근 수정된 업무일지 한 건을 사용한다.
========================================================= */

function findLatestShiftMemberLog(
  date,
  shift,
  role
) {
  const normalizedDate =
    String(
      date ||
      ""
    ).trim();


  const normalizedShift =
    String(
      shift ||
      ""
    )
      .trim()
      .toUpperCase();


  const normalizedRole =
    normalizeMemberLogRole(
      role
    );


  const matchedLogs =
    appState.logs
      .filter(
        (
          log
        ) => {
          return (
            String(
              log?.date ||
              ""
            ).trim() ===
              normalizedDate &&

            String(
              log?.shift ||
              ""
            )
              .trim()
              .toUpperCase() ===
              normalizedShift &&

            normalizeMemberLogRole(
              log?.role
            ) ===
              normalizedRole
          );
        }
      )
      .sort(
        (
          firstLog,
          secondLog
        ) => {
          const firstTime =
            new Date(
              firstLog?.updatedAt ||
              firstLog?.createdAt ||
              0
            ).getTime();


          const secondTime =
            new Date(
              secondLog?.updatedAt ||
              secondLog?.createdAt ||
              0
            ).getTime();


          return (
            secondTime -
            firstTime
          );
        }
      );


  return (
    matchedLogs[0] ||
    null
  );
}


/* =========================================================
  근무자 카드 업무일지 상태 설정

  PC 표시:
  - 미작성
  - 임시저장
  - 결재요청
  - 결재완료
  - 저장완료

  모바일 표시:
  - 없음
  - 저장
  - 요청
  - 승인
  - 완료
========================================================= */

function applyShiftMemberCardLogStatus(
  card,
  statusElement,
  log
) {
  if (
    !card ||
    !statusElement
  ) {
    return;
  }


  /* =====================================================
    업무일지가 없는 경우
  ====================================================== */

  if (
    !log
  ) {
    card.dataset.logState =
      "empty";


    card.dataset.approvalStatus =
      "empty";


    card.dataset.mobileStatus =
      "없음";


    statusElement.textContent =
      "미작성";


    statusElement.dataset.mobileStatus =
      "없음";


    statusElement.title =
      "미작성";


    statusElement.className =
      [
        "shift-member-card__status",
        "is-empty"
      ].join(
        " "
      );


    return;
  }


  /* =====================================================
    실제 저장 상태
  ====================================================== */

  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  const desktopStatusText =
    getShiftLogStatusDisplayName(
      normalizedStatus
    );


  const statusClassMap = {
    작성중:
      "is-writing",

    임시저장:
      "is-writing",

    작성완료:
      "is-requested",

    결재요청:
      "is-requested",

    결재완료:
      "is-approved",

    저장완료:
      "is-complete",

    완료:
      "is-complete"
  };


  const mobileStatusMap = {
    작성중:
      "저장",

    임시저장:
      "저장",

    작성완료:
      "요청",

    결재요청:
      "요청",

    결재완료:
      "승인",

    저장완료:
      "완료",

    완료:
      "완료"
  };


  const statusClass =
    statusClassMap[
      normalizedStatus
    ] ||
    "is-writing";


  const mobileStatusText =
    mobileStatusMap[
      normalizedStatus
    ] ||
    "저장";


  /* =====================================================
    카드 상태값
  ====================================================== */

  card.dataset.logState =
    "existing";


  card.dataset.approvalStatus =
    normalizedStatus;


  card.dataset.mobileStatus =
    mobileStatusText;


  /* =====================================================
    상태 표시

    PC:
    textContent 사용

    모바일:
    CSS에서 data-mobile-status 사용
  ====================================================== */

  statusElement.textContent =
    desktopStatusText;


  statusElement.dataset.mobileStatus =
    mobileStatusText;


  statusElement.title =
    desktopStatusText;


  statusElement.className = [
    "shift-member-card__status",
    statusClass
  ].join(
    " "
  );
}

/* =========================================================
  근무자 카드 상태 전체 갱신 최종본

  표시 항목:
  - 보직
  - 작성자 이름
  - 대근 배지
  - 결재 상태

  결재 상태:
  - 미작성
  - 임시저장
  - 결재요청
  - 결재완료
  - 저장완료
========================================================= */

updateShiftMemberCardStates =
  function updateShiftMemberCardStates() {
    const selectedDate =
      formatInputDate(
        appState.selectedDate
      );


    const selectedShift =
      String(
        appState.selectedShift ||
        ""
      )
        .trim()
        .toUpperCase();


    const shiftMemberCards = [
      ...document.querySelectorAll(
        ".shift-member-card"
      )
    ];


    shiftMemberCards.forEach(
      (
        card
      ) => {
        const role =
          normalizeMemberLogRole(
            card.dataset.role ||
            ""
          );


        const roleElement =
          card.querySelector(
            ".shift-member-card__role"
          );


        const nameElement =
          card.querySelector(
            ".shift-member-card__name"
          );


        const nameWrapElement =
          card.querySelector(
            ".shift-member-card__name-wrap"
          ) ||
          nameElement?.parentElement ||
          null;


        const teamElement =
          card.querySelector(
            ".shift-member-card__team"
          );


        const statusElement =
          card.querySelector(
            ".shift-member-card__status"
          );


        /*
          보직명 복원

          HTML 내용이 비워졌거나 다른 코드에서
          변경되어도 data-role 값을 기준으로 다시 표시한다.
        */
        if (
          roleElement
        ) {
          roleElement.textContent =
            role;
        }


        /*
          근무파트는 카드 내부에서 표시하지 않는다.

          현재 파트는 근무자 현황 제목 옆에서만 표시한다.
        */
        if (
          teamElement
        ) {
          teamElement.textContent =
            "";

          teamElement.hidden =
            true;
        }


        /*
          이전 렌더링에서 생성한 대근 배지 제거
        */
        card
          .querySelectorAll(
            ".shift-member-card__substitute"
          )
          .forEach(
            (
              badge
            ) => {
              badge.remove();
            }
          );


        /*
          날짜·근무·보직이 같은
          가장 최근 업무일지 찾기
        */
        const existingLog =
          findLatestShiftMemberLog(
            selectedDate,
            selectedShift,
            role
          );


        /*
          작성된 업무일지가 없는 경우
        */
        if (
          !existingLog
        ) {
          if (
            nameElement
          ) {
            nameElement.textContent =
              "";
          }


          card.dataset.logState =
            "empty";


          card.dataset.approvalStatus =
            "empty";


          if (
            statusElement
          ) {
            statusElement.textContent =
              "미작성";


            statusElement.className =
              "shift-member-card__status is-empty";
          }


          card.setAttribute(
            "aria-label",
            `${role} 업무일지 작성`
          );


          return;
        }


        /*
          업무일지 작성자 이름 표시
        */
        const authorName =
          String(
            existingLog.author ||
            existingLog.authorName ||
            existingLog.writerName ||
            existingLog.writer_name ||
            ""
          ).trim();


        if (
          nameElement
        ) {
          nameElement.textContent =
            authorName;
        }


        /*
          대근 업무일지 표시
        */
        const isSubstitute =
          existingLog.isSubstitute ===
            true ||
          existingLog.isSubstitute ===
            "true" ||
          existingLog.is_substitute ===
            true ||
          Number(
            existingLog.isSubstitute ??
            existingLog.is_substitute ??
            0
          ) ===
            1;


        if (
          isSubstitute &&
          nameWrapElement
        ) {
          const substituteBadge =
            document.createElement(
              "span"
            );


          substituteBadge.className =
            "shift-member-card__substitute";


          substituteBadge.textContent =
            "대근";


          nameWrapElement.appendChild(
            substituteBadge
          );
        }


        /*
          결재 상태 표시
        */
        if (
          statusElement
        ) {
          applyShiftMemberCardLogStatus(
            card,
            statusElement,
            existingLog
          );
        }


        card.setAttribute(
          "aria-label",
          [
            role,
            authorName,
            getShiftLogStatusDisplayName(
              existingLog.status
            ),
            "업무일지 열기"
          ]
            .filter(Boolean)
            .join(" ")
        );
      }
    );
  };


/* =========================================================
  현재 화면 상태 즉시 갱신
========================================================= */

function refreshShiftLogStatusDisplays() {
  if (
    typeof renderLogTable ===
      "function"
  ) {
    renderLogTable();
  }


  updateShiftMemberCardStates();


  const currentDetailLog =
    typeof getCurrentDetailShiftLog ===
      "function"
      ? getCurrentDetailShiftLog()
      : null;


  if (
    currentDetailLog &&
    typeof updateShiftLogDetailActionButtons ===
      "function"
  ) {
    updateShiftLogDetailActionButtons(
      currentDetailLog
    );
  }
}


document.addEventListener(
  "DOMContentLoaded",
  () => {
    window.requestAnimationFrame(
      refreshShiftLogStatusDisplays
    );
  }
);

/* =========================================================
  업무일지 결재 이력

  기록 대상:
  - 임시저장
  - 결재요청
  - 저장완료
  - 결재완료
  - 결재취소

  저장 위치:
  log.approvalHistory
========================================================= */


/* =========================================================
  결재 이력 배열 정규화
========================================================= */

function normalizeShiftLogApprovalHistory(
  history
) {
  if (
    !Array.isArray(
      history
    )
  ) {
    return [];
  }


  return history
    .map(
      (
        historyItem
      ) => {
        if (
          !historyItem ||
          typeof historyItem !==
            "object"
        ) {
          return null;
        }


        const action =
          String(
            historyItem.action ||
            ""
          ).trim();


        const at =
          String(
            historyItem.at ||
            historyItem.createdAt ||
            ""
          ).trim();


        if (
          !action
        ) {
          return null;
        }


        return {
          id:
            String(
              historyItem.id ||
              ""
            ).trim() ||
            [
              "approval-history",
              Date.now(),
              Math.random()
                .toString(36)
                .slice(2, 9)
            ].join("-"),

          action,

          previousStatus:
            String(
              historyItem.previousStatus ||
              ""
            ).trim(),

          nextStatus:
            String(
              historyItem.nextStatus ||
              ""
            ).trim(),

          userId:
            String(
              historyItem.userId ||
              historyItem.employeeNo ||
              ""
            ).trim(),

          userName:
            String(
              historyItem.userName ||
              historyItem.name ||
              ""
            ).trim(),

          accountRole:
            String(
              historyItem.accountRole ||
              historyItem.role ||
              ""
            ).trim(),

          at:
            at ||
            new Date()
              .toISOString()
        };
      }
    )
    .filter(Boolean);
}


/* =========================================================
  결재 이력 한 건 생성
========================================================= */

function createShiftLogApprovalHistoryItem(
  action,
  options = {}
) {
  const {
    previousStatus = "",
    nextStatus = ""
  } = options;


  const currentUser =
    getCurrentShiftLogUserIdentity();


  return {
    id: [
      "approval-history",
      Date.now(),
      Math.random()
        .toString(36)
        .slice(2, 9)
    ].join("-"),

    action:
      String(
        action ||
        ""
      ).trim(),

    previousStatus:
      previousStatus
        ? normalizeShiftLogApprovalStatus(
            previousStatus
          )
        : "",

    nextStatus:
      nextStatus
        ? normalizeShiftLogApprovalStatus(
            nextStatus
          )
        : "",

    userId:
      String(
        currentUser.employeeNo ||
        ""
      ).trim(),

    userName:
      String(
        currentUser.name ||
        ""
      ).trim(),

    accountRole:
      normalizeShiftLogAccountRole(
        currentUser.role
      ),

    at:
      new Date()
        .toISOString()
  };
}


/* =========================================================
  중복 이력 방지

  같은 사용자·행동·상태가 매우 짧은 시간 안에
  반복 저장되면 한 건만 유지한다.
========================================================= */

function isDuplicateShiftLogApprovalHistory(
  history,
  newHistoryItem
) {
  const safeHistory =
    normalizeShiftLogApprovalHistory(
      history
    );


  const latestItem =
    safeHistory[
      safeHistory.length - 1
    ];


  if (
    !latestItem
  ) {
    return false;
  }


  const latestTime =
    new Date(
      latestItem.at
    ).getTime();


  const newTime =
    new Date(
      newHistoryItem.at
    ).getTime();


  const timeDifference =
    Math.abs(
      newTime -
      latestTime
    );


  return (
    latestItem.action ===
      newHistoryItem.action &&

    latestItem.userId ===
      newHistoryItem.userId &&

    latestItem.previousStatus ===
      newHistoryItem.previousStatus &&

    latestItem.nextStatus ===
      newHistoryItem.nextStatus &&

    timeDifference <
      2000
  );
}


/* =========================================================
  업무일지에 결재 이력 추가
========================================================= */

function appendShiftLogApprovalHistory(
  log,
  action,
  options = {}
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    return log;
  }


  const previousHistory =
    normalizeShiftLogApprovalHistory(
      log.approvalHistory
    );


  const newHistoryItem =
    createShiftLogApprovalHistoryItem(
      action,
      options
    );


  if (
    isDuplicateShiftLogApprovalHistory(
      previousHistory,
      newHistoryItem
    )
  ) {
    log.approvalHistory =
      previousHistory;

    return log;
  }


  log.approvalHistory = [
    ...previousHistory,
    newHistoryItem
  ];


  return log;
}


/* =========================================================
  저장 직전 기존 업무일지 찾기
========================================================= */

function getEditingShiftLogBeforeSave() {
  const editingId =
    String(
      elements.logEditorForm
        ?.dataset
        ?.editingId ||
      ""
    ).trim();


  if (
    !editingId
  ) {
    return null;
  }


  return (
    appState.logs.find(
      (
        log
      ) => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          editingId
        );
      }
    ) ||
    null
  );
}


/* =========================================================
  기존 최종 데이터 수집 함수 보존
========================================================= */

const collectEditorDataBeforeApprovalHistory =
  collectEditorData;


/* =========================================================
  결재 이력이 적용된 최종 데이터 수집 함수

  신규 작성:
  첫 저장 행동을 기록한다.

  기존 수정:
  이전 이력을 그대로 유지하고,
  상태가 변경된 경우에만 새 이력을 추가한다.
========================================================= */

collectEditorData =
  function collectEditorData(
    requestedStatus
  ) {
    const previousLog =
      getEditingShiftLogBeforeSave();


    const collectedLog =
      collectEditorDataBeforeApprovalHistory(
        requestedStatus
      );


    if (
      !collectedLog ||
      typeof collectedLog !==
        "object"
    ) {
      return collectedLog;
    }


    const previousStatus =
      previousLog
        ? normalizeShiftLogApprovalStatus(
            previousLog.status
          )
        : "";


    const nextStatus =
      normalizeShiftLogApprovalStatus(
        collectedLog.status
      );


    collectedLog.approvalHistory =
      normalizeShiftLogApprovalHistory(
        previousLog?.approvalHistory ||
        collectedLog.approvalHistory
      );


    /*
      신규 업무일지

      첫 저장 행동은 반드시 기록한다.
    */
    if (
      !previousLog
    ) {
      appendShiftLogApprovalHistory(
        collectedLog,
        nextStatus,
        {
          previousStatus:
            "",

          nextStatus
        }
      );


      return collectedLog;
    }


    /*
      기존 업무일지 상태가 바뀐 경우
    */
    if (
      previousStatus !==
      nextStatus
    ) {
      appendShiftLogApprovalHistory(
        collectedLog,
        nextStatus,
        {
          previousStatus,

          nextStatus
        }
      );


      return collectedLog;
    }


    /*
      같은 상태에서 내용만 수정한 경우

      이력을 과도하게 늘리지 않도록
      별도의 결재 이력은 추가하지 않는다.
    */
    return collectedLog;
  };


/* =========================================================
  파트장 결재완료 함수 보존
========================================================= */

const completeCurrentDetailShiftLogApprovalBeforeHistory =
  completeCurrentDetailShiftLogApproval;


/* =========================================================
  결재완료 이력 추가

  기존 결재완료 함수 실행 후
  실제 상태가 결재완료로 바뀐 경우에만 기록한다.
========================================================= */

completeCurrentDetailShiftLogApproval =
  function completeCurrentDetailShiftLogApproval() {
    const targetLogBefore =
      getCurrentDetailShiftLog();


    const previousStatus =
      normalizeShiftLogApprovalStatus(
        targetLogBefore?.status
      );


    completeCurrentDetailShiftLogApprovalBeforeHistory();


    const targetLogAfter =
      getCurrentDetailShiftLog();


    if (
      !targetLogAfter
    ) {
      return;
    }


    const nextStatus =
      normalizeShiftLogApprovalStatus(
        targetLogAfter.status
      );


    if (
      previousStatus ===
        nextStatus ||
      nextStatus !==
        "결재완료"
    ) {
      return;
    }


    appendShiftLogApprovalHistory(
      targetLogAfter,
      "결재완료",
      {
        previousStatus,

        nextStatus
      }
    );


    persistLogs();

    renderLogTable();

    updateShiftMemberCardStates();

    openLogDetail(
      targetLogAfter
    );
  };


/* =========================================================
  결재취소 함수 보존
========================================================= */

const cancelCurrentDetailShiftLogApprovalBeforeHistory =
  cancelCurrentDetailShiftLogApproval;


/* =========================================================
  결재취소 이력 추가

  결재취소 후 상태는 임시저장이지만
  이력 action은 "결재취소"로 기록한다.
========================================================= */

cancelCurrentDetailShiftLogApproval =
  function cancelCurrentDetailShiftLogApproval() {
    const targetLogBefore =
      getCurrentDetailShiftLog();


    const previousStatus =
      normalizeShiftLogApprovalStatus(
        targetLogBefore?.status
      );


    cancelCurrentDetailShiftLogApprovalBeforeHistory();


    const targetLogAfter =
      getCurrentDetailShiftLog();


    if (
      !targetLogAfter
    ) {
      return;
    }


    const nextStatus =
      normalizeShiftLogApprovalStatus(
        targetLogAfter.status
      );


    if (
      previousStatus ===
        nextStatus ||
      nextStatus !==
        "임시저장"
    ) {
      return;
    }


    appendShiftLogApprovalHistory(
      targetLogAfter,
      "결재취소",
      {
        previousStatus,

        nextStatus
      }
    );


    persistLogs();

    renderLogTable();

    updateShiftMemberCardStates();

    openLogDetail(
      targetLogAfter
    );
  };


/* =========================================================
  결재 행동 표시 이름
========================================================= */

function getShiftLogApprovalHistoryActionLabel(
  historyItem
) {
  const action =
    String(
      historyItem?.action ||
      ""
    ).trim();


  if (
    action ===
      "결재취소"
  ) {
    const previousStatus =
      normalizeShiftLogApprovalStatus(
        historyItem.previousStatus
      );


    return (
      previousStatus ===
        "결재완료"
        ? "완료된 결재 취소"
        : "결재요청 취소"
    );
  }


  return getShiftLogStatusDisplayName(
    action
  );
}


/* =========================================================
  결재 이력 역할 표시
========================================================= */

function getShiftLogApprovalHistoryRoleLabel(
  accountRole
) {
  const normalizedRole =
    String(
      accountRole ||
      ""
    )
      .trim()
      .toLowerCase();


  if (
    normalizedRole ===
      "leader" ||
    normalizedRole ===
      "admin"
  ) {
    return "파트장";
  }


  if (
    normalizedRole ===
      "super_admin" ||
    normalizedRole ===
      "superadmin"
  ) {
    return "최고관리자";
  }


  return "파트원";
}


/* =========================================================
  상세보기 결재 이력 HTML
========================================================= */

function createShiftLogApprovalHistoryHtml(
  log
) {
  const history =
    normalizeShiftLogApprovalHistory(
      log?.approvalHistory
    );


  /*
    과거 업무일지 또는 아직 이력이 없는 기존 자료
  */
  if (
    !history.length
  ) {
    return `
      <section
        class="detail-section shift-log-approval-history"
        data-shift-log-approval-history
      >
        <div class="detail-section__header">
          <h3>
            결재 이력
          </h3>

          <span class="detail-count">
            0건
          </span>
        </div>

        <div class="shift-log-approval-history__empty">
          저장된 결재 이력이 없습니다.
        </div>
      </section>
    `;
  }


  const orderedHistory = [
    ...history
  ].sort(
    (
      firstItem,
      secondItem
    ) => {
      return (
        new Date(
          secondItem.at
        ).getTime() -
        new Date(
          firstItem.at
        ).getTime()
      );
    }
  );


  return `
    <section
      class="detail-section shift-log-approval-history"
      data-shift-log-approval-history
    >
      <div class="detail-section__header">
        <h3>
          결재 이력
        </h3>

        <span class="detail-count">
          ${orderedHistory.length}건
        </span>
      </div>


      <div class="shift-log-approval-history__list">
        ${orderedHistory
          .map(
            (
              historyItem
            ) => {
              const actionLabel =
                getShiftLogApprovalHistoryActionLabel(
                  historyItem
                );


              const userName =
                String(
                  historyItem.userName ||
                  "사용자"
                ).trim();


              const userId =
                String(
                  historyItem.userId ||
                  ""
                ).trim();


              const roleLabel =
                getShiftLogApprovalHistoryRoleLabel(
                  historyItem.accountRole
                );


              const userText =
                userId
                  ? `${userName} (${userId})`
                  : userName;


              return `
                <article
                  class="shift-log-approval-history__item"
                >
                  <div
                    class="shift-log-approval-history__action"
                  >
                    ${escapeHtml(
                      actionLabel
                    )}
                  </div>


                  <div
                    class="shift-log-approval-history__person"
                  >
                    <strong>
                      ${escapeHtml(
                        userText
                      )}
                    </strong>

                    <span>
                      ${escapeHtml(
                        roleLabel
                      )}
                    </span>
                  </div>


                  <time
                    class="shift-log-approval-history__time"
                    datetime="${escapeHtml(
                      historyItem.at
                    )}"
                  >
                    ${escapeHtml(
                      formatDateTime(
                        historyItem.at
                      )
                    )}
                  </time>
                </article>
              `;
            }
          )
          .join("")}
      </div>
    </section>
  `;
}


/* =========================================================
  상세보기 결재 이력 숨김

  결재 이력 데이터 저장과
  결재 기능은 그대로 유지하고,
  상세 화면에만 표시하지 않는다.
========================================================= */

function renderShiftLogApprovalHistoryInDetail(
  log
) {
  const detailContent =
    elements.logDetailContent ||
    document.getElementById(
      "logDetailContent"
    );


  if (!detailContent) {
    return;
  }


  detailContent
    .querySelectorAll(
      "[data-shift-log-approval-history]"
    )
    .forEach(
      historyElement => {
        historyElement.remove();
      }
    );
}



/* =========================================================
  업무일지 상세보기 단일 실행 · 재진입 방지 최종본

  - 최초 상세보기 함수만 1회 실행
  - 중복 래퍼 호출 제거
  - 연속 클릭 및 재진입 차단
  - 버튼 처리 오류가 나도 열린 상세창 유지
========================================================= */

let isOpeningLogDetail =
  false;


openLogDetail =
  function openLogDetail(
    log
  ) {
    if (
      isOpeningLogDetail
    ) {
      return;
    }


    if (
      !log ||
      typeof log !==
        "object"
    ) {
      showToast(
        "업무일지 정보를 확인할 수 없습니다."
      );

      return;
    }


    isOpeningLogDetail =
      true;


    try {
      /*
        다른 래퍼를 다시 거치지 않고
        최초 상세보기 함수만 직접 실행한다.
      */
      openLogDetailBeforeApprovalActions(
        log
      );


      /*
        권한별 하단 버튼을 한 번만 정리한다.
      */
      updateShiftLogDetailActionButtons(
        log
      );


      /*
        상세창에서는 결재 이력을 표시하지 않는다.
      */
      renderShiftLogApprovalHistoryInDetail(
        log
      );

    } catch (
      error
    ) {
      console.error(
        "업무일지 상세보기 열기 실패:",
        error
      );


      const detailModal =
        elements.logDetailModal ||
        document.getElementById(
          "logDetailModal"
        );


      const detailIsOpen =
        detailModal?.classList.contains(
          "is-open"
        ) ===
        true;


      /*
        상세창이 이미 열렸다면
        버튼 처리 중 오류이므로 창은 유지한다.
      */
      if (
        !detailIsOpen
      ) {
        appState.currentDetailLogId =
          null;


        const otherOpenModal =
          document.querySelector(
            ".modal-backdrop.is-open"
          );


        if (
          !otherOpenModal
        ) {
          document.body.classList.remove(
            "modal-open"
          );
        }


        showToast(
          "상세보기를 열지 못했습니다. 다시 시도해 주세요."
        );
      }

    } finally {
      isOpeningLogDetail =
        false;
    }
  };
  
  /* =========================================================
  결재 버튼 이벤트를 결재 이력 포함 함수로 재연결
========================================================= */

function reconnectShiftLogApprovalHistoryEvents() {

  const approveButton =
    document.getElementById(
      "approveFromDetailButton"
    );

  if (approveButton) {

    const newApproveButton =
      approveButton.cloneNode(true);

    approveButton.replaceWith(
      newApproveButton
    );

    elements.approveFromDetailButton =
      newApproveButton;

    newApproveButton.addEventListener(
      "click",
      completeCurrentDetailShiftLogApproval
    );
  }


  const cancelButton =
    document.getElementById(
      "cancelApprovalFromDetailButton"
    );

  if (cancelButton) {

    const newCancelButton =
      cancelButton.cloneNode(true);

    cancelButton.replaceWith(
      newCancelButton
    );

    elements.cancelApprovalFromDetailButton =
      newCancelButton;

    newCancelButton.addEventListener(
      "click",
      cancelCurrentDetailShiftLogApproval
    );
  }


  const printButton =
    document.getElementById(
      "printLogDetailButton"
    );

  if (printButton) {

    const newPrintButton =
      printButton.cloneNode(true);

    printButton.replaceWith(
      newPrintButton
    );

    elements.printLogDetailButton =
      newPrintButton;

    newPrintButton.addEventListener(
      "click",
      () => {
        window.print();
      }
    );
  }
}


document.addEventListener(
  "DOMContentLoaded",
  reconnectShiftLogApprovalHistoryEvents
);

/* =========================================================
  D1 공용 업무일지 최종 연결

  기존 화면·과거 일지 변환 함수는 유지하고
  신규 업무일지만 D1 공용 저장소에 연결한다.
========================================================= */

class ShiftLogApiError extends Error {
  constructor(
    message,
    options = {}
  ) {
    super(
      message
    );


    this.name =
      "ShiftLogApiError";


    this.status =
      Number(
        options.status ||
        0
      );


    this.currentLog =
      options.currentLog ||
      null;


    this.isConflict =
      this.status ===
        409 ||
      options.isConflict ===
        true;
  }
}


/* =========================================================
  D1 업무일지 API 공통 요청
========================================================= */

async function requestShiftLogApi(
  path = "",
  options = {}
) {
  const method =
    String(
      options.method ||
      "GET"
    ).toUpperCase();


  const requestOptions = {
    method,


    headers:
      getShiftLogAuthHeaders(
        options.body
          ? {
              "Content-Type":
                "application/json"
            }
          : {}
      )
  };


  if (
    options.body
  ) {
    requestOptions.body =
      JSON.stringify(
        options.body
      );
  }


  const response =
    await fetch(
      `${SHIFT_LOGS_API_URL}${path}`,
      requestOptions
    );


  let result = {};


  try {
    result =
      await response.json();

  } catch {
    throw new ShiftLogApiError(
      "업무일지 서버 응답을 확인할 수 없습니다.",
      {
        status:
          response.status
      }
    );
  }


  /*
    세션이 만료되었으면
    로그인 화면으로 이동한다.
  */
  if (
    response.status ===
      401
  ) {
    clearCurrentUser();


    openLoginScreen();
  }


  if (
    !response.ok ||
    result.ok ===
      false
  ) {
    throw new ShiftLogApiError(
      result.message ||
      "업무일지 서버 요청에 실패했습니다.",
      {
        status:
          response.status,


        currentLog:
          result.currentLog ||
          null,


        isConflict:
          result.conflict ===
          true
      }
    );
  }


  return result;
}


/* =========================================================
  날짜·근무·보직 기준 업무일지 고유 그룹 키
========================================================= */

function getShiftLogGroupKey(
  log
) {
  return [
    String(
      log?.date ||
      ""
    ).trim(),


    String(
      log?.shift ||
      ""
    )
      .trim()
      .toUpperCase(),


    normalizeMemberLogRole(
      log?.role
    )
  ].join(
    "||"
  );
}


/* =========================================================
  D1 공용 업무일지 여부
========================================================= */

function isSharedD1ShiftLog(
  log
) {
  return (
    String(
      log?.source ||
      ""
    )
      .trim()
      .toLowerCase() ===
      "shared-d1" ||


    Number.isInteger(
      Number(
        log?.serverRevision
      )
    )
  );
}


/* =========================================================
  D1 업무일지 데이터 정규화
========================================================= */

function normalizeSharedShiftLog(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    return null;
  }


  const normalizedLog = {
    ...log,


    id:
      String(
        log.id ||
        ""
      ).trim(),


    date:
      String(
        log.date ||
        ""
      ).trim(),


    shift:
      String(
        log.shift ||
        ""
      )
        .trim()
        .toUpperCase(),


    role:
      normalizeMemberLogRole(
        log.role
      ),


    status:
      normalizeShiftLogApprovalStatus(
        log.status
      ),


    serverRevision:
      Number(
        log.serverRevision
      ) ||
      1,


    source:
      "shared-d1"
  };


  if (
    !normalizedLog.id ||
    !normalizedLog.date ||
    !normalizedLog.shift ||
    !normalizedLog.role
  ) {
    return null;
  }


  return normalizedLog;
}


/* =========================================================
  저장된 D1 업무일지를 현재 화면 상태에 반영
========================================================= */

function replaceSharedShiftLogInState(
  savedLog
) {
  const normalizedLog =
    normalizeSharedShiftLog(
      savedLog
    );


  if (
    !normalizedLog
  ) {
    return null;
  }


  const savedId =
    String(
      normalizedLog.id
    );


  const savedGroupKey =
    getShiftLogGroupKey(
      normalizedLog
    );


  appState.logs =
    appState.logs.filter(
      currentLog => {
        /*
          과거 연동 업무일지는 유지한다.
        */
        if (
          isReadOnlyLegacyShiftLog(
            currentLog
          )
        ) {
          return true;
        }


        const isSameId =
          String(
            currentLog?.id ||
            ""
          ) ===
            savedId;


        const isSameGroup =
          getShiftLogGroupKey(
            currentLog
          ) ===
            savedGroupKey;


        return !(
          isSameId ||
          isSameGroup
        );
      }
    );


  appState.logs.unshift(
    normalizedLog
  );


  return normalizedLog;
}


/* =========================================================
  삭제된 D1 업무일지를 현재 화면 상태에서 제거
========================================================= */

function removeSharedShiftLogFromState(
  logId
) {
  const normalizedId =
    String(
      logId ||
      ""
    ).trim();


  appState.logs =
    appState.logs.filter(
      log => {
        return (
          String(
            log?.id ||
            ""
          ).trim() !==
          normalizedId
        );
      }
    );
}


/* =========================================================
  D1 공용 업무일지 불러오기
========================================================= */

async function loadSharedShiftLogsFromServer(
  query = ""
) {
  if (
    !getShiftLogSessionToken()
  ) {
    return [];
  }


  const result =
    await requestShiftLogApi(
      query
    );


  return (
    Array.isArray(
      result.logs
    )
      ? result.logs
      : []
  )
    .map(
      normalizeSharedShiftLog
    )
    .filter(Boolean);
}


/* =========================================================
  D1 공용 업무일지 저장·수정
========================================================= */

async function saveShiftLogToServer(
  log,
  options = {}
) {
  const result =
    await requestShiftLogApi(
      "",
      {
        method:
          "POST",


        body: {
          action:
            options.action ||
            "save",


          expectedRevision:
            Number(
              options.expectedRevision ??
              log?.serverRevision ??
              0
            ),


          log
        }
      }
    );


  return normalizeSharedShiftLog(
    result.log
  );
}

/* =========================================================
  D1 공용 업무일지 삭제
========================================================= */

async function deleteShiftLogFromServer(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    throw new ShiftLogApiError(
      "삭제할 업무일지 정보가 없습니다."
    );
  }


  const logId =
    String(
      log.id ||
      ""
    ).trim();


  const serverRevision =
    Number(
      log.serverRevision
    );


  if (
    !logId
  ) {
    throw new ShiftLogApiError(
      "삭제할 업무일지 ID를 확인할 수 없습니다."
    );
  }


  if (
    !Number.isInteger(
      serverRevision
    ) ||
    serverRevision < 1
  ) {
    throw new ShiftLogApiError(
      "업무일지의 서버 버전을 확인할 수 없습니다."
    );
  }


  const searchParams =
    new URLSearchParams({
      id:
        logId,

      revision:
        String(
          serverRevision
        )
    });


  const result =
    await requestShiftLogApi(
      `?${searchParams.toString()}`,
      {
        method:
          "DELETE"
      }
    );


  return String(
    result.deletedId ||
    logId
  ).trim();
}

/* =========================================================
  브라우저에 저장된 신규 업무일지 이전 자료 정리

  - 과거 연동 업무일지 제외
  - 예시 업무일지 제외
  - 같은 날짜·근무·보직은 최신 자료 1건만 유지
========================================================= */

function readLocalShiftLogsForMigration() {
  const savedLogs =
    localStorage.getItem(
      STORAGE_KEYS.logs
    );


  if (
    !savedLogs
  ) {
    return [];
  }


  try {
    const parsedLogs =
      JSON.parse(
        savedLogs
      );


    if (
      !Array.isArray(
        parsedLogs
      )
    ) {
      return [];
    }


    const sampleLogIds =
      new Set([
        "sample-1",
        "sample-2",
        "sample-3"
      ]);


    const latestLogMap =
      new Map();


    [
      ...parsedLogs
    ]
      .filter(
        log => {
          return (
            log &&
            typeof log ===
              "object" &&


            !isReadOnlyLegacyShiftLog(
              log
            ) &&


            !sampleLogIds.has(
              String(
                log.id ||
                ""
              )
            )
          );
        }
      )
      .sort(
        (
          firstLog,
          secondLog
        ) => {
          const firstTime =
            new Date(
              firstLog.updatedAt ||
              firstLog.createdAt ||
              0
            ).getTime();


          const secondTime =
            new Date(
              secondLog.updatedAt ||
              secondLog.createdAt ||
              0
            ).getTime();


          return (
            secondTime -
            firstTime
          );
        }
      )
      .forEach(
        log => {
          const groupKey =
            getShiftLogGroupKey(
              log
            );


          if (
            groupKey !==
              "||||" &&


            !latestLogMap.has(
              groupKey
            )
          ) {
            latestLogMap.set(
              groupKey,
              log
            );
          }
        }
      );


    return [
      ...latestLogMap.values()
    ];

  } catch (
    error
  ) {
    console.error(
      "브라우저 업무일지 이전 자료 분석 실패:",
      error
    );


    return [];
  }
}


/* =========================================================
  기존 브라우저 업무일지를 D1으로 이전
========================================================= */

async function migrateLocalShiftLogsToServer(
  serverLogs
) {
  const localLogs =
    readLocalShiftLogsForMigration();


  /*
    브라우저에 이전할 업무일지가 없으면
    서버 자료만 그대로 사용한다.
  */
  if (
    localLogs.length ===
      0
  ) {
    return {
      logs:
        serverLogs,


      completed:
        true
    };
  }


  const serverLogMap =
    new Map(
      serverLogs.map(
        log => {
          return [
            getShiftLogGroupKey(
              log
            ),


            log
          ];
        }
      )
    );


  let migrationCompleted =
    true;


  for (
    const localLog of
    localLogs
  ) {
    const groupKey =
      getShiftLogGroupKey(
        localLog
      );


    /*
      같은 날짜·근무·보직 일지가
      이미 D1에 있으면 서버 자료를 유지한다.
    */
    if (
      serverLogMap.has(
        groupKey
      )
    ) {
      continue;
    }


    try {
      const migratedLog =
        await saveShiftLogToServer(
          localLog,
          {
            action:
              "migrate",


            expectedRevision:
              0
          }
        );


      if (
        migratedLog
      ) {
        serverLogMap.set(
          groupKey,
          migratedLog
        );
      }

    } catch (
      error
    ) {
      /*
        다른 사용자가 먼저 같은 업무일지를
        서버에 저장했다면 최신 서버 자료를 사용한다.
      */
      if (
        error instanceof
          ShiftLogApiError &&


        error.isConflict &&


        error.currentLog
      ) {
        const currentLog =
          normalizeSharedShiftLog(
            error.currentLog
          );


        if (
          currentLog
        ) {
          serverLogMap.set(
            groupKey,
            currentLog
          );


          continue;
        }
      }


      migrationCompleted =
        false;


      console.error(
        "브라우저 업무일지 D1 이전 실패:",
        error
      );
    }
  }


  /*
    모든 이전 작업이 성공한 경우에만
    브라우저의 기존 업무일지를 삭제한다.

    실패 자료가 있으면 다음 로그인 때
    다시 이전할 수 있도록 그대로 남긴다.
  */
  if (
    migrationCompleted
  ) {
    localStorage.removeItem(
      STORAGE_KEYS.logs
    );
  }


  return {
    logs: [
      ...serverLogMap.values()
    ],


    completed:
      migrationCompleted
  };
}


/* =========================================================
  D1 업무일지 최신 상태 다시 불러오기
========================================================= */

async function refreshSharedShiftLogsInState(
  options = {}
) {
  if (
    !getShiftLogSessionToken()
  ) {
    return [];
  }


  /*
    기존 과거 연동 업무일지는 유지한다.
  */
  const preservedLegacyLogs =
    appState.logs.filter(
      isReadOnlyLegacyShiftLog
    );


  const serverLogs =
    await loadSharedShiftLogsFromServer(
      options.query ||
      ""
    );


  appState.logs = [
    ...serverLogs,
    ...preservedLegacyLogs
  ];


  return serverLogs;
}


/* =========================================================
  기존 localStorage 업무일지 저장 중지

  기존 코드에 persistLogs() 호출이 남아 있어도
  신규 업무일지를 localStorage에 다시 저장하지 않는다.
========================================================= */

persistLogs =
  function persistLogs() {
    return false;
  };


/* =========================================================
  D1 공용 업무일지 불러오기

  최초 로그인:
  - D1 업무일지 불러오기
  - 기존 브라우저 업무일지 D1 이전
  - 과거 연동 업무일지 유지

  이후 로그인:
  - D1 공용 업무일지만 불러오기
========================================================= */

loadLogs =
  async function loadLogs() {
    if (
      !getShiftLogSessionToken()
    ) {
      appState.logs = [];


      return [];
    }


    try {
      const serverLogs =
        await loadSharedShiftLogsFromServer();


      const migrationResult =
        await migrateLocalShiftLogsToServer(
          serverLogs
        );


      /*
        기존 과거 연동 업무일지는
        appState에 그대로 유지한다.
      */
      const preservedLegacyLogs =
        appState.logs.filter(
          isReadOnlyLegacyShiftLog
        );


      appState.logs = [
        ...migrationResult.logs,
        ...preservedLegacyLogs
      ];


      console.log(
        `D1 공용 신규 업무일지 ${migrationResult.logs.length}건을 불러왔습니다.`
      );


      return migrationResult.logs;

    } catch (
      error
    ) {
      console.error(
        "D1 공용 업무일지 불러오기 실패:",
        error
      );


      if (
        error instanceof
          ShiftLogApiError &&


        error.status ===
          401
      ) {
        showToast(
          "로그인 세션이 만료되었습니다. 다시 로그인해 주세요."
        );

      } else {
        showToast(
          error.message ||
          "공용 업무일지를 불러오지 못했습니다."
        );
      }


      return [];
    }
  };

  /* =========================================================
  D1 업무일지 저장·수정·삭제·권한 연결
========================================================= */

function setShiftLogSavingState(
  isSaving
) {
  if (
    !elements.logEditorForm
  ) {
    return;
  }


  elements.logEditorForm
    .setAttribute(
      "aria-busy",
      isSaving
        ? "true"
        : "false"
    );


  [
    getShiftLogEditorSubmitButton(),
    elements.saveDraftButton,
    elements.requestApprovalButton
  ]
    .filter(Boolean)
    .forEach(
      button => {
        button.disabled =
          isSaving;
      }
    );


  if (
    !isSaving
  ) {
    updateLogEditorActionButtons();
  }
}


/* =========================================================
  다른 사용자가 먼저 수정한 경우 충돌 처리
========================================================= */

function handleShiftLogConflict(
  error
) {
  const latestLog =
    normalizeSharedShiftLog(
      error?.currentLog
    );


  /*
    다른 사용자가 먼저 저장한 최신 일지가 있으면
    현재 화면의 자료를 최신 서버 자료로 교체한다.
  */
  if (
    latestLog
  ) {
    replaceSharedShiftLogInState(
      latestLog
    );


    renderLogTable();


    updateShiftMemberCardStates();


    /*
      오래된 내용이 열린 수정창을 그대로 두면
      다시 저장할 때 최신 내용을 덮어쓸 수 있다.

      수정창을 닫고 최신 상세보기로 전환한다.
    */
    closeLogEditor();


    openLogDetail(
      latestLog
    );
  }


  showToast(
    error?.message ||
    (
      latestLog
        ? "다른 사용자가 먼저 저장했습니다. 최신 업무일지를 다시 확인해 주세요."
        : "다른 사용자가 먼저 수정했습니다. 업무일지를 다시 불러와 주세요."
    )
  );
}


/* =========================================================
  현재 업무일지 D1 저장·수정
========================================================= */

saveCurrentLog =
  async function saveCurrentLog(
    requestedStatus,
    options = {}
  ) {
    const {
      closeAfterSave = true
    } = options;


    if (
      elements.logEditorForm
        ?.getAttribute(
          "aria-busy"
        ) ===
        "true"
    ) {
      return null;
    }


    if (
      !elements.logEditorForm ||
      !elements.logEditorForm
        .reportValidity()
    ) {
      return null;
    }


    const log =
      collectEditorData(
        requestedStatus
      );


    const hasEntryContent =
      Array.isArray(
        log.entries
      ) &&
      log.entries.some(
        entry => {
          return Boolean(
            String(
              entry?.content ||
              ""
            ).trim()
          );
        }
      );


    if (
      !String(
        log.operationStatus ||
        ""
      ).trim() &&
      !hasEntryContent &&
      !String(
        log.note ||
        ""
      ).trim()
    ) {
      showToast(
        "운전 현황 또는 업무 내용을 입력해 주세요."
      );


      return null;
    }


    const editingId =
      String(
        elements.logEditorForm
          .dataset.editingId ||
        ""
      ).trim();


    const normalizedRole =
      normalizeMemberLogRole(
        log.role
      );


    const baseLog =
      appState.logs
        .filter(
          currentLog => {
            if (
              isReadOnlyLegacyShiftLog(
                currentLog
              )
            ) {
              return false;
            }


            if (
              editingId &&
              String(
                currentLog?.id ||
                ""
              ) ===
                editingId
            ) {
              return true;
            }


            return (
              String(
                currentLog?.date ||
                ""
              ).trim() ===
                String(
                  log.date ||
                  ""
                ).trim() &&


              String(
                currentLog?.shift ||
                ""
              )
                .trim()
                .toUpperCase() ===
                String(
                  log.shift ||
                  ""
                )
                  .trim()
                  .toUpperCase() &&


              normalizeMemberLogRole(
                currentLog?.role
              ) ===
                normalizedRole
            );
          }
        )
        .sort(
          (
            firstLog,
            secondLog
          ) => {
            return (
              Number(
                secondLog.serverRevision ||
                0
              ) -
              Number(
                firstLog.serverRevision ||
                0
              )
            );
          }
        )[0] ||
      null;


    if (
      baseLog
    ) {
      log.id =
        baseLog.id;


      log.createdAt =
        baseLog.createdAt ||
        log.createdAt;


      log.serverRevision =
        Number(
          baseLog.serverRevision
        ) ||
        0;
    }


    setShiftLogSavingState(
      true
    );


    try {
      const savedLog =
        await saveShiftLogToServer(
          log,
          {
            action:
              "save",


            expectedRevision:
              Number(
                baseLog?.serverRevision ||
                0
              )
          }
        );


      if (
        !savedLog
      ) {
        throw new Error(
          "저장된 업무일지를 확인할 수 없습니다."
        );
      }


      replaceSharedShiftLogInState(
        savedLog
      );


      localStorage.removeItem(
        STORAGE_KEYS.draft
      );


      elements.logEditorForm
        .dataset.editingId =
        savedLog.id;


      appState.selectedDate =
        new Date(
          `${savedLog.date}T00:00:00`
        );


      appState.selectedShift =
        savedLog.shift;


      renderSelectedDate();


      renderLogTable();


      updateShiftMemberCardStates();


      if (
        closeAfterSave
      ) {
        closeLogEditor();
      }


      const savedStatus =
        normalizeShiftLogApprovalStatus(
          savedLog.status
        );


/* =========================================================
  업무일지 저장 완료 안내

  임시저장:
  저장 문구만 표시하고 작성창 유지

  결재요청·파트장 저장:
  각각의 완료 문구 표시
========================================================= */

showToast(
  savedStatus ===
    "결재요청"
    ? "결재요청이 완료되었습니다."
    : (
        savedStatus ===
          "저장완료"
          ? "저장이 완료되었습니다."
          : "저장이 되었습니다."
      )
);


      return savedLog;

    } catch (
      error
    ) {
      console.error(
        "공용 업무일지 저장 실패:",
        error
      );


      if (
        error instanceof
          ShiftLogApiError &&
        error.isConflict
      ) {
        handleShiftLogConflict(
          error
        );

      } else {
        showToast(
          error.message ||
          "업무일지를 저장하지 못했습니다."
        );
      }


      return null;

    } finally {
      setShiftLogSavingState(
        false
      );
    }
  };


/* =========================================================
  임시저장 D1 연결
========================================================= */

saveDraft =
  async function saveDraft() {
    if (
      !elements.logEditorForm ||
      !elements.logEditorForm
        .reportValidity()
    ) {
      return null;
    }


    const hasEntryContent =
      appState.editorEntries.some(
        entry => {
          return Boolean(
            String(
              entry?.content ||
              ""
            ).trim()
          );
        }
      );


    const hasOperationStatus =
      Boolean(
        String(
          elements.operationStatusSnapshot
            ?.value ||
          elements.operationStatus
            ?.value ||
          appState.currentOperationStatus
            ?.content ||
          ""
        ).trim()
      );


    const hasNote =
      Boolean(
        String(
          elements.logNote
            ?.value ||
          ""
        ).trim()
      );


    if (
      !hasEntryContent &&
      !hasOperationStatus &&
      !hasNote
    ) {
      showToast(
        "운전 현황 또는 업무 내용을 입력해 주세요."
      );


      return null;
    }


    return saveCurrentLog(
      "작성중",
      {
        closeAfterSave:
          false
      }
    );
  };


/* =========================================================
  업무일지 D1 삭제
========================================================= */

deleteLogById =
  async function deleteLogById(
    logId
  ) {
    const targetLog =
      appState.logs.find(
        log => {
          return (
            String(
              log?.id ||
              ""
            ) ===
            String(
              logId ||
              ""
            )
          );
        }
      );


    if (
      !targetLog
    ) {
      showToast(
        "삭제할 업무일지를 찾을 수 없습니다."
      );


      return;
    }


    if (
      isReadOnlyLegacyShiftLog(
        targetLog
      )
    ) {
      showToast(
        "과거 업무일지는 삭제할 수 없습니다."
      );


      return;
    }


    const shouldDelete =
      window.confirm(
        [
          "이 업무일지를 삭제하시겠습니까?",
          "",
          `날짜: ${targetLog.date || "-"}`,
          `근무: ${targetLog.shift || "-"}`,
          `보직: ${targetLog.role || "-"}`,
          `작성자: ${targetLog.author || "-"}`
        ].join(
          "\n"
        )
      );


    if (
      !shouldDelete
    ) {
      return;
    }


    try {
      await deleteShiftLogFromServer(
        targetLog
      );


      removeSharedShiftLogFromState(
        targetLog.id
      );


      renderLogTable();


      updateShiftMemberCardStates();


      showToast(
        "업무일지를 삭제했습니다."
      );

    } catch (
      error
    ) {
      console.error(
        "공용 업무일지 삭제 실패:",
        error
      );


      if (
        error instanceof
          ShiftLogApiError &&
        error.isConflict
      ) {
        handleShiftLogConflict(
          error
        );

      } else {
        showToast(
          error.message ||
          "업무일지를 삭제하지 못했습니다."
        );
      }
    }
  };


/* =========================================================
  업무일지 수정 권한

  - 최고관리자: 모든 보직과 상태 수정 가능
  - 일반 사용자: 본인이 작성한 임시저장 일지만 가능
  - 파트장: 본인의 저장완료 일지 수정 가능
  - 과거 연동 일지: 수정 불가
========================================================= */

canCurrentUserEditShiftLog =
  function canCurrentUserEditShiftLog(
    log
  ) {
    if (
      !log ||
      typeof log !==
        "object"
    ) {
      return false;
    }


    const isSuperAdmin =
      isCurrentUserSuperAdmin();


    /*
      공용 D1 업무일지는 최고관리자가
      작성자·보직·결재 상태와 관계없이 수정 가능
    */
    if (
      isSuperAdmin &&
      isSharedD1ShiftLog(
        log
      )
    ) {
      return true;
    }


    /*
      7월 21일까지의 과거 연동 업무일지는
      조회 전용
    */
    if (
      isReadOnlyLegacyShiftLog(
        log
      )
    ) {
      return false;
    }


    /*
      공용 D1 판정값이 없는 신규 업무일지도
      최고관리자는 수정 가능
    */
    if (
      isSuperAdmin
    ) {
      return true;
    }


    const currentUser =
      getCurrentShiftLogUserIdentity();


    const currentEmployeeNo =
      String(
        currentUser?.employeeNo ||
        ""
      ).trim();


    if (
      !currentEmployeeNo
    ) {
      return false;
    }


    /*
      일반 사용자는 본인 업무일지만 수정 가능
    */
    if (
      !isCurrentUserShiftLogAuthor(
        log
      )
    ) {
      return false;
    }


    const normalizedStatus =
      normalizeShiftLogApprovalStatus(
        log.status
      );


    if (
      normalizedStatus ===
        "임시저장"
    ) {
      return true;
    }


    return (
      isCurrentShiftLogLeader() &&
      normalizeMemberLogRole(
        log.role
      ) ===
        "파트장" &&
      normalizedStatus ===
        "저장완료"
    );
  };

/* =========================================================
  업무일지 편집창 권한 유형

  중요:
  로그인 계정 권한이 아니라
  현재 작성·수정 중인 업무일지의 보직을 기준으로
  저장 버튼 구성을 결정한다.

  파트장:
  저장

  TGO · BCO1 · BCO2 · TO · BO1 · BO2:
  임시저장 · 결재요청

  최고관리자가 다른 보직 일지를 수정하더라도
  해당 보직의 일반 작성 절차를 그대로 사용한다.
========================================================= */

getCurrentShiftLogPermissionType =
  function getCurrentShiftLogPermissionType() {
    const currentEditorRole =
      normalizeMemberLogRole(
        elements.logRole?.value || ""
      );

    if (
      currentEditorRole ===
      "파트장"
    ) {
      return "leader";
    }

    return "member";
  };


/* =========================================================
  편집창 저장 버튼 표시

  파트장:
  저장 버튼 표시
  임시저장·결재요청 숨김

  일반 보직:
  저장 버튼 숨김
  임시저장·결재요청 표시

  최고관리자 수정도 현재 업무일지 보직 기준으로 처리
========================================================= */

updateLogEditorActionButtons =
  function updateLogEditorActionButtons() {
    const permissionType =
      getCurrentShiftLogPermissionType();

    const submitButton =
      getShiftLogEditorSubmitButton();

    const saveDraftButton =
      elements.saveDraftButton ||
      document.getElementById(
        "saveDraftButton"
      );

    const requestApprovalButton =
      elements.requestApprovalButton ||
      document.getElementById(
        "requestApprovalButton"
      );

    const isLeaderMode =
      permissionType ===
      "leader";

    /*
      파트장 전용 저장 버튼
    */
    if (
      submitButton
    ) {
      submitButton.hidden =
        !isLeaderMode;

      submitButton.disabled =
        !isLeaderMode;

      submitButton.textContent =
        "저장";

      submitButton.title =
        isLeaderMode
          ? "파트장 업무일지를 저장완료 상태로 저장합니다."
          : "";
    }

    /*
      일반 보직 임시저장
    */
    if (
      saveDraftButton
    ) {
      saveDraftButton.hidden =
        isLeaderMode;

      saveDraftButton.disabled =
        isLeaderMode;

      saveDraftButton.textContent =
        "임시저장";
    }

    /*
      일반 보직 결재요청
    */
    if (
      requestApprovalButton
    ) {
      requestApprovalButton.hidden =
        isLeaderMode;

      requestApprovalButton.disabled =
        isLeaderMode;

      requestApprovalButton.textContent =
        "결재요청";
    }
  };


/* =========================================================
  편집창 저장 버튼 권한별 표시
========================================================= */

updateLogEditorActionButtons =
  function updateLogEditorActionButtons() {
    const permissionType =
      getCurrentShiftLogPermissionType();


    const submitButton =
      getShiftLogEditorSubmitButton();


    const saveDraftButton =
      elements.saveDraftButton ||
      document.getElementById(
        "saveDraftButton"
      );


    const requestApprovalButton =
      elements.requestApprovalButton ||
      document.getElementById(
        "requestApprovalButton"
      );


    const isLeaderMode =
      permissionType ===
        "leader";


    const isSuperAdminEditMode =
      permissionType ===
        "super_admin_edit";


    const showSubmitButton =
      isLeaderMode ||
      isSuperAdminEditMode;


    if (
      submitButton
    ) {
      submitButton.hidden =
        !showSubmitButton;


      submitButton.disabled =
        !showSubmitButton;


      submitButton.textContent =
        isSuperAdminEditMode
          ? "수정 저장"
          : "저장";


      submitButton.title =
        isSuperAdminEditMode
          ? "원 작성자와 결재 상태를 유지하고 수정 내용을 저장합니다."
          : (
              isLeaderMode
                ? "파트장 업무일지를 저장완료 상태로 저장합니다."
                : ""
            );
    }


    if (
      saveDraftButton
    ) {
      saveDraftButton.hidden =
        showSubmitButton;


      saveDraftButton.disabled =
        showSubmitButton;


      saveDraftButton.textContent =
        "임시저장";
    }


    if (
      requestApprovalButton
    ) {
      requestApprovalButton.hidden =
        showSubmitButton;


      requestApprovalButton.disabled =
        showSubmitButton;


      requestApprovalButton.textContent =
        "결재요청";
    }
  };

  /* =========================================================
  D1 업무일지 결재·결재취소 연결
========================================================= */

async function changeShiftLogApprovalOnServer(
  targetLog,
  action
) {
  const savedLog =
    await saveShiftLogToServer(
      targetLog,
      {
        action,


        expectedRevision:
          Number(
            targetLog.serverRevision
          ) ||
          0
      }
    );


  if (
    savedLog
  ) {
    replaceSharedShiftLogInState(
      savedLog
    );
  }


  return savedLog;
}


/* =========================================================
  업무일지 결재완료

  - 파트장 또는 최고관리자만 가능
  - 결재요청 상태의 파트원 업무일지만 가능
  - 결재 이력과 결재자 정보는 서버에서 기록
========================================================= */

completeCurrentDetailShiftLogApproval =
  async function completeCurrentDetailShiftLogApproval() {
    const targetLog =
      getCurrentDetailShiftLog();


    if (
      !targetLog
    ) {
      showToast(
        "결재할 업무일지를 찾을 수 없습니다."
      );


      return null;
    }


    if (
      !(
        isCurrentShiftLogLeader() ||
        isCurrentUserSuperAdmin()
      )
    ) {
      showToast(
        "파트장 또는 최고관리자만 업무일지를 결재할 수 있습니다."
      );


      return null;
    }


    if (
      normalizeMemberLogRole(
        targetLog.role
      ) ===
        "파트장"
    ) {
      showToast(
        "파트장 업무일지는 결재 대상이 아닙니다."
      );


      return null;
    }


    if (
      normalizeShiftLogApprovalStatus(
        targetLog.status
      ) !==
        "결재요청"
    ) {
      showToast(
        "결재요청 상태의 업무일지만 결재할 수 있습니다."
      );


      return null;
    }


    const shouldApprove =
      window.confirm(
        [
          "이 업무일지를 결재완료 처리하시겠습니까?",
          "",
          `작성일: ${targetLog.date || "-"}`,
          `근무: ${getShiftDisplayName(
            targetLog.shift
          )}`,
          `보직: ${targetLog.role || "-"}`,
          `작성자: ${targetLog.author || "-"}`
        ].join(
          "\n"
        )
      );


    if (
      !shouldApprove
    ) {
      return null;
    }


    try {
      const savedLog =
        await changeShiftLogApprovalOnServer(
          targetLog,
          "approve"
        );


      renderLogTable();


      updateShiftMemberCardStates();


      openLogDetail(
        savedLog
      );


      showToast(
        "업무일지 결재가 완료되었습니다."
      );


      return savedLog;

    } catch (
      error
    ) {
      console.error(
        "업무일지 결재 실패:",
        error
      );


      if (
        error instanceof
          ShiftLogApiError &&
        error.isConflict
      ) {
        handleShiftLogConflict(
          error
        );

      } else {
        showToast(
          error.message ||
          "업무일지를 결재하지 못했습니다."
        );
      }


      return null;
    }
  };


/* =========================================================
  기존 상세보기 결재 함수 연결
========================================================= */

approveCurrentDetailLog =
  function approveCurrentDetailLog() {
    return completeCurrentDetailShiftLogApproval();
  };


/* =========================================================
  업무일지 결재취소

  - 본인: 결재요청 상태 취소 가능
  - 파트장·최고관리자:
    결재요청 또는 결재완료 상태 취소 가능
  - 취소 후 임시저장 상태로 변경
========================================================= */

cancelCurrentDetailShiftLogApproval =
  async function cancelCurrentDetailShiftLogApproval() {
    const targetLog =
      getCurrentDetailShiftLog();


    if (
      !targetLog
    ) {
      showToast(
        "결재취소할 업무일지를 찾을 수 없습니다."
      );


      return null;
    }


    if (
      !canCurrentUserCancelShiftLogApproval(
        targetLog
      )
    ) {
      showToast(
        "현재 계정으로는 이 업무일지의 결재를 취소할 수 없습니다."
      );


      return null;
    }


    const previousStatus =
      normalizeShiftLogApprovalStatus(
        targetLog.status
      );


    const shouldCancel =
      window.confirm(
        previousStatus ===
          "결재완료"
          ? [
              "완료된 결재를 취소하시겠습니까?",
              "",
              "업무일지는 임시저장 상태로 돌아갑니다."
            ].join(
              "\n"
            )
          : [
              "결재요청을 취소하시겠습니까?",
              "",
              "업무일지는 임시저장 상태로 돌아갑니다."
            ].join(
              "\n"
            )
      );


    if (
      !shouldCancel
    ) {
      return null;
    }


    try {
      const savedLog =
        await changeShiftLogApprovalOnServer(
          targetLog,
          "cancel"
        );


      renderLogTable();


      updateShiftMemberCardStates();


      openLogDetail(
        savedLog
      );


      showToast(
        previousStatus ===
          "결재완료"
          ? "완료된 결재를 취소했습니다."
          : "결재요청을 취소했습니다."
      );


      return savedLog;

    } catch (
      error
    ) {
      console.error(
        "업무일지 결재취소 실패:",
        error
      );


      if (
        error instanceof
          ShiftLogApiError &&
        error.isConflict
      ) {
        handleShiftLogConflict(
          error
        );

      } else {
        showToast(
          error.message ||
          "업무일지 결재를 취소하지 못했습니다."
        );
      }


      return null;
    }
  };

