  /* =========================================================
  2026-07-22 이후 기존 업무일지 D1 자동 이전

  - 2026-07-21까지는 조회 전용 유지
  - 이후 legacy 일지는 공용 D1으로 자동 이전
  - 기존 작성자 유지
  - 이전 완료 후 최고관리자 수정 가능
========================================================= */

async function migrateEditableLegacyLogsForSelectedDate() {
  const selectedDate =
    formatInputDate(
      appState.selectedDate
    );


  /*
    2026-07-21까지는 확정된 과거 이력이므로
    기존대로 조회 전용으로 유지한다.
  */
  if (
    selectedDate <=
    "2026-07-21"
  ) {
    return [];
  }


  const currentUser =
    loadCurrentUser();


  const currentEmployeeNo =
    getShiftLogUserEmployeeNo(
      currentUser
    );


  if (
    !currentEmployeeNo ||
    !getShiftLogSessionToken()
  ) {
    return [];
  }


  const legacyLogs =
    appState.logs.filter(
      log => {
        return (
          String(
            log?.date ||
            ""
          ).trim() ===
            selectedDate &&

          isReadOnlyLegacyShiftLog(
            log
          )
        );
      }
    );


  if (
    legacyLogs.length ===
    0
  ) {
    return [];
  }


  const sharedGroupKeys =
    new Set(
      appState.logs
        .filter(
          isSharedD1ShiftLog
        )
        .map(
          getShiftLogGroupKey
        )
    );


  const migratedLogs = [];


  for (
    const legacyLog of
    legacyLogs
  ) {
    const groupKey =
      getShiftLogGroupKey(
        legacyLog
      );


    /*
      같은 날짜·근무·보직의 D1 일지가
      이미 존재하면 다시 이전하지 않는다.
    */
    if (
      sharedGroupKeys.has(
        groupKey
      )
    ) {
      continue;
    }


    const canMigrateLog =
      currentEmployeeNo ===
        FORCED_SUPER_ADMIN_EMPLOYEE_NO ||

      isCurrentUserSuperAdmin() ||

      isCurrentUserShiftLogAuthor(
        legacyLog
      );


    if (
      !canMigrateLog
    ) {
      continue;
    }


    /*
      기존 작성자와 상태를 유지한 채
      D1 이전용 자료를 만든다.
    */
    const migrationLog = {
      ...legacyLog,

      author:
        String(
          legacyLog.author ||
          ""
        ).trim(),

      authorId:
        String(
          legacyLog.authorId ||
          legacyLog.writerId ||
          ""
        ).trim(),

      authorRole:
        String(
          legacyLog.authorRole ||
          ""
        ).trim(),

      status:
        normalizeShiftLogApprovalStatus(
          legacyLog.status
        )
    };


    try {
      const migratedLog =
        await saveShiftLogToServer(
          migrationLog,
          {
            action:
              "migrate",

            expectedRevision:
              0
          }
        );


      if (
        migratedLog
      ) {
        replaceSharedShiftLogInState(
          migratedLog
        );


        sharedGroupKeys.add(
          groupKey
        );


        migratedLogs.push(
          migratedLog
        );
      }

    } catch (
      error
    ) {
      /*
        다른 PC에서 먼저 이전했다면
        서버의 최신 D1 일지를 사용한다.
      */
      if (
        error instanceof
          ShiftLogApiError &&

        error.isConflict &&

        error.currentLog
      ) {
        const currentLog =
          normalizeSharedShiftLog(
            error.currentLog
          );


        if (
          currentLog
        ) {
          replaceSharedShiftLogInState(
            currentLog
          );


          sharedGroupKeys.add(
            groupKey
          );


          migratedLogs.push(
            currentLog
          );
        }


        continue;
      }


      console.error(
        "현재 날짜 기존 업무일지 D1 이전 실패:",
        error
      );
    }
  }


  /*
    D1 일지가 준비된 보직의
    legacy 중복 행만 목록에서 제거한다.

    이전에 실패한 자료는 조회용으로 남긴다.
  */
  appState.logs =
    appState.logs.filter(
      log => {
        const isSameDateLegacy =
          String(
            log?.date ||
            ""
          ).trim() ===
            selectedDate &&

          isReadOnlyLegacyShiftLog(
            log
          );


        if (
          !isSameDateLegacy
        ) {
          return true;
        }


        return !sharedGroupKeys.has(
          getShiftLogGroupKey(
            log
          )
        );
      }
    );


  if (
    migratedLogs.length >
    0
  ) {
    renderLogTable();


    updateShiftMemberCardStates();
  }


  return migratedLogs;
}


/*
  기존 legacy 조회 함수 보존
*/
const loadLegacyLogsForSelectedDateBeforeEditableMigration =
  loadLegacyLogsForSelectedDate;


/*
  legacy 조회가 끝난 뒤
  수정 가능한 날짜의 자료를 D1으로 자동 이전한다.
*/
loadLegacyLogsForSelectedDate =
  async function loadLegacyLogsForSelectedDate() {
    const legacyLogs =
      await loadLegacyLogsForSelectedDateBeforeEditableMigration();


    await migrateEditableLegacyLogsForSelectedDate();


    return legacyLogs;
  };

  /* =========================================================
  최고관리자 legacy 업무일지 수정·삭제 최종 연결

  - 2026-07-21까지: 조회 전용
  - 2026-07-22 이후: 최고관리자 수정·삭제 가능
  - 버튼 클릭 시 해당 일지를 D1으로 전환
========================================================= */

function isSuperAdminManageableLegacyLog(
  log
) {
  return (
    isReadOnlyLegacyShiftLog(
      log
    ) &&

    String(
      log?.date ||
      ""
    ).trim() >
      "2026-07-21"
  );
}


/* =========================================================
  legacy 업무일지 1건을 D1으로 전환
========================================================= */

async function convertLegacyLogForSuperAdminManagement(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    throw new Error(
      "업무일지 정보를 확인할 수 없습니다."
    );
  }


  if (
    !isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    return log;
  }


  if (
    !isCurrentUserSuperAdmin()
  ) {
    throw new Error(
      "최고관리자만 이 업무일지를 수정할 수 있습니다."
    );
  }


  if (
    !isSuperAdminManageableLegacyLog(
      log
    )
  ) {
    throw new Error(
      "2026년 7월 21일까지의 과거 업무일지는 조회만 가능합니다."
    );
  }


  const migrationLog = {
    ...log,

    author:
      String(
        log.author ||
        log.authorName ||
        log.writerName ||
        ""
      ).trim(),

    authorId:
      String(
        log.authorId ||
        log.writerId ||
        log.writer_id ||
        ""
      ).trim(),

    authorRole:
      String(
        log.authorRole ||
        log.writerRole ||
        log.writer_role ||
        ""
      ).trim(),

    status:
      normalizeShiftLogApprovalStatus(
        log.status
      )
  };


  let sharedLog =
    null;


  try {
    sharedLog =
      await saveShiftLogToServer(
        migrationLog,
        {
          action:
            "migrate",

          expectedRevision:
            0
        }
      );

  } catch (
    error
  ) {
    /*
      이미 같은 날짜·근무·보직의 D1 일지가 있으면
      서버의 현재 자료를 사용한다.
    */
    if (
      error instanceof
        ShiftLogApiError &&

      error.isConflict &&

      error.currentLog
    ) {
      sharedLog =
        normalizeSharedShiftLog(
          error.currentLog
        );

    } else {
      throw error;
    }
  }


  if (
    !sharedLog
  ) {
    throw new Error(
      "업무일지를 수정 가능한 자료로 전환하지 못했습니다."
    );
  }


  const groupKey =
    getShiftLogGroupKey(
      sharedLog
    );


  /*
    전환된 일지와 같은 legacy 중복 행 제거
  */
  appState.logs =
    appState.logs.filter(
      currentLog => {
        return !(
          isReadOnlyLegacyShiftLog(
            currentLog
          ) &&

          getShiftLogGroupKey(
            currentLog
          ) ===
            groupKey
        );
      }
    );


  const normalizedSharedLog =
    replaceSharedShiftLogInState(
      sharedLog
    );


  renderLogTable();

  updateShiftMemberCardStates();


  return (
    normalizedSharedLog ||
    sharedLog
  );
}


/* =========================================================
  수정·삭제 버튼 표시 최종 권한
========================================================= */

canCurrentUserEditShiftLog =
  function canCurrentUserEditShiftLog(
    log
  ) {
    if (
      !log ||
      typeof log !==
        "object"
    ) {
      return false;
    }


    /*
      최고관리자

      - 신규 업무일지는 모든 보직과 상태 수정 가능
      - 관리 가능한 과거 업무일지만 수정 가능
    */
    if (
      isCurrentUserSuperAdmin()
    ) {
      if (
        isReadOnlyLegacyShiftLog(
          log
        )
      ) {
        return isSuperAdminManageableLegacyLog(
          log
        );
      }


      return true;
    }


    /*
      일반 계정은 과거 연동 업무일지 수정 불가
    */
    if (
      isReadOnlyLegacyShiftLog(
        log
      )
    ) {
      return false;
    }


    const currentUser =
      getCurrentShiftLogUserIdentity();


    if (
      !String(
        currentUser?.employeeNo ||
        ""
      ).trim()
    ) {
      return false;
    }


    const normalizedLogRole =
      normalizeMemberLogRole(
        log.role
      );


    const normalizedStatus =
      normalizeShiftLogApprovalStatus(
        log.status
      );


    /*
      파트장 계정

      - 본인이 작성한 파트장 업무일지만 수정 가능
      - 저장완료 상태만 수정 가능
      - 일반 보직 업무일지는 수정 불가
    */
    if (
      isCurrentShiftLogLeader()
    ) {
      return (
        normalizedLogRole ===
          "파트장" &&

        isCurrentUserShiftLogAuthor(
          log
        ) &&

        normalizedStatus ===
          "저장완료"
      );
    }


    /*
      일반회원은 파트장 업무일지 수정 불가
    */
    if (
      normalizedLogRole ===
        "파트장"
    ) {
      return false;
    }


    const editableMemberRoles = [
      "TGO",
      "BCO1",
      "BCO2",
      "TO",
      "BO1",
      "BO2"
    ];


    /*
      일반회원

      - 일반 보직의 작성중 일지는 작성자와 관계없이 수정 가능
      - 결재요청은 먼저 결재취소해야 수정 가능
      - 결재완료는 수정 불가
    */
    return (
      editableMemberRoles.includes(
        normalizedLogRole
      ) &&

      normalizedStatus ===
        "임시저장"
    );
  };  


/* =========================================================
  수정 클릭 시 legacy → D1 전환
========================================================= */

const openLogEditorBeforeLegacyManagement =
  openLogEditor;


openLogEditor =
  async function openLogEditor(
    log = null,
    preset = null
  ) {
    /*
      신규 작성 또는 이미 D1인 일지
    */
    if (
      !log ||

      !isReadOnlyLegacyShiftLog(
        log
      )
    ) {
      return openLogEditorBeforeLegacyManagement(
        log,
        preset
      );
    }


    /*
      수정 권한이 없는 legacy 자료
    */
    if (
      !canCurrentUserEditShiftLog(
        log
      )
    ) {
      return openLogEditorBeforeLegacyManagement(
        log,
        preset
      );
    }


    try {
      const sharedLog =
        await convertLegacyLogForSuperAdminManagement(
          log
        );


      return openLogEditorBeforeLegacyManagement(
        sharedLog,
        preset
      );

    } catch (
      error
    ) {
      console.error(
        "업무일지 수정 준비 실패:",
        error
      );


      showToast(
        error.message ||
        "업무일지를 수정 가능한 상태로 전환하지 못했습니다."
      );


      return null;
    }
  };

