/* =========================================================
  날짜를 YYYY-MM-DD로 반환
========================================================= */

function getRoleNoticeTodayValue() {
  const today =
    new Date();


  return [
    today.getFullYear(),

    String(
      today.getMonth() + 1
    ).padStart(
      2,
      "0"
    ),

    String(
      today.getDate()
    ).padStart(
      2,
      "0"
    )
  ].join("-");
}

/* =========================================================
  공지 표시 기준일

  실제 오늘 날짜가 아니라
  현재 화면에서 선택한 업무일지 기준일을 사용한다.
========================================================= */

function getRoleNoticeReferenceDate() {
  if (
    typeof appState !==
      "undefined" &&
    appState.selectedDate instanceof
      Date &&
    !Number.isNaN(
      appState.selectedDate.getTime()
    )
  ) {
    return formatInputDate(
      appState.selectedDate
    );
  }


  return getRoleNoticeTodayValue();
}


/* =========================================================
  날짜 표시
========================================================= */

function formatRoleNoticeDate(
  value
) {
  const normalizedValue =
    String(
      value ||
      ""
    ).trim();


  if (
    !normalizedValue
  ) {
    return "-";
  }


  const dateMatch =
    normalizedValue.match(
      /^(\d{4})-(\d{2})-(\d{2})/
    );


  if (
    !dateMatch
  ) {
    return normalizedValue;
  }


  return [
    dateMatch[1],
    dateMatch[2],
    dateMatch[3]
  ].join(".");
}


/* =========================================================
  작성일시 표시
========================================================= */

function formatRoleNoticeDateTime(
  value
) {
  const date =
    new Date(
      value
    );


  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return "-";
  }


  return [
    date.getFullYear(),
    ".",
    String(
      date.getMonth() + 1
    ).padStart(
      2,
      "0"
    ),
    ".",
    String(
      date.getDate()
    ).padStart(
      2,
      "0"
    ),
    " ",
    String(
      date.getHours()
    ).padStart(
      2,
      "0"
    ),
    ":",
    String(
      date.getMinutes()
    ).padStart(
      2,
      "0"
    )
  ].join("");
}


/* =========================================================
  공지 데이터 정규화
========================================================= */

function normalizeRoleNotice(
  notice
) {
  const sourceNotice =
    notice &&
    typeof notice ===
      "object"
      ? notice
      : {};


  const role =
    normalizeMemberLogRole(
      sourceNotice.role ||
      sourceNotice.position ||
      sourceNotice.targetRole ||
      sourceNotice.target_role ||
      ""
    );


  return {
    id:
      String(
        sourceNotice.id ||
        sourceNotice.noticeId ||
        sourceNotice.notice_id ||
        ""
      ).trim(),

    role,

    title:
      String(
        sourceNotice.title ||
        ""
      ).trim(),

    content:
      String(
        sourceNotice.content ||
        sourceNotice.body ||
        ""
      )
        .replace(
          /\r\n/g,
          "\n"
        )
        .replace(
          /\r/g,
          "\n"
        )
        .trim(),

    startDate:
      String(
        sourceNotice.startDate ||
        sourceNotice.start_date ||
        ""
      ).slice(
        0,
        10
      ),

    endDate:
      String(
        sourceNotice.endDate ||
        sourceNotice.end_date ||
        ""
      ).slice(
        0,
        10
      ),

    isImportant:
      sourceNotice.isImportant ===
        true ||
      sourceNotice.is_important ===
        true ||
      Number(
        sourceNotice.isImportant ??
        sourceNotice.is_important ??
        0
      ) ===
        1,

    createdBy:
      String(
        sourceNotice.createdBy ||
        sourceNotice.created_by ||
        ""
      ).trim(),

    createdByName:
      String(
        sourceNotice.createdByName ||
        sourceNotice.created_by_name ||
        sourceNotice.author ||
        ""
      ).trim(),

    createdAt:
      String(
        sourceNotice.createdAt ||
        sourceNotice.created_at ||
        ""
      ),

    updatedAt:
      String(
        sourceNotice.updatedAt ||
        sourceNotice.updated_at ||
        sourceNotice.createdAt ||
        sourceNotice.created_at ||
        ""
      )
  };
}

/* =========================================================
  공지 상태 판정

  중요:
  오늘 날짜가 아니라
  현재 화면에서 선택한 업무일지 기준일로 판단한다.
========================================================= */

/* =========================================================
  공지 상태 판정

  현재 화면에서 선택한 업무일지 날짜 기준:

  active:
  시작일 <= 화면 날짜 <= 종료일

  upcoming:
  화면 날짜 < 시작일

  expired:
  종료일 < 화면 날짜
========================================================= */

function getRoleNoticeStatus(
  notice,
  referenceDate =
    getRoleNoticeReferenceDate()
) {
  const startDate =
    String(
      notice?.startDate ||
      ""
    ).trim();


  const endDate =
    String(
      notice?.endDate ||
      ""
    ).trim();


  if (
    startDate &&
    referenceDate <
      startDate
  ) {
    return "upcoming";
  }


  if (
    endDate &&
    referenceDate >
      endDate
  ) {
    return "expired";
  }


  return "active";
}


/* =========================================================
  공지 상태 표시 이름
========================================================= */

function getRoleNoticeStatusLabel(
  status
) {
  const labelMap = {
    active:
      "진행 중",

    upcoming:
      "예정",

    expired:
      "종료"
  };


  return (
    labelMap[
      status
    ] ||
    "진행 중"
  );
}


/* =========================================================
  현재 로그인 사용자의 보직 확인
========================================================= */

function getCurrentUserRoleNoticePosition() {
  const currentUser =
    loadCurrentUser();


  return normalizeMemberLogRole(
    currentUser?.position ||
    currentUser?.jobPosition ||
    currentUser?.job_position ||
    currentUser?.duty ||
    ""
  );
}


/* =========================================================
  보직 공지 관리 권한 최종본

  허용:
  - 로그인한 사용자 전체
  - 파트장·TGO·BCO1·BCO2·TO·BO1·BO2
  - 모든 보직 공지 추가·수정·삭제 가능
========================================================= */

function canCurrentUserManageRoleNotice(
  role
) {
  const currentUser =
    loadCurrentUser();


  if (
    !currentUser
  ) {
    return false;
  }


  const normalizedRole =
    normalizeMemberLogRole(
      role
    );


  return ROLE_NOTICE_ROLES.includes(
    normalizedRole
  );
}


/* =========================================================
  API 응답 읽기
========================================================= */

async function readRoleNoticeApiResponse(
  response
) {
  const responseText =
    await response.text();


  let result = {};


  if (
    responseText.trim()
  ) {
    try {
      result =
        JSON.parse(
          responseText
        );

    } catch {
      throw new Error(
        "공지사항 서버 응답 형식이 올바르지 않습니다."
      );
    }
  }


  if (
    !response.ok ||
    result.ok === false ||
    result.success === false
  ) {
    throw new Error(
      result.message ||
      result.error ||
      `공지사항 요청 실패 (HTTP ${response.status})`
    );
  }


  return result;
}


/* =========================================================
  전체 보직 공지 불러오기

  API 응답 지원:
  {
    notices: []
  }

  {
    items: []
  }

  {
    data: []
  }
========================================================= */

async function loadRoleNotices() {
  if (
    roleNoticeState.isLoading
  ) {
    return roleNoticeState.notices;
  }


  roleNoticeState.isLoading =
    true;


  try {
    const requestUrl =
      new URL(
        ROLE_NOTICE_API_URL,
        window.location.origin
      );


    requestUrl.searchParams.set(
      "_",
      String(
        Date.now()
      )
    );


    const response =
      await fetch(
        requestUrl.toString(),
        {
          method:
            "GET",

          headers:
            typeof getShiftLogAuthHeaders ===
              "function"
              ? getShiftLogAuthHeaders()
              : {
                  Accept:
                    "application/json"
                },

          cache:
            "no-store"
        }
      );


    const result =
      await readRoleNoticeApiResponse(
        response
      );


    const rawNotices =
      Array.isArray(
        result.notices
      )
        ? result.notices
        : (
            Array.isArray(
              result.items
            )
              ? result.items
              : (
                  Array.isArray(
                    result.data
                  )
                    ? result.data
                    : []
                )
          );


    roleNoticeState.notices =
      rawNotices
        .map(
          normalizeRoleNotice
        )
        .filter(
          notice => {
            return (
              notice.id &&
              ROLE_NOTICE_ROLES.includes(
                notice.role
              )
            );
          }
        );


    updateAllRoleNoticeButtons();


    if (
      roleNoticeState.currentRole
    ) {
      renderCurrentRoleNoticeList();
    }


    return roleNoticeState.notices;

  } catch (
    error
  ) {
    console.error(
      "보직별 공지사항 불러오기 실패:",
      error
    );


    roleNoticeState.notices =
      [];


    updateAllRoleNoticeButtons();


    return [];

  } finally {
    roleNoticeState.isLoading =
      false;
  }
}


/* =========================================================
  특정 보직 공지 목록
========================================================= */

function getRoleNoticesByRole(
  role
) {
  const normalizedRole =
    normalizeMemberLogRole(
      role
    );


  return roleNoticeState.notices
    .filter(
      notice => {
        return (
          notice.role ===
          normalizedRole
        );
      }
    )
    .sort(
      (
        firstNotice,
        secondNotice
      ) => {
        /*
          중요 공지 우선
        */
        const importantDifference =
          Number(
            secondNotice.isImportant
          ) -
          Number(
            firstNotice.isImportant
          );


        if (
          importantDifference !==
          0
        ) {
          return importantDifference;
        }


        /*
          최근 수정 공지 우선
        */
        const firstTime =
          new Date(
            firstNotice.updatedAt ||
            firstNotice.createdAt ||
            0
          ).getTime();


        const secondTime =
          new Date(
            secondNotice.updatedAt ||
            secondNotice.createdAt ||
            0
          ).getTime();


        return (
          secondTime -
          firstTime
        );
      }
    );
}

/* =========================================================
  보직 카드의 활성 공지 버튼 갱신

  색상 구분:
  - 일반 공지만 있음:
    has-normal-notice

  - 중요 공지가 하나라도 있음:
    has-important-notice

  - 중요 공지가 있으면 일반 공지보다 우선 표시
========================================================= */

function updateRoleNoticeButton(
  button
) {
  if (
    !button
  ) {
    return;
  }


  const role =
    normalizeMemberLogRole(
      button.dataset.role
    );


  /* =====================================================
    현재 선택 날짜에 활성화된 공지만 가져온다.
  ====================================================== */

  const activeNotices =
    getRoleNoticesByRole(
      role
    ).filter(
      notice => {
        return (
          getRoleNoticeStatus(
            notice
          ) ===
          "active"
        );
      }
    );


  const activeCount =
    activeNotices.length;


  /* =====================================================
    일반·중요 공지 개수
  ====================================================== */

  const importantCount =
    activeNotices.filter(
      notice => {
        return (
          notice.isImportant ===
          true
        );
      }
    ).length;


  const normalCount =
    activeCount -
    importantCount;


  const hasActiveNotice =
    activeCount >
    0;


  /*
    중요 공지가 하나라도 있으면
    중요 공지 색상을 우선 적용한다.
  */
  const hasImportantNotice =
    importantCount >
    0;


  const hasNormalNoticeOnly =
    hasActiveNotice &&
    !hasImportantNotice;


  const icon =
    button.querySelector(
      ".role-notice-button__icon"
    );


  const count =
    button.querySelector(
      "[data-role-notice-count]"
    );


  /* =====================================================
    공지 상태 클래스

    기존 has-active-notice는 유지한다.
  ====================================================== */

  button.classList.toggle(
    "has-active-notice",
    hasActiveNotice
  );


  button.classList.toggle(
    "has-normal-notice",
    hasNormalNoticeOnly
  );


  button.classList.toggle(
    "has-important-notice",
    hasImportantNotice
  );


  /*
    현재 상태를 개발자 도구에서도
    확인할 수 있도록 저장한다.
  */
  button.dataset.noticePriority =
    hasImportantNotice
      ? "important"
      : (
          hasNormalNoticeOnly
            ? "normal"
            : "none"
        );


  /* =====================================================
    접근성 안내 문구
  ====================================================== */

  if (
    hasImportantNotice
  ) {
    button.setAttribute(
      "aria-label",
      [
        `${role} 중요 공지 ${importantCount}건`,

        normalCount >
          0
          ? `일반 공지 ${normalCount}건`
          : "",

        "열기"
      ]
        .filter(
          Boolean
        )
        .join(
          ", "
        )
    );

  } else if (
    hasNormalNoticeOnly
  ) {
    button.setAttribute(
      "aria-label",
      `${role} 일반 공지 ${normalCount}건 열기`
    );

  } else {
    button.setAttribute(
      "aria-label",
      `${role} 공지사항 열기`
    );
  }


  /* =====================================================
    기존 아이콘이 있는 HTML도 대응
  ====================================================== */

  if (
    icon
  ) {
    icon.textContent =
      hasImportantNotice
        ? "!"
        : (
            hasNormalNoticeOnly
              ? "■"
              : "□"
          );
  }


  /* =====================================================
    활성 공지 전체 건수
  ====================================================== */

  if (
    count
  ) {
    count.textContent =
      String(
        activeCount
      );


    count.hidden =
      activeCount ===
      0;
  }
}

/* =========================================================
  전체 공지 버튼 갱신
========================================================= */

function updateAllRoleNoticeButtons() {
  document
    .querySelectorAll(
      "[data-role-notice-button]"
    )
    .forEach(
      updateRoleNoticeButton
    );
}


/* =========================================================
  공지 목록창 열기
========================================================= */

async function openRoleNoticeModal(
  role
) {
  const normalizedRole =
    normalizeMemberLogRole(
      role
    );


  if (
    !ROLE_NOTICE_ROLES.includes(
      normalizedRole
    )
  ) {
    showToast(
      "공지 대상 보직을 확인할 수 없습니다."
    );

    return;
  }


  const noticeElements =
    getRoleNoticeElements();


  if (
    !noticeElements.roleNoticeModal
  ) {
    showToast(
      "보직 공지사항창을 찾을 수 없습니다."
    );

    return;
  }


  roleNoticeState.currentRole =
    normalizedRole;

  roleNoticeState.currentFilter =
    "active";


  if (
    noticeElements.roleNoticeCurrentRole
  ) {
    noticeElements
      .roleNoticeCurrentRole
      .value =
      normalizedRole;
  }


  if (
    noticeElements.roleNoticeModalTitle
  ) {
    noticeElements
      .roleNoticeModalTitle
      .textContent =
      `${normalizedRole} 공지사항`;
  }


  noticeElements
    .filterButtons
    .forEach(
      button => {
        button.classList.toggle(
          "is-active",
          button.dataset
            .roleNoticeFilter ===
            "active"
        );
      }
    );


/*
  보직 공지 새 공지 버튼

  표시:
  - 최고관리자
  - 파트장 계정
  - 현재 공지 대상과 같은 보직 사용자

  숨김:
  - 다른 보직의 일반 사용자
*/
if (
  noticeElements
    .openRoleNoticeEditorButton
) {
  const addButton =
    noticeElements
      .openRoleNoticeEditorButton;


  const canManageCurrentRole =
    canCurrentUserManageRoleNotice(
      normalizedRole
    );


  addButton.hidden =
    !canManageCurrentRole;


  addButton.disabled =
    !canManageCurrentRole;


  addButton.setAttribute(
    "aria-hidden",
    String(
      !canManageCurrentRole
    )
  );


  if (
    canManageCurrentRole
  ) {
    /*
      과거에 설정된 hidden과
      인라인 스타일을 확실히 해제한다.
    */
    addButton.removeAttribute(
      "hidden"
    );


    addButton.style.removeProperty(
      "display"
    );


    addButton.style.removeProperty(
      "visibility"
    );


    addButton.style.removeProperty(
      "opacity"
    );

  } else {
    addButton.setAttribute(
      "hidden",
      ""
    );
  }
}

  /*
    API 응답을 기다리기 전에 모달부터 연다.

    서버 조회가 느리거나 실패하더라도
    버튼 클릭 자체는 즉시 확인할 수 있다.
  */
  if (
    typeof openModal ===
      "function"
  ) {
    openModal(
      noticeElements.roleNoticeModal
    );

  } else {
    noticeElements
      .roleNoticeModal
      .classList
      .add(
        "is-open"
      );

    noticeElements
      .roleNoticeModal
      .setAttribute(
        "aria-hidden",
        "false"
      );

    document.body.classList.add(
      "modal-open"
    );
  }


  if (
    noticeElements.roleNoticeList
  ) {
    noticeElements
      .roleNoticeList
      .setAttribute(
        "aria-busy",
        "true"
      );
  }


  try {
    await loadRoleNotices();

  } finally {
    if (
      noticeElements.roleNoticeList
    ) {
      noticeElements
        .roleNoticeList
        .setAttribute(
          "aria-busy",
          "false"
        );
    }
  }


  renderCurrentRoleNoticeList();
}

/* =========================================================
  공지 목록창 닫기
========================================================= */

function closeRoleNoticeModal() {
  const {
    roleNoticeModal,
    roleNoticeEditorModal
  } =
    getRoleNoticeElements();


  if (
    roleNoticeEditorModal?.classList.contains(
      "is-open"
    )
  ) {
    closeRoleNoticeEditor();
  }


  if (
    !roleNoticeModal
  ) {
    return;
  }


  if (
    typeof closeModal ===
      "function"
  ) {
    closeModal(
      roleNoticeModal
    );

  } else {
    roleNoticeModal
      .classList
      .remove(
        "is-open"
      );

    roleNoticeModal
      .setAttribute(
        "aria-hidden",
        "true"
      );

    document.body.classList.remove(
      "modal-open"
    );
  }


  roleNoticeState.currentRole =
    "";

  roleNoticeState.currentFilter =
    "active";
}


/* =========================================================
  공지 카드 HTML
========================================================= */

function createRoleNoticeCardHtml(
  notice
) {
  const status =
    getRoleNoticeStatus(
      notice
    );


  const canManage =
    canCurrentUserManageRoleNotice(
      notice.role
    );


  const authorText =
    notice.createdByName ||
    notice.createdBy ||
    "작성자 미확인";


  const updatedText =
    formatRoleNoticeDateTime(
      notice.updatedAt ||
      notice.createdAt
    );


  return `
    <article
      class="
        role-notice-card
        ${
          notice.isImportant
            ? "is-important"
            : ""
        }
        ${
          status ===
            "expired"
            ? "is-expired"
            : ""
        }
      "
      data-role-notice-id="${escapeHtml(
        notice.id
      )}"
    >

      <div class="role-notice-card__main">

        <div class="role-notice-card__heading">

          <h3 class="role-notice-card__title">
            ${escapeHtml(
              notice.title ||
              "제목 없음"
            )}
          </h3>

          ${
            notice.isImportant
              ? `
                <span class="role-notice-card__important-badge">
                  중요
                </span>
              `
              : ""
          }

          <span
            class="
              role-notice-card__status
              is-${status}
            "
          >
            ${getRoleNoticeStatusLabel(
              status
            )}
          </span>

        </div>


        <p class="role-notice-card__period">
          ${escapeHtml(
            formatRoleNoticeDate(
              notice.startDate
            )
          )}
          ~
          ${escapeHtml(
            formatRoleNoticeDate(
              notice.endDate
            )
          )}
        </p>


        <p class="role-notice-card__content">
          ${escapeHtml(
            notice.content ||
            ""
          )}
        </p>


        <p class="role-notice-card__meta">
          ${escapeHtml(
            authorText
          )}
          ·
          ${escapeHtml(
            updatedText
          )}
        </p>

      </div>


      ${
        canManage
          ? `
            <div class="role-notice-card__actions">

              <button
                type="button"
                class="role-notice-card__edit-button"
                data-role-notice-edit="${escapeHtml(
                  notice.id
                )}"
              >
                수정
              </button>

              <button
                type="button"
                class="role-notice-card__delete-button"
                data-role-notice-delete="${escapeHtml(
                  notice.id
                )}"
              >
                삭제
              </button>

            </div>
          `
          : ""
      }

    </article>
  `;
}


/* =========================================================
  현재 보직의 공지 목록 출력
========================================================= */

function renderCurrentRoleNoticeList() {
  const noticeElements =
    getRoleNoticeElements();


  const currentRole =
    normalizeMemberLogRole(
      roleNoticeState.currentRole
    );


  if (
    !currentRole ||
    !noticeElements.roleNoticeList
  ) {
    return;
  }


  const allNotices =
    getRoleNoticesByRole(
      currentRole
    );


  const statusCounts = {
    active:
      0,

    upcoming:
      0,

    expired:
      0,

    all:
      allNotices.length
  };


  allNotices.forEach(
    notice => {
      const status =
        getRoleNoticeStatus(
          notice
        );


      if (
        Object.hasOwn(
          statusCounts,
          status
        )
      ) {
        statusCounts[
          status
        ] +=
          1;
      }
    }
  );


  if (
    noticeElements.roleNoticeActiveCount
  ) {
    noticeElements
      .roleNoticeActiveCount
      .textContent =
      `활성 ${statusCounts.active}건`;
  }


  if (
    noticeElements
      .roleNoticeActiveFilterCount
  ) {
    noticeElements
      .roleNoticeActiveFilterCount
      .textContent =
      String(
        statusCounts.active
      );
  }


  if (
    noticeElements
      .roleNoticeUpcomingFilterCount
  ) {
    noticeElements
      .roleNoticeUpcomingFilterCount
      .textContent =
      String(
        statusCounts.upcoming
      );
  }


  if (
    noticeElements
      .roleNoticeExpiredFilterCount
  ) {
    noticeElements
      .roleNoticeExpiredFilterCount
      .textContent =
      String(
        statusCounts.expired
      );
  }


  if (
    noticeElements
      .roleNoticeAllFilterCount
  ) {
    noticeElements
      .roleNoticeAllFilterCount
      .textContent =
      String(
        statusCounts.all
      );
  }


  const filteredNotices =
    roleNoticeState
      .currentFilter ===
      "all"
      ? allNotices
      : allNotices.filter(
          notice => {
            return (
              getRoleNoticeStatus(
                notice
              ) ===
              roleNoticeState
                .currentFilter
            );
          }
        );


  if (
    noticeElements.roleNoticeEmpty
  ) {
    noticeElements
      .roleNoticeEmpty
      .hidden =
      filteredNotices.length >
      0;
  }


  /*
    빈 상태 요소를 보존하면서
    기존 공지 카드만 제거한다.
  */
  noticeElements
    .roleNoticeList
    .querySelectorAll(
      ".role-notice-card"
    )
    .forEach(
      card => {
        card.remove();
      }
    );


  if (
    !filteredNotices.length
  ) {
    return;
  }


  noticeElements
    .roleNoticeList
    .insertAdjacentHTML(
      "beforeend",
      filteredNotices
        .map(
          createRoleNoticeCardHtml
        )
        .join("")
    );
}


/* =========================================================
  공지 필터 변경
========================================================= */

function changeRoleNoticeFilter(
  filter
) {
  const validFilters = [
    "active",
    "upcoming",
    "expired",
    "all"
  ];


  if (
    !validFilters.includes(
      filter
    )
  ) {
    return;
  }


  roleNoticeState.currentFilter =
    filter;


  const {
    filterButtons
  } =
    getRoleNoticeElements();


  filterButtons.forEach(
    button => {
      button.classList.toggle(
        "is-active",
        button.dataset
          .roleNoticeFilter ===
          filter
      );
    }
  );


  renderCurrentRoleNoticeList();
}


/* =========================================================
  공지 작성창 오류 메시지
========================================================= */

function showRoleNoticeEditorMessage(
  message
) {
  const {
    roleNoticeEditorMessage
  } =
    getRoleNoticeElements();


  if (
    !roleNoticeEditorMessage
  ) {
    return;
  }


  roleNoticeEditorMessage.textContent =
    String(
      message ||
      ""
    );

  roleNoticeEditorMessage.hidden =
    !message;
}


function hideRoleNoticeEditorMessage() {
  showRoleNoticeEditorMessage(
    ""
  );
}


/* =========================================================
  공지 작성창 글자 수
========================================================= */

function updateRoleNoticeCharacterCount() {
  const {
    roleNoticeContentInput,
    roleNoticeCharacterCount
  } =
    getRoleNoticeElements();


  if (
    !roleNoticeCharacterCount
  ) {
    return;
  }


  const length =
    String(
      roleNoticeContentInput?.value ||
      ""
    ).length;


  roleNoticeCharacterCount.textContent =
    `${length} / 2000`;
}

/* =========================================================
  보직 공지 중요도 선택

  false:
  - 일반 선택

  true:
  - 중요 선택
========================================================= */

function setRoleNoticeEditorPriority(
  isImportant
) {
  const editorForm =
    document.getElementById(
      "roleNoticeEditorForm"
    );


  const normalInput =
    editorForm?.querySelector(
      `
        input[
          name="roleNoticePriority"
        ][
          value="normal"
        ]
      `
    );


  const importantInput =
    document.getElementById(
      "roleNoticeImportantInput"
    );


  const shouldUseImportant =
    Boolean(
      isImportant
    );


  if (
    normalInput
  ) {
    normalInput.checked =
      !shouldUseImportant;
  }


  if (
    importantInput
  ) {
    importantInput.checked =
      shouldUseImportant;
  }
}


/* =========================================================
  새 공지 작성창 열기
========================================================= */

function openNewRoleNoticeEditor() {
  const currentRole =
    normalizeMemberLogRole(
      roleNoticeState.currentRole
    );


  if (
    !ROLE_NOTICE_ROLES.includes(
      currentRole
    )
  ) {
    showToast(
      "공지 대상 보직을 확인해 주세요."
    );

    return;
  }


  if (
    !canCurrentUserManageRoleNotice(
      currentRole
    )
  ) {
    showToast(
      "해당 보직 공지를 작성할 권한이 없습니다."
    );

    return;
  }


  const noticeElements =
    getRoleNoticeElements();


  if (
    !noticeElements.roleNoticeEditorModal ||
    !noticeElements.roleNoticeEditorForm
  ) {
    showToast(
      "공지 작성창을 찾을 수 없습니다."
    );

    return;
  }


  roleNoticeState.editingNoticeId =
    "";


  noticeElements
    .roleNoticeEditorForm
    .reset();


  const todayValue =
    getRoleNoticeTodayValue();

    /*
  새 보직 공지는 기본적으로 일반 공지
*/
setRoleNoticeEditorPriority(
  false
);


  if (
    noticeElements.roleNoticeEditingId
  ) {
    noticeElements
      .roleNoticeEditingId
      .value =
      "";
  }


  if (
    noticeElements.roleNoticeEditorRole
  ) {
    noticeElements
      .roleNoticeEditorRole
      .value =
      currentRole;
  }


  if (
    noticeElements
      .roleNoticeEditorRoleLabel
  ) {
    noticeElements
      .roleNoticeEditorRoleLabel
      .textContent =
      currentRole;
  }


  if (
    noticeElements.roleNoticeEditorTitle
  ) {
    noticeElements
      .roleNoticeEditorTitle
      .textContent =
      `${currentRole} 새 공지`;
  }


  if (
    noticeElements
      .roleNoticeStartDateInput
  ) {
    noticeElements
      .roleNoticeStartDateInput
      .value =
      todayValue;
  }


  if (
    noticeElements
      .roleNoticeEndDateInput
  ) {
    noticeElements
      .roleNoticeEndDateInput
      .value =
      todayValue;
  }


  hideRoleNoticeEditorMessage();

  updateRoleNoticeCharacterCount();


  if (
    typeof openModal ===
      "function"
  ) {
    openModal(
      noticeElements
        .roleNoticeEditorModal
    );

  } else {
    noticeElements
      .roleNoticeEditorModal
      .classList
      .add(
        "is-open"
      );

    noticeElements
      .roleNoticeEditorModal
      .setAttribute(
        "aria-hidden",
        "false"
      );

    document.body.classList.add(
      "modal-open"
    );
  }


  window.setTimeout(
    () => {
      noticeElements
        .roleNoticeTitleInput
        ?.focus();
    },
    50
  );
}


/* =========================================================
  기존 공지 수정창 열기
========================================================= */

function openEditRoleNoticeEditor(
  noticeId
) {
  const notice =
    roleNoticeState.notices.find(
      item => {
        return (
          item.id ===
          String(
            noticeId ||
            ""
          )
        );
      }
    );


  if (
    !notice
  ) {
    showToast(
      "수정할 공지를 찾을 수 없습니다."
    );

    return;
  }


  if (
    !canCurrentUserManageRoleNotice(
      notice.role
    )
  ) {
    showToast(
      "해당 공지를 수정할 권한이 없습니다."
    );

    return;
  }


  const noticeElements =
    getRoleNoticeElements();


  roleNoticeState.editingNoticeId =
    notice.id;


  if (
    noticeElements.roleNoticeEditingId
  ) {
    noticeElements
      .roleNoticeEditingId
      .value =
      notice.id;
  }


  if (
    noticeElements.roleNoticeEditorRole
  ) {
    noticeElements
      .roleNoticeEditorRole
      .value =
      notice.role;
  }


  if (
    noticeElements
      .roleNoticeEditorRoleLabel
  ) {
    noticeElements
      .roleNoticeEditorRoleLabel
      .textContent =
      notice.role;
  }


  if (
    noticeElements.roleNoticeEditorTitle
  ) {
    noticeElements
      .roleNoticeEditorTitle
      .textContent =
      `${notice.role} 공지 수정`;
  }


  if (
    noticeElements.roleNoticeTitleInput
  ) {
    noticeElements
      .roleNoticeTitleInput
      .value =
      notice.title;
  }


  if (
    noticeElements.roleNoticeContentInput
  ) {
    noticeElements
      .roleNoticeContentInput
      .value =
      notice.content;
  }


  if (
    noticeElements
      .roleNoticeStartDateInput
  ) {
    noticeElements
      .roleNoticeStartDateInput
      .value =
      notice.startDate;
  }


  if (
    noticeElements.roleNoticeEndDateInput
  ) {
    noticeElements
      .roleNoticeEndDateInput
      .value =
      notice.endDate;
  }


/*
  저장된 중요도에 맞춰
  일반 또는 중요을 선택한다.
*/
setRoleNoticeEditorPriority(
  notice.isImportant
);


  hideRoleNoticeEditorMessage();

  updateRoleNoticeCharacterCount();


  if (
    typeof openModal ===
      "function"
  ) {
    openModal(
      noticeElements
        .roleNoticeEditorModal
    );

  } else {
    noticeElements
      .roleNoticeEditorModal
      .classList
      .add(
        "is-open"
      );

    noticeElements
      .roleNoticeEditorModal
      .setAttribute(
        "aria-hidden",
        "false"
      );
  }


  window.setTimeout(
    () => {
      noticeElements
        .roleNoticeTitleInput
        ?.focus();
    },
    50
  );
}


/* =========================================================
  공지 작성창 닫기
========================================================= */

function closeRoleNoticeEditor() {
  const {
    roleNoticeEditorModal,
    roleNoticeEditorForm
  } =
    getRoleNoticeElements();


  if (
    !roleNoticeEditorModal
  ) {
    return;
  }


  roleNoticeEditorModal
    .classList
    .remove(
      "is-open"
    );

  roleNoticeEditorModal
    .setAttribute(
      "aria-hidden",
      "true"
    );


  /*
    뒤쪽 목록창이 열려 있으면
    body의 modal-open은 유지한다.
  */
  const roleNoticeModal =
    document.getElementById(
      "roleNoticeModal"
    );


  if (
    !roleNoticeModal?.classList.contains(
      "is-open"
    )
  ) {
    document.body.classList.remove(
      "modal-open"
    );
  }


  roleNoticeEditorForm?.reset();


  roleNoticeState.editingNoticeId =
    "";


  hideRoleNoticeEditorMessage();

  updateRoleNoticeCharacterCount();
}


/* =========================================================
  공지 저장
========================================================= */

async function saveRoleNotice(
  event
) {
  event.preventDefault();


  const noticeElements =
    getRoleNoticeElements();


  if (
    !noticeElements.roleNoticeEditorForm
      ?.reportValidity()
  ) {
    return;
  }


  const editingId =
    String(
      noticeElements
        .roleNoticeEditingId
        ?.value ||
      roleNoticeState
        .editingNoticeId ||
      ""
    ).trim();


  const role =
    normalizeMemberLogRole(
      noticeElements
        .roleNoticeEditorRole
        ?.value ||
      roleNoticeState
        .currentRole
    );


  const title =
    String(
      noticeElements
        .roleNoticeTitleInput
        ?.value ||
      ""
    ).trim();


  const content =
    String(
      noticeElements
        .roleNoticeContentInput
        ?.value ||
      ""
    ).trim();


  const startDate =
    String(
      noticeElements
        .roleNoticeStartDateInput
        ?.value ||
      ""
    ).trim();


  const endDate =
    String(
      noticeElements
        .roleNoticeEndDateInput
        ?.value ||
      ""
    ).trim();


  const isImportant =
    Boolean(
      noticeElements
        .roleNoticeImportantInput
        ?.checked
    );


  hideRoleNoticeEditorMessage();


  if (
    !ROLE_NOTICE_ROLES.includes(
      role
    )
  ) {
    showRoleNoticeEditorMessage(
      "공지 대상 보직을 확인해 주세요."
    );

    return;
  }


  if (
    !canCurrentUserManageRoleNotice(
      role
    )
  ) {
    showRoleNoticeEditorMessage(
      "해당 보직 공지를 저장할 권한이 없습니다."
    );

    return;
  }


  if (
    !title
  ) {
    showRoleNoticeEditorMessage(
      "공지 제목을 입력해 주세요."
    );

    noticeElements
      .roleNoticeTitleInput
      ?.focus();

    return;
  }


  if (
    !content
  ) {
    showRoleNoticeEditorMessage(
      "공지 내용을 입력해 주세요."
    );

    noticeElements
      .roleNoticeContentInput
      ?.focus();

    return;
  }


  if (
    !startDate ||
    !endDate
  ) {
    showRoleNoticeEditorMessage(
      "공지 시작일과 종료일을 선택해 주세요."
    );

    return;
  }


  if (
    startDate >
    endDate
  ) {
    showRoleNoticeEditorMessage(
      "종료일은 시작일보다 빠를 수 없습니다."
    );

    noticeElements
      .roleNoticeEndDateInput
      ?.focus();

    return;
  }


  const saveButton =
    noticeElements
      .saveRoleNoticeButton;


  const originalButtonText =
    String(
      saveButton?.textContent ||
      "저장"
    ).trim();


  if (
    saveButton
  ) {
    saveButton.disabled =
      true;

    saveButton.textContent =
      "저장 중...";
  }


  try {
    const requestBody = {
      id:
        editingId ||
        undefined,

      role,

      title,

      content,

      startDate,

      endDate,

      isImportant
    };


    const response =
      await fetch(
        ROLE_NOTICE_API_URL,
        {
          method:
            editingId
              ? "PUT"
              : "POST",

          headers:
            typeof getShiftLogAuthHeaders ===
              "function"
              ? getShiftLogAuthHeaders({
                  "Content-Type":
                    "application/json"
                })
              : {
                  "Content-Type":
                    "application/json",

                  Accept:
                    "application/json"
                },

          body:
            JSON.stringify(
              requestBody
            )
        }
      );


    await readRoleNoticeApiResponse(
      response
    );


    closeRoleNoticeEditor();


    await loadRoleNotices();


    renderCurrentRoleNoticeList();


    showToast(
      editingId
        ? "공지가 수정되었습니다."
        : "공지가 등록되었습니다."
    );

  } catch (
    error
  ) {
    console.error(
      "보직 공지 저장 실패:",
      error
    );


    showRoleNoticeEditorMessage(
      error.message ||
      "공지를 저장하지 못했습니다."
    );

  } finally {
    if (
      saveButton
    ) {
      saveButton.disabled =
        false;

      saveButton.textContent =
        originalButtonText;
    }
  }
}


/* =========================================================
  공지 삭제
========================================================= */

async function deleteRoleNotice(
  noticeId
) {
  const notice =
    roleNoticeState.notices.find(
      item => {
        return (
          item.id ===
          String(
            noticeId ||
            ""
          )
        );
      }
    );


  if (
    !notice
  ) {
    showToast(
      "삭제할 공지를 찾을 수 없습니다."
    );

    return;
  }


  if (
    !canCurrentUserManageRoleNotice(
      notice.role
    )
  ) {
    showToast(
      "해당 공지를 삭제할 권한이 없습니다."
    );

    return;
  }


  const shouldDelete =
    typeof showCompactConfirm ===
      "function"
      ? await showCompactConfirm(
          "이 공지사항을 삭제하시겠습니까?"
        )
      : window.confirm(
          "이 공지사항을 삭제하시겠습니까?"
        );


  if (
    !shouldDelete
  ) {
    return;
  }


  try {
    const requestUrl =
      new URL(
        ROLE_NOTICE_API_URL,
        window.location.origin
      );


    requestUrl.searchParams.set(
      "id",
      notice.id
    );


    const response =
      await fetch(
        requestUrl.toString(),
        {
          method:
            "DELETE",

          headers:
            typeof getShiftLogAuthHeaders ===
              "function"
              ? getShiftLogAuthHeaders()
              : {
                  Accept:
                    "application/json"
                }
        }
      );


    await readRoleNoticeApiResponse(
      response
    );


    await loadRoleNotices();


    renderCurrentRoleNoticeList();


    showToast(
      "공지가 삭제되었습니다."
    );

  } catch (
    error
  ) {
    console.error(
      "보직 공지 삭제 실패:",
      error
    );


    showToast(
      error.message ||
      "공지를 삭제하지 못했습니다."
    );
  }
}


/* =========================================================
  공지 목록 클릭 처리

  동적 생성되는 수정·삭제 버튼을
  이벤트 위임 방식으로 처리한다.
========================================================= */

function handleRoleNoticeListClick(
  event
) {
  const editButton =
    event.target.closest(
      "[data-role-notice-edit]"
    );


  if (
    editButton
  ) {
    openEditRoleNoticeEditor(
      editButton.dataset
        .roleNoticeEdit
    );

    return;
  }


  const deleteButton =
    event.target.closest(
      "[data-role-notice-delete]"
    );


  if (
    deleteButton
  ) {
    deleteRoleNotice(
      deleteButton.dataset
        .roleNoticeDelete
    );
  }
}


/* =========================================================
  공지 기능 이벤트 연결
========================================================= */

function bindRoleNoticeEvents() {
  const noticeElements =
    getRoleNoticeElements();


  /*
    보직 카드 위 공지 버튼
  */
  noticeElements.noticeButtons.forEach(
    button => {
      button.addEventListener(
        "click",
        event => {
          /*
            아래 업무일지 카드의 클릭 이벤트로
            전달되지 않도록 차단한다.
          */
          event.preventDefault();

          event.stopPropagation();


          openRoleNoticeModal(
            button.dataset.role
          );
        }
      );
    }
  );


  /*
    목록창 닫기
  */
  noticeElements
    .closeRoleNoticeModalButton
    ?.addEventListener(
      "click",
      closeRoleNoticeModal
    );


  noticeElements
    .closeRoleNoticeModalFooterButton
    ?.addEventListener(
      "click",
      closeRoleNoticeModal
    );


  /*
    새 공지
  */
  noticeElements
    .openRoleNoticeEditorButton
    ?.addEventListener(
      "click",
      openNewRoleNoticeEditor
    );


  /*
    필터
  */
  noticeElements.filterButtons.forEach(
    button => {
      button.addEventListener(
        "click",
        () => {
          changeRoleNoticeFilter(
            button.dataset
              .roleNoticeFilter
          );
        }
      );
    }
  );


  /*
    공지 카드 수정·삭제
  */
  noticeElements
    .roleNoticeList
    ?.addEventListener(
      "click",
      handleRoleNoticeListClick
    );


  /*
    작성창 닫기
  */
  noticeElements
    .closeRoleNoticeEditorButton
    ?.addEventListener(
      "click",
      closeRoleNoticeEditor
    );


  noticeElements
    .cancelRoleNoticeEditorButton
    ?.addEventListener(
      "click",
      closeRoleNoticeEditor
    );


  /*
    작성창 저장
  */
  noticeElements
    .roleNoticeEditorForm
    ?.addEventListener(
      "submit",
      saveRoleNotice
    );


  /*
    내용 글자 수
  */
  noticeElements
    .roleNoticeContentInput
    ?.addEventListener(
      "input",
      updateRoleNoticeCharacterCount
    );


  /*
    시작일 변경 시 종료일이 더 빠르면
    종료일을 시작일과 같게 보정한다.
  */
  noticeElements
    .roleNoticeStartDateInput
    ?.addEventListener(
      "change",
      () => {
        const startDate =
          noticeElements
            .roleNoticeStartDateInput
            ?.value ||
          "";

        const endDate =
          noticeElements
            .roleNoticeEndDateInput
            ?.value ||
          "";


        if (
          startDate &&
          (
            !endDate ||
            endDate <
              startDate
          )
        ) {
          noticeElements
            .roleNoticeEndDateInput
            .value =
            startDate;
        }
      }
    );


  /*
    목록창은 배경 클릭으로 닫는다.
    작성창은 입력 실수를 막기 위해 배경 클릭으로 닫지 않는다.
  */
  noticeElements
    .roleNoticeModal
    ?.addEventListener(
      "click",
      event => {
        if (
          event.target ===
          noticeElements
            .roleNoticeModal
        ) {
          closeRoleNoticeModal();
        }
      }
    );


  /*
    ESC 처리
  */
  document.addEventListener(
    "keydown",
    event => {
      if (
        event.key !==
        "Escape"
      ) {
        return;
      }


      if (
        noticeElements
          .roleNoticeEditorModal
          ?.classList.contains(
            "is-open"
          )
      ) {
        closeRoleNoticeEditor();

        return;
      }


      if (
        noticeElements
          .roleNoticeModal
          ?.classList.contains(
            "is-open"
          )
      ) {
        closeRoleNoticeModal();
      }
    }
  );
}


/* =========================================================
  보직 공지 초기화

  로그인 후 카드에 활성 공지 개수를 표시한다.
========================================================= */

async function initializeRoleNotices() {
  const noticeButtons =
    document.querySelectorAll(
      "[data-role-notice-button]"
    );


  /*
    공지 HTML이 아직 없으면
    기존 업무일지 기능에는 영향을 주지 않는다.
  */
  if (
    !noticeButtons.length
  ) {
    return;
  }


  bindRoleNoticeEvents();


  /*
    API 응답 전에는 모든 버튼을
    공지 없음 상태로 표시한다.
  */
  updateAllRoleNoticeButtons();


  /*
    로그인 사용자만 공지 데이터를 조회한다.
  */
  const currentUser =
    loadCurrentUser();


  if (
    !currentUser
  ) {
    return;
  }


  await loadRoleNotices();
}


document.addEventListener(
  "DOMContentLoaded",
  initializeRoleNotices
);

/* =========================================================
  전체공지 프런트엔드 기능

  권한:
  - 로그인한 모든 사용자 조회 가능
  - 로그인한 모든 사용자 추가·수정·삭제 가능

  중요도:
  - normal    : 일반
  - important : 중요
  - urgent    : 긴급

  자동 팝업:
  - 현재 활성 상태인 중요·긴급 공지
  - 사용자별·공지별 12시간 숨김 지원

  첨부자료:
  - FormData로 서버 전송
  - 실제 파일은 다음 단계의 Worker API에서 R2에 저장

  API:
  - GET    /api/global-notices
  - POST   /api/global-notices
  - DELETE /api/global-notices?id=공지ID
========================================================= */


