/* =========================================================
  전체공지 날짜 처리
========================================================= */

function getGlobalNoticeTodayText() {
  const today =
    new Date();


  return [
    today.getFullYear(),

    String(
      today.getMonth() + 1
    ).padStart(
      2,
      "0"
    ),

    String(
      today.getDate()
    ).padStart(
      2,
      "0"
    )
  ].join("-");
}


function normalizeGlobalNoticeDate(
  value
) {
  return String(
    value ||
    ""
  )
    .trim()
    .slice(
      0,
      10
    );
}


function formatGlobalNoticeDate(
  value
) {
  const normalizedDate =
    normalizeGlobalNoticeDate(
      value
    );


  if (
    !normalizedDate
  ) {
    return "-";
  }


  const parts =
    normalizedDate.split(
      "-"
    );


  if (
    parts.length !==
    3
  ) {
    return normalizedDate;
  }


  return `${parts[0]}.${parts[1]}.${parts[2]}`;
}


/* =========================================================
  전체공지 상태 판정

  오늘 < 시작일:
  예정

  시작일 <= 오늘 <= 종료일:
  진행 중

  오늘 > 종료일:
  종료
========================================================= */

function getGlobalNoticeStatus(
  notice,
  todayText =
    getGlobalNoticeTodayText()
) {
  const startDate =
    normalizeGlobalNoticeDate(
      notice?.startDate ||
      notice?.start_date
    );


  const endDate =
    normalizeGlobalNoticeDate(
      notice?.endDate ||
      notice?.end_date
    );


  if (
    startDate &&
    todayText <
      startDate
  ) {
    return "upcoming";
  }


  if (
    endDate &&
    todayText >
      endDate
  ) {
    return "expired";
  }


  return "active";
}


function getGlobalNoticeStatusLabel(
  status
) {
  const statusMap = {
    active:
      "진행 중",

    upcoming:
      "예정",

    expired:
      "종료"
  };


  return (
    statusMap[
      status
    ] ||
    "진행 중"
  );
}


/* =========================================================
  중요도 정규화
========================================================= */

function normalizeGlobalNoticePriority(
  value
) {
  const priority =
    String(
      value ||
      "normal"
    )
      .trim()
      .toLowerCase();


  if (
    priority ===
      "urgent" ||
    priority ===
      "긴급"
  ) {
    return "urgent";
  }


  if (
    priority ===
      "important" ||
    priority ===
      "중요"
  ) {
    return "important";
  }


  return "normal";
}


function getGlobalNoticePriorityLabel(
  priority
) {
  const priorityMap = {
    normal:
      "일반",

    important:
      "중요",

    urgent:
      "긴급"
  };


  return (
    priorityMap[
      normalizeGlobalNoticePriority(
        priority
      )
    ] ||
    "일반"
  );
}


/* =========================================================
  서버 전체공지 객체 정규화
========================================================= */

function normalizeGlobalNotice(
  notice
) {
  const sourceNotice =
    notice &&
    typeof notice ===
      "object"
      ? notice
      : {};


  const attachments =
    Array.isArray(
      sourceNotice.attachments
    )
      ? sourceNotice.attachments
      : [];


  return {
    id:
      String(
        sourceNotice.id ||
        ""
      ).trim(),

    priority:
      normalizeGlobalNoticePriority(
        sourceNotice.priority ||
        sourceNotice.importance ||
        sourceNotice.noticePriority ||
        sourceNotice.notice_priority
      ),

    title:
      String(
        sourceNotice.title ||
        ""
      ).trim(),

    content:
      String(
        sourceNotice.content ||
        ""
      )
        .replace(
          /\r\n/g,
          "\n"
        )
        .replace(
          /\r/g,
          "\n"
        )
        .trim(),

    startDate:
      normalizeGlobalNoticeDate(
        sourceNotice.startDate ||
        sourceNotice.start_date
      ),

    endDate:
      normalizeGlobalNoticeDate(
        sourceNotice.endDate ||
        sourceNotice.end_date
      ),

    createdBy:
      String(
        sourceNotice.createdBy ||
        sourceNotice.created_by ||
        ""
      ).trim(),

    createdByName:
      String(
        sourceNotice.createdByName ||
        sourceNotice.created_by_name ||
        sourceNotice.authorName ||
        sourceNotice.author_name ||
        ""
      ).trim(),

    createdAt:
      String(
        sourceNotice.createdAt ||
        sourceNotice.created_at ||
        ""
      ).trim(),

    updatedAt:
      String(
        sourceNotice.updatedAt ||
        sourceNotice.updated_at ||
        ""
      ).trim(),

    attachments:
      attachments
        .map(
          attachment => {
            const attachmentId =
              String(
                attachment?.id ||
                ""
              ).trim();


            const fileName =
              String(
                attachment?.fileName ||
                attachment?.file_name ||
                attachment?.name ||
                ""
              ).trim();


            const url =
              String(
                attachment?.url ||
                attachment?.downloadUrl ||
                attachment?.download_url ||
                (
                  attachmentId
                    ? `/api/global-notices/attachment?id=${encodeURIComponent(
                        attachmentId
                      )}`
                    : ""
                )
              ).trim();


            return {
              id:
                attachmentId,

              fileName,

              name:
                fileName,

              fileSize:
                Number(
                  attachment?.fileSize ||
                  attachment?.file_size ||
                  0
                ),

              mimeType:
                String(
                  attachment?.mimeType ||
                  attachment?.mime_type ||
                  ""
                ).trim(),

              r2Key:
                String(
                  attachment?.r2Key ||
                  attachment?.r2_key ||
                  ""
                ).trim(),

              url
            };
          }
        )
        .filter(
          attachment => {
            return Boolean(
              attachment.id ||
              attachment.fileName ||
              attachment.url
            );
          }
        )
  };
}


/* =========================================================
  전체공지 관리 권한

  요청사항:
  - 일반 사용자도 추가·수정·삭제 가능
========================================================= */

function canCurrentUserManageGlobalNotice() {
  return Boolean(
    loadCurrentUser()
  );
}


/* =========================================================
  전체공지 API 응답 읽기
========================================================= */

async function parseGlobalNoticeResponse(
  response
) {
  const responseText =
    await response.text();


  if (
    !responseText.trim()
  ) {
    return {};
  }


  try {
    return JSON.parse(
      responseText
    );

  } catch {
    throw new Error(
      "전체공지 서버 응답 형식이 올바르지 않습니다."
    );
  }
}


/* =========================================================
  전체공지 불러오기
========================================================= */

async function loadGlobalNotices() {
  if (
    globalNoticeState.isLoading
  ) {
    return globalNoticeState.notices;
  }


  const currentUser =
    loadCurrentUser();


  if (
    !currentUser
  ) {
    globalNoticeState.notices =
      [];

    return [];
  }


  globalNoticeState.isLoading =
    true;


  try {
    const response =
      await fetch(
        `${GLOBAL_NOTICE_API_URL}?_=${Date.now()}`,
        {
          method:
            "GET",

          headers:
            getShiftLogAuthHeaders(),

          cache:
            "no-store"
        }
      );


    const result =
      await parseGlobalNoticeResponse(
        response
      );


    if (
      !response.ok ||
      result.ok ===
        false ||
      result.success ===
        false
    ) {
      throw new Error(
        result.message ||
        result.error ||
        `전체공지 조회 실패 (HTTP ${response.status})`
      );
    }


    const sourceItems =
      Array.isArray(
        result.items
      )
        ? result.items
        : (
            Array.isArray(
              result.notices
            )
              ? result.notices
              : (
                  Array.isArray(
                    result.data
                  )
                    ? result.data
                    : []
                )
          );


    globalNoticeState.notices =
      sourceItems
        .map(
          normalizeGlobalNotice
        )
        .filter(
          notice => {
            return Boolean(
              notice.id
            );
          }
        )
        .sort(
          (
            firstNotice,
            secondNotice
          ) => {
            const priorityOrder = {
              urgent:
                3,

              important:
                2,

              normal:
                1
            };


            const priorityDifference =
              (
                priorityOrder[
                  secondNotice.priority
                ] ||
                0
              ) -
              (
                priorityOrder[
                  firstNotice.priority
                ] ||
                0
              );


            if (
              priorityDifference !==
              0
            ) {
              return priorityDifference;
            }


            return String(
              secondNotice.updatedAt ||
              secondNotice.createdAt ||
              ""
            ).localeCompare(
              String(
                firstNotice.updatedAt ||
                firstNotice.createdAt ||
                ""
              )
            );
          }
        );


    updateGlobalNoticeHeaderButton();


    return globalNoticeState.notices;

  } catch (
    error
  ) {
    console.error(
      "전체공지 조회 오류:",
      error
    );


    globalNoticeState.notices =
      [];


    updateGlobalNoticeHeaderButton();


    return [];

  } finally {
    globalNoticeState.isLoading =
      false;
  }
}


/* =========================================================
  상단 전체공지 버튼 활성 건수 표시
========================================================= */

function updateGlobalNoticeHeaderButton() {
  const {
    noticeButton
  } =
    getGlobalNoticeElements();


  if (
    !noticeButton
  ) {
    return;
  }


  const activeCount =
    globalNoticeState.notices.filter(
      notice => {
        return (
          getGlobalNoticeStatus(
            notice
          ) ===
          "active"
        );
      }
    ).length;


  noticeButton.textContent =
    activeCount > 0
      ? `전체공지 ${activeCount}`
      : "전체공지";


  noticeButton.dataset
    .activeNoticeCount =
    String(
      activeCount
    );


  noticeButton.classList.toggle(
    "has-active-notice",
    activeCount > 0
  );
}


/* =========================================================
  전체공지 카드 HTML
========================================================= */

function createGlobalNoticeCardHtml(
  notice
) {
  const status =
    getGlobalNoticeStatus(
      notice
    );


  const priority =
    normalizeGlobalNoticePriority(
      notice.priority
    );


  const authorText =
    notice.createdByName ||
    notice.createdBy ||
    "작성자 미확인";


  const updatedText =
    typeof formatDateTime ===
      "function"
      ? formatDateTime(
          notice.updatedAt ||
          notice.createdAt
        )
      : String(
          notice.updatedAt ||
          notice.createdAt ||
          ""
        );


  const attachments =
    Array.isArray(
      notice.attachments
    )
      ? notice.attachments
      : [];


  const attachmentHtml =
    attachments.length
      ? `
        <div class="global-notice-card__attachments">

          ${attachments
            .map(
              attachment => {
                const fileName =
                  attachment.fileName ||
                  attachment.name ||
                  "첨부자료";


                return `
                  <a
                    href="${escapeHtml(
                      attachment.url ||
                      "#"
                    )}"
                    class="global-notice-card__attachment-link"
                    target="_blank"
                    rel="noopener noreferrer"
                    download
                    title="${escapeHtml(
                      fileName
                    )}"
                  >
                    📎
                    ${escapeHtml(
                      fileName
                    )}
                  </a>
                `;
              }
            )
            .join("")}

        </div>
      `
      : "";


  return `
    <article
      class="
        global-notice-card
        is-${escapeHtml(
          priority
        )}
        ${
          status ===
            "expired"
            ? "is-expired"
            : ""
        }
      "
      data-global-notice-id="${escapeHtml(
        notice.id
      )}"
    >

      <div class="global-notice-card__main">

        <div class="global-notice-card__heading">

          <span
            class="
              global-notice-priority-badge
              is-${escapeHtml(
                priority
              )}
            "
          >
            ${escapeHtml(
              getGlobalNoticePriorityLabel(
                priority
              )
            )}
          </span>


          <h3 class="global-notice-card__title">
            ${escapeHtml(
              notice.title ||
              "제목 없음"
            )}
          </h3>


          <span
            class="
              global-notice-card__status
              is-${escapeHtml(
                status
              )}
            "
          >
            ${escapeHtml(
              getGlobalNoticeStatusLabel(
                status
              )
            )}
          </span>

        </div>


        <p class="global-notice-card__period">
          ${escapeHtml(
            formatGlobalNoticeDate(
              notice.startDate
            )
          )}
          ~
          ${escapeHtml(
            formatGlobalNoticeDate(
              notice.endDate
            )
          )}
        </p>


        <p class="global-notice-card__content">
          ${escapeHtml(
            notice.content ||
            ""
          )}
        </p>


        ${attachmentHtml}


        <p class="global-notice-card__meta">
          ${escapeHtml(
            authorText
          )}
          ·
          ${escapeHtml(
            updatedText
          )}
        </p>

      </div>


      ${
        canCurrentUserManageGlobalNotice()
          ? `
            <div class="global-notice-card__actions">

              <button
                type="button"
                class="global-notice-card__edit-button"
                data-global-notice-edit="${escapeHtml(
                  notice.id
                )}"
              >
                수정
              </button>


              <button
                type="button"
                class="global-notice-card__delete-button"
                data-global-notice-delete="${escapeHtml(
                  notice.id
                )}"
              >
                삭제
              </button>

            </div>
          `
          : ""
      }

    </article>
  `;
}


/* =========================================================
  전체공지 목록 출력
========================================================= */

function renderGlobalNoticeList() {
  const noticeElements =
    getGlobalNoticeElements();


  if (
    !noticeElements.globalNoticeList
  ) {
    return;
  }


  const statusCounts = {
    active:
      0,

    upcoming:
      0,

    expired:
      0,

    all:
      globalNoticeState.notices.length
  };


  globalNoticeState.notices.forEach(
    notice => {
      const status =
        getGlobalNoticeStatus(
          notice
        );


      statusCounts[
        status
      ] +=
        1;
    }
  );


  if (
    noticeElements.globalNoticeActiveCount
  ) {
    noticeElements
      .globalNoticeActiveCount
      .textContent =
      `활성 ${statusCounts.active}건`;
  }


  if (
    noticeElements.globalNoticeActiveFilterCount
  ) {
    noticeElements
      .globalNoticeActiveFilterCount
      .textContent =
      String(
        statusCounts.active
      );
  }


  if (
    noticeElements.globalNoticeUpcomingFilterCount
  ) {
    noticeElements
      .globalNoticeUpcomingFilterCount
      .textContent =
      String(
        statusCounts.upcoming
      );
  }


  if (
    noticeElements.globalNoticeExpiredFilterCount
  ) {
    noticeElements
      .globalNoticeExpiredFilterCount
      .textContent =
      String(
        statusCounts.expired
      );
  }


  if (
    noticeElements.globalNoticeAllFilterCount
  ) {
    noticeElements
      .globalNoticeAllFilterCount
      .textContent =
      String(
        statusCounts.all
      );
  }


  const filteredNotices =
    globalNoticeState.currentFilter ===
      "all"
      ? globalNoticeState.notices
      : globalNoticeState.notices.filter(
          notice => {
            return (
              getGlobalNoticeStatus(
                notice
              ) ===
              globalNoticeState
                .currentFilter
            );
          }
        );


  if (
    noticeElements.globalNoticeEmpty
  ) {
    noticeElements
      .globalNoticeEmpty
      .hidden =
      filteredNotices.length >
      0;
  }


  noticeElements.globalNoticeList
    .querySelectorAll(
      ".global-notice-card"
    )
    .forEach(
      card => {
        card.remove();
      }
    );


  if (
    filteredNotices.length
  ) {
    noticeElements.globalNoticeList
      .insertAdjacentHTML(
        "beforeend",
        filteredNotices
          .map(
            createGlobalNoticeCardHtml
          )
          .join("")
      );
  }


  updateGlobalNoticeHeaderButton();
}


/* =========================================================
  전체공지 목록창 열기
========================================================= */

async function openGlobalNoticeModal() {
  const noticeElements =
    getGlobalNoticeElements();


  if (
    !noticeElements.globalNoticeModal
  ) {
    showToast(
      "전체공지창을 찾을 수 없습니다."
    );

    return;
  }


  globalNoticeState.currentFilter =
    "active";


  noticeElements.filterButtons
    .forEach(
      button => {
        button.classList.toggle(
          "is-active",
          button.dataset
            .globalNoticeFilter ===
            "active"
        );
      }
    );


  if (
    noticeElements.openGlobalNoticeEditorButton
  ) {
    noticeElements
      .openGlobalNoticeEditorButton
      .hidden =
      !canCurrentUserManageGlobalNotice();
  }


  openModal(
    noticeElements.globalNoticeModal
  );


  if (
    noticeElements.globalNoticeList
  ) {
    noticeElements.globalNoticeList
      .setAttribute(
        "aria-busy",
        "true"
      );
  }


  await loadGlobalNotices();


  if (
    noticeElements.globalNoticeList
  ) {
    noticeElements.globalNoticeList
      .setAttribute(
        "aria-busy",
        "false"
      );
  }


  renderGlobalNoticeList();
}


/* =========================================================
  전체공지 목록창 닫기
========================================================= */

function closeGlobalNoticeModal() {
  const {
    globalNoticeModal,
    globalNoticeEditorModal
  } =
    getGlobalNoticeElements();


  if (
    globalNoticeEditorModal
      ?.classList.contains(
        "is-open"
      )
  ) {
    closeGlobalNoticeEditor();
  }


  if (
    globalNoticeModal
  ) {
    closeModal(
      globalNoticeModal
    );
  }
}


/* =========================================================
  전체공지 작성창 메시지
========================================================= */

function showGlobalNoticeEditorMessage(
  message
) {
  const {
    globalNoticeEditorMessage
  } =
    getGlobalNoticeElements();


  if (
    !globalNoticeEditorMessage
  ) {
    return;
  }


  globalNoticeEditorMessage.textContent =
    String(
      message ||
      ""
    );


  globalNoticeEditorMessage.hidden =
    !message;
}


function hideGlobalNoticeEditorMessage() {
  showGlobalNoticeEditorMessage(
    ""
  );
}


/* =========================================================
  전체공지 작성창 초기화
========================================================= */

function resetGlobalNoticeEditor() {
  const noticeElements =
    getGlobalNoticeElements();


  noticeElements.globalNoticeEditorForm
    ?.reset();


  globalNoticeState.editingNoticeId =
    "";


  globalNoticeState.selectedFiles =
    [];


  globalNoticeState.existingAttachments =
    [];


  globalNoticeState.deletedAttachmentIds =
    [];


  if (
    noticeElements.globalNoticeEditingId
  ) {
    noticeElements.globalNoticeEditingId.value =
      "";
  }


  const todayText =
    getGlobalNoticeTodayText();


  if (
    noticeElements.globalNoticeStartDateInput
  ) {
    noticeElements
      .globalNoticeStartDateInput
      .value =
      todayText;
  }


  if (
    noticeElements.globalNoticeEndDateInput
  ) {
    noticeElements
      .globalNoticeEndDateInput
      .value =
      todayText;
  }


  if (
    noticeElements.globalNoticeCharacterCount
  ) {
    noticeElements
      .globalNoticeCharacterCount
      .textContent =
      "0 / 5000";
  }


  if (
    noticeElements.globalNoticeFileInput
  ) {
    noticeElements.globalNoticeFileInput.value =
      "";
  }


  if (
    noticeElements.globalNoticeDeletedAttachmentIds
  ) {
    noticeElements
      .globalNoticeDeletedAttachmentIds
      .value =
      "[]";
  }


  hideGlobalNoticeEditorMessage();


  renderGlobalNoticeSelectedFiles();


  renderGlobalNoticeExistingAttachments();
}


/* =========================================================
  새 전체공지 작성창
========================================================= */

function openNewGlobalNoticeEditor() {
  if (
    !canCurrentUserManageGlobalNotice()
  ) {
    showToast(
      "로그인 후 전체공지를 작성할 수 있습니다."
    );

    return;
  }


  const noticeElements =
    getGlobalNoticeElements();


  resetGlobalNoticeEditor();


  if (
    noticeElements.globalNoticeEditorTitle
  ) {
    noticeElements.globalNoticeEditorTitle.textContent =
      "새 전체공지";
  }


  openModal(
    noticeElements.globalNoticeEditorModal
  );


  window.setTimeout(
    () => {
      noticeElements.globalNoticeTitleInput
        ?.focus();
    },
    50
  );
}


/* =========================================================
  기존 전체공지 수정창
========================================================= */

function openGlobalNoticeEditor(
  noticeId
) {
  const notice =
    globalNoticeState.notices.find(
      item => {
        return (
          String(
            item.id
          ) ===
          String(
            noticeId
          )
        );
      }
    );


  if (
    !notice
  ) {
    showToast(
      "수정할 전체공지를 찾을 수 없습니다."
    );

    return;
  }


  const noticeElements =
    getGlobalNoticeElements();


  resetGlobalNoticeEditor();


  globalNoticeState.editingNoticeId =
    notice.id;


  globalNoticeState.existingAttachments =
    Array.isArray(
      notice.attachments
    )
      ? notice.attachments.map(
          attachment => {
            return {
              ...attachment
            };
          }
        )
      : [];


  if (
    noticeElements.globalNoticeEditingId
  ) {
    noticeElements.globalNoticeEditingId.value =
      notice.id;
  }


  if (
    noticeElements.globalNoticeEditorTitle
  ) {
    noticeElements.globalNoticeEditorTitle.textContent =
      "전체공지 수정";
  }


  if (
    noticeElements.globalNoticeTitleInput
  ) {
    noticeElements.globalNoticeTitleInput.value =
      notice.title;
  }


  if (
    noticeElements.globalNoticeContentInput
  ) {
    noticeElements.globalNoticeContentInput.value =
      notice.content;
  }


  if (
    noticeElements.globalNoticeCharacterCount
  ) {
    noticeElements.globalNoticeCharacterCount.textContent =
      `${notice.content.length} / 5000`;
  }


  if (
    noticeElements.globalNoticeStartDateInput
  ) {
    noticeElements.globalNoticeStartDateInput.value =
      notice.startDate;
  }


  if (
    noticeElements.globalNoticeEndDateInput
  ) {
    noticeElements.globalNoticeEndDateInput.value =
      notice.endDate;
  }


  noticeElements.priorityInputs
    .forEach(
      input => {
        input.checked =
          input.value ===
          notice.priority;
      }
    );


  renderGlobalNoticeExistingAttachments();


  openModal(
    noticeElements.globalNoticeEditorModal
  );


  window.setTimeout(
    () => {
      noticeElements.globalNoticeTitleInput
        ?.focus();
    },
    50
  );
}


/* =========================================================
  전체공지 작성창 닫기
========================================================= */

function closeGlobalNoticeEditor() {
  const {
    globalNoticeEditorModal,
    globalNoticeModal
  } =
    getGlobalNoticeElements();


  if (
    globalNoticeEditorModal
  ) {
    closeModal(
      globalNoticeEditorModal
    );
  }


  /*
    목록창이 열려 있으면
    body의 modal-open 상태를 유지한다.
  */
  if (
    globalNoticeModal
      ?.classList.contains(
        "is-open"
      )
  ) {
    document.body.classList.add(
      "modal-open"
    );
  }


  resetGlobalNoticeEditor();
}


/* =========================================================
  파일 크기 표시
========================================================= */

function formatGlobalNoticeFileSize(
  fileSize
) {
  const size =
    Number(
      fileSize ||
      0
    );


  if (
    size >=
    1024 * 1024
  ) {
    return `${(
      size /
      1024 /
      1024
    ).toFixed(1)} MB`;
  }


  if (
    size >=
    1024
  ) {
    return `${Math.round(
      size /
      1024
    )} KB`;
  }


  return `${size} B`;
}


/* =========================================================
  새 첨부파일 검증 및 추가
========================================================= */

function addGlobalNoticeFiles(
  fileList
) {
  const files = [
    ...(
      fileList ||
      []
    )
  ];


  if (
    !files.length
  ) {
    return;
  }


  const existingCount =
    globalNoticeState
      .existingAttachments
      .filter(
        attachment => {
          return !globalNoticeState
            .deletedAttachmentIds
            .includes(
              String(
                attachment.id
              )
            );
        }
      ).length;


  for (
    const file
    of files
  ) {
    const extension =
      String(
        file.name ||
        ""
      )
        .split(
          "."
        )
        .pop()
        .toLowerCase();


    if (
      !GLOBAL_NOTICE_ALLOWED_EXTENSIONS
        .has(
          extension
        )
    ) {
      showGlobalNoticeEditorMessage(
        `${file.name} 파일 형식은 첨부할 수 없습니다.`
      );

      continue;
    }


    if (
      file.size >
      GLOBAL_NOTICE_MAX_FILE_SIZE
    ) {
      showGlobalNoticeEditorMessage(
        `${file.name} 파일은 20MB를 초과합니다.`
      );

      continue;
    }


    const totalCount =
      existingCount +
      globalNoticeState
        .selectedFiles
        .length;


    if (
      totalCount >=
      GLOBAL_NOTICE_MAX_FILE_COUNT
    ) {
      showGlobalNoticeEditorMessage(
        "첨부자료는 최대 10개까지 등록할 수 있습니다."
      );

      break;
    }


    const duplicateFile =
      globalNoticeState
        .selectedFiles
        .some(
          currentFile => {
            return (
              currentFile.name ===
                file.name &&
              currentFile.size ===
                file.size &&
              currentFile.lastModified ===
                file.lastModified
            );
          }
        );


    if (
      duplicateFile
    ) {
      continue;
    }


    globalNoticeState.selectedFiles.push(
      file
    );
  }


  renderGlobalNoticeSelectedFiles();
}


/* =========================================================
  새로 선택한 파일 출력
========================================================= */

function renderGlobalNoticeSelectedFiles() {
  const {
    globalNoticeSelectedFileList
  } =
    getGlobalNoticeElements();


  if (
    !globalNoticeSelectedFileList
  ) {
    return;
  }


  globalNoticeSelectedFileList.innerHTML =
    globalNoticeState.selectedFiles
      .map(
        (
          file,
          fileIndex
        ) => {
          return `
            <div class="global-notice-selected-file-item">

              <span class="global-notice-file-name">
                ${escapeHtml(
                  file.name
                )}
              </span>


              <span class="global-notice-file-size">
                ${escapeHtml(
                  formatGlobalNoticeFileSize(
                    file.size
                  )
                )}
              </span>


              <button
                type="button"
                class="global-notice-file-remove-button"
                data-global-notice-file-remove="${fileIndex}"
              >
                삭제
              </button>

            </div>
          `;
        }
      )
      .join("");
}


/* =========================================================
  기존 첨부자료 출력
========================================================= */

function renderGlobalNoticeExistingAttachments() {
  const noticeElements =
    getGlobalNoticeElements();


  const visibleAttachments =
    globalNoticeState
      .existingAttachments
      .filter(
        attachment => {
          return !globalNoticeState
            .deletedAttachmentIds
            .includes(
              String(
                attachment.id
              )
            );
        }
      );


  if (
    noticeElements
      .globalNoticeExistingAttachmentWrap
  ) {
    noticeElements
      .globalNoticeExistingAttachmentWrap
      .hidden =
      visibleAttachments.length ===
      0;
  }


  if (
    noticeElements
      .globalNoticeExistingAttachmentCount
  ) {
    noticeElements
      .globalNoticeExistingAttachmentCount
      .textContent =
      `${visibleAttachments.length}개`;
  }


  if (
    noticeElements
      .globalNoticeExistingAttachmentList
  ) {
    noticeElements
      .globalNoticeExistingAttachmentList
      .innerHTML =
      visibleAttachments
        .map(
          attachment => {
            return `
              <div class="global-notice-existing-attachment-item">

                <span class="global-notice-file-name">
                  ${escapeHtml(
                    attachment.fileName ||
                    attachment.name ||
                    "첨부자료"
                  )}
                </span>


                <span class="global-notice-file-size">
                  ${escapeHtml(
                    formatGlobalNoticeFileSize(
                      attachment.fileSize
                    )
                  )}
                </span>


                <button
                  type="button"
                  class="global-notice-file-remove-button"
                  data-global-notice-existing-remove="${escapeHtml(
                    attachment.id
                  )}"
                >
                  삭제
                </button>

              </div>
            `;
          }
        )
        .join("");
  }


  if (
    noticeElements
      .globalNoticeDeletedAttachmentIds
  ) {
    noticeElements
      .globalNoticeDeletedAttachmentIds
      .value =
      JSON.stringify(
        globalNoticeState
          .deletedAttachmentIds
      );
  }
}


/* =========================================================
  전체공지 입력 검증
========================================================= */

function validateGlobalNoticeEditor() {
  const noticeElements =
    getGlobalNoticeElements();


  const title =
    String(
      noticeElements
        .globalNoticeTitleInput
        ?.value ||
      ""
    ).trim();


  const content =
    String(
      noticeElements
        .globalNoticeContentInput
        ?.value ||
      ""
    ).trim();


  const startDate =
    String(
      noticeElements
        .globalNoticeStartDateInput
        ?.value ||
      ""
    ).trim();


  const endDate =
    String(
      noticeElements
        .globalNoticeEndDateInput
        ?.value ||
      ""
    ).trim();


  if (
    !title
  ) {
    showGlobalNoticeEditorMessage(
      "공지 제목을 입력해 주세요."
    );

    noticeElements.globalNoticeTitleInput
      ?.focus();

    return false;
  }


  if (
    !content
  ) {
    showGlobalNoticeEditorMessage(
      "공지 내용을 입력해 주세요."
    );

    noticeElements.globalNoticeContentInput
      ?.focus();

    return false;
  }


  if (
    !startDate ||
    !endDate
  ) {
    showGlobalNoticeEditorMessage(
      "공지 시작일과 종료일을 선택해 주세요."
    );

    return false;
  }


  if (
    startDate >
    endDate
  ) {
    showGlobalNoticeEditorMessage(
      "종료일은 시작일보다 빠를 수 없습니다."
    );

    noticeElements.globalNoticeEndDateInput
      ?.focus();

    return false;
  }


  hideGlobalNoticeEditorMessage();


  return true;
}


/* =========================================================
  전체공지 저장

  FormData:
  - id
  - priority
  - title
  - content
  - startDate
  - endDate
  - deletedAttachmentIds
  - files
========================================================= */

async function saveGlobalNotice(
  event
) {
  event?.preventDefault();


  if (
    !validateGlobalNoticeEditor()
  ) {
    return;
  }


  const noticeElements =
    getGlobalNoticeElements();


  const currentUser =
    loadCurrentUser();


  if (
    !currentUser
  ) {
    showGlobalNoticeEditorMessage(
      "로그인 정보를 확인할 수 없습니다."
    );

    return;
  }


  const priority =
    noticeElements.priorityInputs
      .find(
        input => {
          return input.checked;
        }
      )
      ?.value ||
    "normal";


  const formData =
    new FormData();


  formData.append(
    "id",
    String(
      globalNoticeState
        .editingNoticeId ||
      ""
    )
  );


  formData.append(
    "priority",
    normalizeGlobalNoticePriority(
      priority
    )
  );


  formData.append(
    "title",
    String(
      noticeElements
        .globalNoticeTitleInput
        ?.value ||
      ""
    ).trim()
  );


  formData.append(
    "content",
    String(
      noticeElements
        .globalNoticeContentInput
        ?.value ||
      ""
    ).trim()
  );


  formData.append(
    "startDate",
    String(
      noticeElements
        .globalNoticeStartDateInput
        ?.value ||
      ""
    ).trim()
  );


  formData.append(
    "endDate",
    String(
      noticeElements
        .globalNoticeEndDateInput
        ?.value ||
      ""
    ).trim()
  );


  formData.append(
    "deletedAttachmentIds",
    JSON.stringify(
      globalNoticeState
        .deletedAttachmentIds
    )
  );


  globalNoticeState.selectedFiles
    .forEach(
      file => {
        formData.append(
          "files",
          file,
          file.name
        );
      }
    );


  if (
    noticeElements.saveGlobalNoticeButton
  ) {
    noticeElements.saveGlobalNoticeButton.disabled =
      true;

    noticeElements.saveGlobalNoticeButton.textContent =
      "저장 중...";
  }


  try {
    const response =
      await fetch(
        GLOBAL_NOTICE_API_URL,
        {
          method:
            "POST",

          headers:
            getShiftLogAuthHeaders(),

          body:
            formData
        }
      );


    const result =
      await parseGlobalNoticeResponse(
        response
      );


    if (
      !response.ok ||
      result.ok ===
        false ||
      result.success ===
        false
    ) {
      throw new Error(
        result.message ||
        result.error ||
        `전체공지 저장 실패 (HTTP ${response.status})`
      );
    }


    closeGlobalNoticeEditor();


    await loadGlobalNotices();


    renderGlobalNoticeList();


    showToast(
      globalNoticeState.editingNoticeId
        ? "전체공지가 수정되었습니다."
        : "전체공지가 등록되었습니다.",
      1600
    );

  } catch (
    error
  ) {
    console.error(
      "전체공지 저장 오류:",
      error
    );


    showGlobalNoticeEditorMessage(
      error.message ||
      "전체공지를 저장하지 못했습니다."
    );

  } finally {
    if (
      noticeElements.saveGlobalNoticeButton
    ) {
      noticeElements.saveGlobalNoticeButton.disabled =
        false;

      noticeElements.saveGlobalNoticeButton.textContent =
        "저장";
    }
  }
}


/* =========================================================
  전체공지 삭제
========================================================= */

async function deleteGlobalNotice(
  noticeId
) {
  const notice =
    globalNoticeState.notices.find(
      item => {
        return (
          String(
            item.id
          ) ===
          String(
            noticeId
          )
        );
      }
    );


  if (
    !notice
  ) {
    showToast(
      "삭제할 전체공지를 찾을 수 없습니다."
    );

    return;
  }


  const shouldDelete =
    await showCompactConfirm({
      title:
        "전체공지 삭제",

      message:
        `"${notice.title}" 공지를 삭제하시겠습니까? 첨부자료도 함께 삭제됩니다.`,

      confirmText:
        "삭제",

      cancelText:
        "취소"
    });


  if (
    !shouldDelete
  ) {
    return;
  }


  try {
    const response =
      await fetch(
        `${GLOBAL_NOTICE_API_URL}?id=${encodeURIComponent(
          notice.id
        )}`,
        {
          method:
            "DELETE",

          headers:
            getShiftLogAuthHeaders()
        }
      );


    const result =
      await parseGlobalNoticeResponse(
        response
      );


    if (
      !response.ok ||
      result.ok ===
        false ||
      result.success ===
        false
    ) {
      throw new Error(
        result.message ||
        result.error ||
        `전체공지 삭제 실패 (HTTP ${response.status})`
      );
    }


    await loadGlobalNotices();


    renderGlobalNoticeList();


    showToast(
      "전체공지가 삭제되었습니다.",
      1600
    );

  } catch (
    error
  ) {
    console.error(
      "전체공지 삭제 오류:",
      error
    );


    showToast(
      error.message ||
      "전체공지를 삭제하지 못했습니다.",
      2200
    );
  }
}


/* =========================================================
  12시간 숨김 저장 키

  사용자 + 공지별로 분리한다.
========================================================= */

function getGlobalNoticeHideStorageKey(
  noticeId
) {
  const currentUser =
    loadCurrentUser();


  const employeeNo =
    getShiftLogUserEmployeeNo(
      currentUser
    ) ||
    "unknown";


  return [
    GLOBAL_NOTICE_HIDE_STORAGE_PREFIX,
    employeeNo,
    String(
      noticeId ||
      ""
    )
  ].join("||");
}


/* =========================================================
  현재 공지가 12시간 숨김 상태인지 확인
========================================================= */

function isGlobalNoticeHidden(
  noticeId
) {
  const storageKey =
    getGlobalNoticeHideStorageKey(
      noticeId
    );


  const hiddenUntil =
    Number(
      localStorage.getItem(
        storageKey
      ) ||
      0
    );


  if (
    !hiddenUntil
  ) {
    return false;
  }


  if (
    Date.now() >=
    hiddenUntil
  ) {
    localStorage.removeItem(
      storageKey
    );

    return false;
  }


  return true;
}


/* =========================================================
  전체공지 12시간 숨김 저장
========================================================= */

function hideGlobalNoticeForTwelveHours(
  noticeId
) {
  const storageKey =
    getGlobalNoticeHideStorageKey(
      noticeId
    );


  const hiddenUntil =
    Date.now() +
    (
      12 *
      60 *
      60 *
      1000
    );


  localStorage.setItem(
    storageKey,
    String(
      hiddenUntil
    )
  );
}


/* =========================================================
  자동 팝업 표시 대상 구성 최종본

  - 중요·긴급 활성 공지만 표시
  - 12시간 숨김 공지 제외
  - 현재 열려 있는 공지 제외
  - 현재 페이지에서 이미 표시한 공지 제외
  - 중복 초기화되어도 같은 공지를 다시 띄우지 않음
========================================================= */

function buildGlobalNoticeAlertQueue() {
  const currentAlertNoticeId =
    String(
      globalNoticeState
        .currentAlertNoticeId ||
      ""
    ).trim();


  const queuedNoticeIds =
    new Set();


  globalNoticeState.alertQueue =
    globalNoticeState.notices
      .filter(
        notice => {
          const noticeId =
            String(
              notice?.id ||
              ""
            ).trim();


          const priority =
            normalizeGlobalNoticePriority(
              notice?.priority
            );


          if (
            !noticeId ||
            queuedNoticeIds.has(
              noticeId
            ) ||
            currentAlertNoticeId ===
              noticeId ||
            globalNoticeState
              .shownAlertNoticeIds
              .has(
                noticeId
              )
          ) {
            return false;
          }


          const shouldShow =
            getGlobalNoticeStatus(
              notice
            ) ===
              "active" &&

            [
              "important",
              "urgent"
            ].includes(
              priority
            ) &&

            !isGlobalNoticeHidden(
              noticeId
            );


          if (
            shouldShow
          ) {
            queuedNoticeIds.add(
              noticeId
            );
          }


          return shouldShow;
        }
      )
      .sort(
        (
          firstNotice,
          secondNotice
        ) => {
          const priorityOrder = {
            urgent:
              2,

            important:
              1,

            normal:
              0
          };


          return (
            priorityOrder[
              normalizeGlobalNoticePriority(
                secondNotice.priority
              )
            ] -
            priorityOrder[
              normalizeGlobalNoticePriority(
                firstNotice.priority
              )
            ]
          );
        }
      );
}


/* =========================================================
  중요·긴급 공지 팝업 출력
========================================================= */

function showNextGlobalNoticeAlert() {
  const noticeElements =
    getGlobalNoticeElements();


  if (
    noticeElements
      .globalNoticeAlertModal
      ?.classList.contains(
        "is-open"
      )
  ) {
    return;
  }


  const notice =
    globalNoticeState.alertQueue.shift();


  if (
    !notice
  ) {
    globalNoticeState.currentAlertNoticeId =
      "";

    return;
  }


  const priority =
    normalizeGlobalNoticePriority(
      notice.priority
    );


  const attachments =
    Array.isArray(
      notice.attachments
    )
      ? notice.attachments
      : [];


  globalNoticeState.currentAlertNoticeId =
    notice.id;

    /*
  실제로 표시하는 순간 기록한다.
  다른 초기화가 다시 실행되어도
  같은 공지가 대기열에 들어가지 않는다.
*/
globalNoticeState
  .shownAlertNoticeIds
  .add(
    String(
      notice.id
    )
  );


  if (
    noticeElements.globalNoticeAlertNoticeId
  ) {
    noticeElements.globalNoticeAlertNoticeId.value =
      notice.id;
  }


  if (
    noticeElements.globalNoticeAlertTitle
  ) {
    noticeElements.globalNoticeAlertTitle.textContent =
      notice.title ||
      "전체공지";
  }


  if (
    noticeElements.globalNoticeAlertPriorityBadge
  ) {
    noticeElements
      .globalNoticeAlertPriorityBadge
      .textContent =
      getGlobalNoticePriorityLabel(
        priority
      );


    noticeElements
      .globalNoticeAlertPriorityBadge
      .className =
      [
        "global-notice-priority-badge",
        `is-${priority}`
      ].join(" ");
  }


  if (
    noticeElements.globalNoticeAlertPeriod
  ) {
    noticeElements.globalNoticeAlertPeriod.textContent =
      [
        formatGlobalNoticeDate(
          notice.startDate
        ),

        "~",

        formatGlobalNoticeDate(
          notice.endDate
        )
      ].join(" ");
  }


  if (
    noticeElements.globalNoticeAlertContent
  ) {
    noticeElements.globalNoticeAlertContent.textContent =
      notice.content;
  }


  if (
    noticeElements
      .globalNoticeAlertAttachmentSection
  ) {
    noticeElements
      .globalNoticeAlertAttachmentSection
      .hidden =
      attachments.length ===
      0;
  }


  if (
    noticeElements
      .globalNoticeAlertAttachmentCount
  ) {
    noticeElements
      .globalNoticeAlertAttachmentCount
      .textContent =
      `${attachments.length}개`;
  }


  if (
    noticeElements
      .globalNoticeAlertAttachmentList
  ) {
    noticeElements
      .globalNoticeAlertAttachmentList
      .innerHTML =
      attachments
        .map(
          attachment => {
            const fileName =
              attachment.fileName ||
              attachment.name ||
              "첨부자료";


            return `
              <a
                href="${escapeHtml(
                  attachment.url ||
                  "#"
                )}"
                class="global-notice-alert-attachment-link"
                target="_blank"
                rel="noopener noreferrer"
                download
              >
                📎
                ${escapeHtml(
                  fileName
                )}
              </a>
            `;
          }
        )
        .join("");
  }


  if (
    noticeElements
      .globalNoticeHideForTwelveHours
  ) {
    noticeElements
      .globalNoticeHideForTwelveHours
      .checked =
      false;
  }


  noticeElements.globalNoticeAlertModal
    ?.classList.toggle(
      "is-urgent",
      priority ===
        "urgent"
    );


  openModal(
    noticeElements.globalNoticeAlertModal
  );
}


/* =========================================================
  중요·긴급 공지 팝업 닫기
========================================================= */

function closeGlobalNoticeAlert() {
  const noticeElements =
    getGlobalNoticeElements();


  const noticeId =
    String(
      globalNoticeState
        .currentAlertNoticeId ||
      noticeElements
        .globalNoticeAlertNoticeId
        ?.value ||
      ""
    ).trim();


  if (
    noticeId &&
    noticeElements
      .globalNoticeHideForTwelveHours
      ?.checked
  ) {
    hideGlobalNoticeForTwelveHours(
      noticeId
    );
  }


  if (
    noticeElements.globalNoticeAlertModal
  ) {
    closeModal(
      noticeElements.globalNoticeAlertModal
    );
  }


  globalNoticeState.currentAlertNoticeId =
    "";


  window.setTimeout(
    showNextGlobalNoticeAlert,
    180
  );
}


/* =========================================================
  로그인 후 중요·긴급 공지 자동 확인
========================================================= */

async function checkGlobalNoticeAlerts() {
  if (
    !loadCurrentUser()
  ) {
    return;
  }


  await loadGlobalNotices();


  buildGlobalNoticeAlertQueue();


  showNextGlobalNoticeAlert();
}


/* =========================================================
  전체공지 이벤트
========================================================= */

function bindGlobalNoticeEvents() {
  if (
    globalNoticeState.eventsBound
  ) {
    return;
  }


  const noticeElements =
    getGlobalNoticeElements();


  if (
    !noticeElements.globalNoticeModal
  ) {
    return;
  }


  globalNoticeState.eventsBound =
    true;


  noticeElements.noticeButton
    ?.addEventListener(
      "click",
      openGlobalNoticeModal
    );


  noticeElements.closeGlobalNoticeModalButton
    ?.addEventListener(
      "click",
      closeGlobalNoticeModal
    );


  noticeElements.closeGlobalNoticeModalFooterButton
    ?.addEventListener(
      "click",
      closeGlobalNoticeModal
    );


  noticeElements.openGlobalNoticeEditorButton
    ?.addEventListener(
      "click",
      openNewGlobalNoticeEditor
    );


  noticeElements.closeGlobalNoticeEditorButton
    ?.addEventListener(
      "click",
      closeGlobalNoticeEditor
    );


  noticeElements.cancelGlobalNoticeEditorButton
    ?.addEventListener(
      "click",
      closeGlobalNoticeEditor
    );


  noticeElements.globalNoticeEditorForm
    ?.addEventListener(
      "submit",
      saveGlobalNotice
    );


  noticeElements.globalNoticeContentInput
    ?.addEventListener(
      "input",
      () => {
        const length =
          noticeElements
            .globalNoticeContentInput
            .value
            .length;


        if (
          noticeElements
            .globalNoticeCharacterCount
        ) {
          noticeElements
            .globalNoticeCharacterCount
            .textContent =
            `${length} / 5000`;
        }
      }
    );


  noticeElements.filterButtons
    .forEach(
      button => {
        button.addEventListener(
          "click",
          () => {
            const filter =
              String(
                button.dataset
                  .globalNoticeFilter ||
                "active"
              ).trim();


            globalNoticeState.currentFilter =
              filter;


            noticeElements.filterButtons
              .forEach(
                currentButton => {
                  currentButton.classList.toggle(
                    "is-active",
                    currentButton ===
                      button
                  );
                }
              );


            renderGlobalNoticeList();
          }
        );
      }
    );


  noticeElements.globalNoticeList
    ?.addEventListener(
      "click",
      event => {
        const editButton =
          event.target.closest(
            "[data-global-notice-edit]"
          );


        if (
          editButton
        ) {
          openGlobalNoticeEditor(
            editButton.dataset
              .globalNoticeEdit
          );

          return;
        }


        const deleteButton =
          event.target.closest(
            "[data-global-notice-delete]"
          );


        if (
          deleteButton
        ) {
          deleteGlobalNotice(
            deleteButton.dataset
              .globalNoticeDelete
          );
        }
      }
    );


  noticeElements.globalNoticeFileInput
    ?.addEventListener(
      "change",
      event => {
        addGlobalNoticeFiles(
          event.target.files
        );


        event.target.value =
          "";
      }
    );


  noticeElements.globalNoticeFileDropzone
    ?.addEventListener(
      "dragover",
      event => {
        event.preventDefault();


        noticeElements
          .globalNoticeFileDropzone
          .classList.add(
            "is-dragover"
          );
      }
    );


  noticeElements.globalNoticeFileDropzone
    ?.addEventListener(
      "dragleave",
      () => {
        noticeElements
          .globalNoticeFileDropzone
          .classList.remove(
            "is-dragover"
          );
      }
    );


  noticeElements.globalNoticeFileDropzone
    ?.addEventListener(
      "drop",
      event => {
        event.preventDefault();


        noticeElements
          .globalNoticeFileDropzone
          .classList.remove(
            "is-dragover"
          );


        addGlobalNoticeFiles(
          event.dataTransfer
            ?.files
        );
      }
    );


  noticeElements.globalNoticeSelectedFileList
    ?.addEventListener(
      "click",
      event => {
        const removeButton =
          event.target.closest(
            "[data-global-notice-file-remove]"
          );


        if (
          !removeButton
        ) {
          return;
        }


        const fileIndex =
          Number(
            removeButton.dataset
              .globalNoticeFileRemove
          );


        if (
          !Number.isInteger(
            fileIndex
          )
        ) {
          return;
        }


        globalNoticeState.selectedFiles.splice(
          fileIndex,
          1
        );


        renderGlobalNoticeSelectedFiles();
      }
    );


  noticeElements.globalNoticeExistingAttachmentList
    ?.addEventListener(
      "click",
      event => {
        const removeButton =
          event.target.closest(
            "[data-global-notice-existing-remove]"
          );


        if (
          !removeButton
        ) {
          return;
        }


        const attachmentId =
          String(
            removeButton.dataset
              .globalNoticeExistingRemove ||
            ""
          ).trim();


        if (
          attachmentId &&
          !globalNoticeState
            .deletedAttachmentIds
            .includes(
              attachmentId
            )
        ) {
          globalNoticeState
            .deletedAttachmentIds
            .push(
              attachmentId
            );
        }


        renderGlobalNoticeExistingAttachments();
      }
    );


  noticeElements.closeGlobalNoticeAlertButton
    ?.addEventListener(
      "click",
      closeGlobalNoticeAlert
    );


  noticeElements.closeGlobalNoticeAlertFooterButton
    ?.addEventListener(
      "click",
      closeGlobalNoticeAlert
    );


  /*
    목록창·작성창·자동 팝업 모두
    바깥 배경 클릭으로 닫히지 않게 한다.
  */
  [
    noticeElements.globalNoticeModal,
    noticeElements.globalNoticeEditorModal,
    noticeElements.globalNoticeAlertModal
  ]
    .filter(Boolean)
    .forEach(
      modal => {
        modal.addEventListener(
          "click",
          event => {
            if (
              event.target ===
              modal
            ) {
              event.preventDefault();

              event.stopPropagation();
            }
          }
        );
      }
    );


  document.addEventListener(
    "keydown",
    event => {
      if (
        event.key !==
        "Escape"
      ) {
        return;
      }


      if (
        noticeElements
          .globalNoticeAlertModal
          ?.classList.contains(
            "is-open"
          )
      ) {
        closeGlobalNoticeAlert();

        return;
      }


      if (
        noticeElements
          .globalNoticeEditorModal
          ?.classList.contains(
            "is-open"
          )
      ) {
        closeGlobalNoticeEditor();

        return;
      }


      if (
        noticeElements
          .globalNoticeModal
          ?.classList.contains(
            "is-open"
          )
      ) {
        closeGlobalNoticeModal();
      }
    }
  );
}


/* =========================================================
  전체공지 초기화
========================================================= */

async function initializeGlobalNotices(
  options = {}
) {
  const {
    showAlerts =
      true
  } = options;


  const noticeElements =
    getGlobalNoticeElements();


  /*
    전체공지 HTML이 아직 적용되지 않았으면
    기존 업무일지 기능에는 영향을 주지 않는다.
  */
  if (
    !noticeElements.globalNoticeModal
  ) {
    return;
  }


  bindGlobalNoticeEvents();


  updateGlobalNoticeHeaderButton();


  if (
    !loadCurrentUser()
  ) {
    return;
  }


  await loadGlobalNotices();


  renderGlobalNoticeList();


  if (
    showAlerts
  ) {
    buildGlobalNoticeAlertQueue();

    showNextGlobalNoticeAlert();
  }
}


/* =========================================================
  페이지 진입 시 전체공지 초기화
========================================================= */

document.addEventListener(
  "DOMContentLoaded",
  () => {
    initializeGlobalNotices({
      showAlerts:
        true
    });
  }
);


/* =========================================================
  로그인 완료 시 전체공지 다시 확인

  기존 openShiftLogApp()을 감싸는 방식이므로
  기존 로그인 함수 전체를 교체할 필요가 없다.

  적용 효과:
  - 새 로그인 성공
  - 저장된 로그인 복원

  모두 중요·긴급 공지를 자동 확인한다.
========================================================= */

const originalOpenShiftLogAppForGlobalNotice =
  openShiftLogApp;


openShiftLogApp = function (
  user
) {
  originalOpenShiftLogAppForGlobalNotice(
    user
  );


  window.setTimeout(
    () => {
      initializeGlobalNotices({
        showAlerts:
          true
      });
    },
    100
  );
};

/* =========================================================
  조회 결과 = 기존 업무일지 미리보기 그대로 재사용

  적용:
  - PC 조회:
    createLogRowHtml()의 기존 미리보기 복사

  - 모바일 조회:
    createMobileLogCardHtml()의 기존 카드 복사

  - 조회 미리보기에서는 운전현황만 제외
  - 검색어 노란색 강조 유지
  - 조회 화면에서는 수정 버튼 제거
========================================================= */


/* =========================================================
  현재 검색어
========================================================= */

function getCurrentSearchKeyword() {
  return String(
    document.getElementById(
      "searchKeyword"
    )?.value ||
    ""
  ).trim();
}


/* =========================================================
  정규식 특수문자 처리
========================================================= */

function escapeSearchKeywordRegExp(
  value
) {
  return String(
    value ||
    ""
  ).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


/* =========================================================
  검색어 노란색 강조

  PC·모바일 공통 적용
========================================================= */

function highlightSearchKeywordInElement(
  rootElement,
  keyword
) {
  if (
    !rootElement ||
    !keyword
  ) {
    return;
  }


  const searchPattern =
    new RegExp(
      `(${escapeSearchKeywordRegExp(
        keyword
      )})`,
      "gi"
    );


  const matchedTextNodes =
    [];


  const treeWalker =
    document.createTreeWalker(
      rootElement,
      NodeFilter.SHOW_TEXT,
      {
        acceptNode(
          textNode
        ) {
          const text =
            String(
              textNode.nodeValue ||
              ""
            );


          const parentElement =
            textNode.parentElement;


          if (
            !text.trim() ||
            !parentElement ||
            parentElement.closest(
              ".search-keyword-highlight"
            )
          ) {
            return NodeFilter.FILTER_REJECT;
          }


          searchPattern.lastIndex =
            0;


          return searchPattern.test(
            text
          )
            ? NodeFilter.FILTER_ACCEPT
            : NodeFilter.FILTER_REJECT;
        }
      }
    );


  while (
    treeWalker.nextNode()
  ) {
    matchedTextNodes.push(
      treeWalker.currentNode
    );
  }


  matchedTextNodes.forEach(
    textNode => {
      const text =
        String(
          textNode.nodeValue ||
          ""
        );


      searchPattern.lastIndex =
        0;


      const parts =
        text.split(
          searchPattern
        );


      const fragment =
        document.createDocumentFragment();


      parts.forEach(
        (
          part,
          partIndex
        ) => {
          if (
            !part
          ) {
            return;
          }


          if (
            partIndex % 2 ===
            1
          ) {
            const mark =
              document.createElement(
                "mark"
              );


            mark.className =
              "search-keyword-highlight";


            mark.textContent =
              part;


            fragment.appendChild(
              mark
            );


            return;
          }


          fragment.appendChild(
            document.createTextNode(
              part
            )
          );
        }
      );


      textNode.replaceWith(
        fragment
      );
    }
  );
}


/* =========================================================
  조회 미리보기 TAG 연결 정리

  기존 미리보기의 data-log-tag를
  조회 이벤트에서 사용하는 data-search-tag로 변경한다.
========================================================= */

function normalizeSearchPreviewTagElements(
  rootElement
) {
  if (
    !rootElement
  ) {
    return;
  }


  rootElement
    .querySelectorAll(
      `
        .log-preview__tag,
        .mobile-log-preview-item__tag
      `
    )
    .forEach(
      sourceElement => {
        const normalizedTag =
          String(
            sourceElement.dataset
              .searchTag ||
            sourceElement.dataset
              .logTag ||
            sourceElement.textContent ||
            ""
          )
            .trim()
            .replace(
              /^[\[【]\s*/,
              ""
            )
            .replace(
              /\s*[\]】]$/,
              ""
            )
            .trim()
            .toUpperCase();


        if (
          !normalizedTag
        ) {
          return;
        }


        let targetElement =
          sourceElement;


        /*
          카드 본문 자체가 button이므로
          내부 TAG가 button이면 중첩 버튼이 된다.

          TAG가 button인 경우 span으로 바꾼 뒤
          기존 모양과 클릭 기능을 유지한다.
        */
        if (
          sourceElement.tagName ===
          "BUTTON"
        ) {
          const replacement =
            document.createElement(
              "span"
            );


          replacement.className =
            sourceElement.className;


          replacement.innerHTML =
            sourceElement.innerHTML;


          sourceElement.replaceWith(
            replacement
          );


          targetElement =
            replacement;
        }


        targetElement.dataset.searchTag =
          normalizedTag;


        targetElement.removeAttribute(
          "data-log-tag"
        );


        targetElement.removeAttribute(
          "data-action"
        );


        targetElement.removeAttribute(
          "data-log-id"
        );


        targetElement.setAttribute(
          "role",
          "button"
        );


        targetElement.setAttribute(
          "tabindex",
          "0"
        );


        targetElement.setAttribute(
          "title",
          "Facility Navigator에서 설비 보기"
        );
      }
    );
}


/* =========================================================
  PC 조회 결과

  별도 조회용 미리보기를 만들지 않는다.

  메인 업무일지 표의 createLogRowHtml() 결과에서
  .log-preview 내부를 그대로 복사한다.
========================================================= */

createSearchLogPreviewHtml =
  function createSearchLogPreviewHtml(
    log
  ) {
    const template =
      document.createElement(
        "template"
      );


    template.innerHTML = `
      <table>
        <tbody>
          ${createLogRowHtml(
            log
          )}
        </tbody>
      </table>
    `;


    const previewElement =
      template.content
        .querySelector(
          ".log-preview"
        );


    if (
      !previewElement
    ) {
      return `
        <span class="log-preview__empty">
          등록된 업무 내용이 없습니다.
        </span>
      `;
    }


    /*
      조회 목록 미리보기에서는
      운전현황을 표시하지 않는다.

      상세보기에서는 기존처럼 표시된다.
    */
    previewElement
      .querySelectorAll(
        `
          .log-preview__group.is-operation,
          .log-preview__group.is-operation-dashboard
        `
      )
      .forEach(
        element => {
          element.remove();
        }
      );


    normalizeSearchPreviewTagElements(
      previewElement
    );


    highlightSearchKeywordInElement(
      previewElement,
      getCurrentSearchKeyword()
    );


    const hasVisibleContent =
      Boolean(
        previewElement.querySelector(
          `
            .log-preview__group,
            .log-preview__role-section
          `
        )
      );


    return `
      <span
        class="
          log-preview
          search-result-log-preview
        "
      >
        ${
          hasVisibleContent
            ? previewElement.innerHTML
            : `
              <span class="log-preview__empty">
                운전현황 외 등록된 업무 내용이 없습니다.
              </span>
            `
        }
      </span>
    `;
  };


/* =========================================================
  모바일 조회 결과

  별도 mobile-search-card를 새로 만들지 않는다.

  현황 화면에서 사용하는 createMobileLogCardHtml()의
  결과를 그대로 복사한 뒤 조회 화면에 필요한
  날짜·근무 정보만 추가한다.
========================================================= */

createMobileSearchCardHtml =
  function createMobileSearchCardHtml(
    log
  ) {
    const template =
      document.createElement(
        "template"
      );


    template.innerHTML =
      String(
        createMobileLogCardHtml(
          log
        ) ||
        ""
      ).trim();


    const cardElement =
      template.content
        .querySelector(
          ".mobile-log-card"
        );


    if (
      !cardElement
    ) {
      return "";
    }


    const logId =
      String(
        log?.id ||
        ""
      ).trim();


    /*
      기존 모바일 카드 구조 유지
    */
    cardElement.classList.add(
      "search-reused-log-card"
    );


    cardElement.setAttribute(
      "data-search-log-id",
      logId
    );


    cardElement.removeAttribute(
      "data-mobile-log-id"
    );


    /*
      카드 본문 전체 클릭 유지
    */
    const openButton =
      cardElement.querySelector(
        ".mobile-log-card__open"
      );


    if (
      openButton
    ) {
      openButton.setAttribute(
        "data-search-view",
        logId
      );


      openButton.removeAttribute(
        "data-action"
      );


      openButton.removeAttribute(
        "data-log-id"
      );


      /*
        조회 결과 날짜·근무 추가
      */
      openButton.insertAdjacentHTML(
        "afterbegin",
        `
          <div class="search-reused-log-card__date-row">

            <strong>
              ${escapeHtml(
                log?.date ||
                "-"
              )}
            </strong>

            <span>
              ${escapeHtml(
                getShiftDisplayName(
                  log?.shift
                )
              )}
            </span>

          </div>
        `
      );
    }


    const previewElement =
      cardElement.querySelector(
        ".mobile-log-card__preview"
      );


    if (
      previewElement
    ) {
      /*
        조회 목록에서는 운전현황 제외
      */
      previewElement
        .querySelectorAll(
          ".mobile-log-preview-section.is-operation"
        )
        .forEach(
          element => {
            element.remove();
          }
        );


      /*
        TAG 클릭 기능 유지
      */
      normalizeSearchPreviewTagElements(
        previewElement
      );


      /*
        검색어 강조 유지
      */
      highlightSearchKeywordInElement(
        previewElement,
        getCurrentSearchKeyword()
      );


      if (
        !previewElement.querySelector(
          ".mobile-log-preview-section"
        )
      ) {
        previewElement.innerHTML = `
          <p class="mobile-log-card__empty">
            운전현황 외 등록된 업무 내용이 없습니다.
          </p>
        `;
      }
    }


    /*
      조회 화면에서는
      수정·삭제·이어쓰기·상세보기 버튼 제거
    */
    cardElement
      .querySelectorAll(
        `
          .mobile-log-card__edit-button,
          .mobile-log-card__edit-disabled,
          .mobile-log-card__delete-button,
          .mobile-log-card__detail-button
        `
      )
      .forEach(
        element => {
          element.remove();
        }
      );


    const footerElement =
      cardElement.querySelector(
        ".mobile-log-card__footer"
      );


    if (
      footerElement
    ) {
      footerElement.classList.add(
        "mobile-log-card__footer--search"
      );


      footerElement.classList.remove(
        "has-edit-action",
        "has-delete-action"
      );


      /*
        첨부 표시 기능 유지
      */
      footerElement
        .querySelectorAll(
          ".mobile-log-card__attachment-button"
        )
        .forEach(
          button => {
            button.setAttribute(
              "data-search-view",
              logId
            );


            button.removeAttribute(
              "data-action"
            );


            button.removeAttribute(
              "data-log-id"
            );
          }
        );
    }


    return cardElement.outerHTML;
  };

  /* =========================================================
  업무일지 상세보기 삭제 버튼 최종 연결

  일반회원:
  - 본인이 작성한 임시저장 일지만 삭제 가능
  - 결재요청·결재완료에서는 삭제 불가

  파트장:
  - 본인이 작성한 파트장 저장완료 일지 삭제 가능

  최고관리자:
  - 신규 업무일지 삭제 가능

  과거 연동 일지:
  - 삭제 불가
========================================================= */


/* =========================================================
  상세보기 삭제 권한
========================================================= */

function canCurrentUserDeleteShiftLogFromDetail(
  log
) {
  if (
    !log ||
    typeof log !==
      "object"
  ) {
    return false;
  }


  /*
    과거 업무일지는 삭제 불가
  */
  if (
    isReadOnlyLegacyShiftLog(
      log
    )
  ) {
    return false;
  }


  /*
    최고관리자
  */
  if (
    isCurrentUserSuperAdmin()
  ) {
    return true;
  }


  /*
    최고관리자가 아니면
    반드시 본인이 작성한 일지여야 한다.
  */
  if (
    !isCurrentUserShiftLogAuthor(
      log
    )
  ) {
    return false;
  }


  const normalizedStatus =
    normalizeShiftLogApprovalStatus(
      log.status
    );


  /*
    일반 보직:
    본인 임시저장 일지
  */
  if (
    normalizedStatus ===
    "임시저장"
  ) {
    return true;
  }


  /*
    파트장:
    본인의 파트장 저장완료 일지
  */
  return (
    isCurrentShiftLogLeader() &&

    normalizeMemberLogRole(
      log.role
    ) ===
      "파트장" &&

    normalizedStatus ===
      "저장완료"
  );
}


/* =========================================================
  기존 상세보기 버튼 갱신 함수 보존
========================================================= */

const updateShiftLogDetailActionButtonsBeforeDeleteSupport =
  updateShiftLogDetailActionButtons;


/* =========================================================
  삭제 버튼이 포함된 상세보기 버튼 갱신
========================================================= */

updateShiftLogDetailActionButtons =
  function updateShiftLogDetailActionButtons(
    log
  ) {
    /*
      기존 결재취소·결재완료·수정 표시 규칙 실행
    */
    updateShiftLogDetailActionButtonsBeforeDeleteSupport(
      log
    );


    const deleteButton =
      document.getElementById(
        "deleteFromDetailButton"
      );


    if (
      !deleteButton
    ) {
      return;
    }


    const canDelete =
      canCurrentUserDeleteShiftLogFromDetail(
        log
      );


    deleteButton.hidden =
      !canDelete;


    deleteButton.disabled =
      !canDelete;


    deleteButton.setAttribute(
      "aria-hidden",
      String(
        !canDelete
      )
    );


    if (
      canDelete
    ) {
      deleteButton.removeAttribute(
        "hidden"
      );


      deleteButton.style.removeProperty(
        "display"
      );

    } else {
      deleteButton.setAttribute(
        "hidden",
        ""
      );
    }
  };


/* =========================================================
  현재 상세 업무일지 삭제
========================================================= */

async function deleteCurrentDetailShiftLog() {
  const targetLog =
    getCurrentDetailShiftLog();


  if (
    !targetLog
  ) {
    showToast(
      "삭제할 업무일지를 찾을 수 없습니다."
    );


    return;
  }


  if (
    !canCurrentUserDeleteShiftLogFromDetail(
      targetLog
    )
  ) {
    const normalizedStatus =
      normalizeShiftLogApprovalStatus(
        targetLog.status
      );


    showToast(
      normalizedStatus ===
        "결재요청"
        ? "결재요청을 취소한 후 삭제할 수 있습니다."
        : "현재 상태에서는 이 업무일지를 삭제할 수 없습니다."
    );


    return;
  }


  const targetLogId =
    String(
      targetLog.id ||
      ""
    ).trim();


  await deleteLogById(
    targetLogId
  );


  /*
    서버 삭제 성공 후 appState에서 사라졌는지 확인한다.

    삭제 실패 시 상세창은 그대로 유지한다.
  */
  const logStillExists =
    appState.logs.some(
      log => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          targetLogId
        );
      }
    );


  if (
    !logStillExists
  ) {
    closeLogDetail();
  }
}


/* =========================================================
  상세보기 삭제 이벤트 연결
========================================================= */

function initializeShiftLogDetailDeleteAction() {
  const deleteButton =
    document.getElementById(
      "deleteFromDetailButton"
    );


  if (
    !deleteButton ||
    deleteButton.dataset
      .deleteEventBound ===
      "true"
  ) {
    return;
  }


  deleteButton.dataset
    .deleteEventBound =
    "true";


  deleteButton.addEventListener(
    "click",
    deleteCurrentDetailShiftLog
  );
}


if (
  document.readyState ===
  "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeShiftLogDetailDeleteAction
  );

} else {
  initializeShiftLogDetailDeleteAction();
}

/* =========================================================
  날짜 ±7일·±30일 빠른 이동

  적용:
  - 선택한 D/S 또는 N/S는 그대로 유지
  - 날짜만 ±7일·±30일 이동
  - 이동 후 D1 최신 데이터 재조회
  - 과거 업무일지 재조회
========================================================= */

let isQuickDateJumpRunning =
  false;


/* =========================================================
  날짜 단위 이동
========================================================= */

async function jumpSelectedDateByDays(
  dayOffset
) {
  const normalizedOffset =
    Number(
      dayOffset
    );


  if (
    !Number.isInteger(
      normalizedOffset
    ) ||
    normalizedOffset ===
      0 ||
    isQuickDateJumpRunning
  ) {
    return;
  }


  isQuickDateJumpRunning =
    true;


  const quickButtons = [
    ...document.querySelectorAll(
      "[data-date-jump-days]"
    )
  ];


  quickButtons.forEach(
    button => {
      button.disabled =
        true;
    }
  );


  try {
    const nextDate =
      new Date(
        appState.selectedDate
      );


    nextDate.setDate(
      nextDate.getDate() +
      normalizedOffset
    );


    /*
      시간값을 제거하고 날짜만 저장한다.

      현재 선택된 D/S·N/S는 변경하지 않는다.
    */
    appState.selectedDate =
      new Date(
        nextDate.getFullYear(),
        nextDate.getMonth(),
        nextDate.getDate()
      );


    renderSelectedDate();


    /*
      다른 PC에서 저장한 최신 D1 자료 갱신
    */
    if (
      typeof refreshSharedShiftLogsInState ===
      "function"
    ) {
      await refreshSharedShiftLogsInState();
    }


    /*
      선택 날짜의 과거·연동 업무일지 로딩
    */
    if (
      typeof loadLegacyLogsForSelectedDate ===
      "function"
    ) {
      await loadLegacyLogsForSelectedDate();
    }


    renderLogTable();

    updateShiftMemberCardStates();

  } catch (
    error
  ) {
    console.error(
      "날짜 빠른 이동 실패:",
      error
    );


    showToast(
      "날짜를 이동하지 못했습니다. 다시 시도해 주세요."
    );

  } finally {
    isQuickDateJumpRunning =
      false;


    quickButtons.forEach(
      button => {
        button.disabled =
          false;
      }
    );
  }
}


/* =========================================================
  날짜 빠른 이동 버튼 이벤트
========================================================= */

function initializeDateQuickNavigation() {
  document
    .querySelectorAll(
      "[data-date-jump-days]"
    )
    .forEach(
      button => {
        if (
          button.dataset
            .quickJumpBound ===
            "true"
        ) {
          return;
        }


        button.dataset
          .quickJumpBound =
          "true";


        button.addEventListener(
          "click",
          () => {
            jumpSelectedDateByDays(
              button.dataset
                .dateJumpDays
            );
          }
        );
      }
    );
}


if (
  document.readyState ===
  "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeDateQuickNavigation
  );

} else {
  initializeDateQuickNavigation();
}

/* =========================================================
  모바일 파트장 업무일지 보직별 구분 최종 보정

  적용 결과:
  - TGO → BCO1 → BCO2 보직 제목 표시
  - 보직별 건수 표시
  - 각 보직 번호를 1번부터 다시 시작
  - MutationObserver 반복 실행 방지
  - 모바일 화면 멈춤 현상 방지
  - PC 렌더링 구조는 변경하지 않음

  적용 위치:
  script.js 파일 맨 마지막
========================================================= */

(function initializeMobileLeaderRoleGroupingFix() {
  const MOBILE_BREAKPOINT =
    "(max-width: 768px)";

  let refreshFrameId = 0;
  let isRefreshing = false;

  function isMobileShiftLogScreen() {
    return window.matchMedia(
      MOBILE_BREAKPOINT
    ).matches;
  }

  function getDirectPreviewChildren(
    previewElement
  ) {
    return [
      ...previewElement.children
    ];
  }

  function isRoleSectionElement(
    element
  ) {
    return Boolean(
      element?.classList.contains(
        "log-preview__role-section"
      )
    );
  }

  function isRoleEntryElement(
    element
  ) {
    return Boolean(
      element?.classList.contains(
        "log-preview__group"
      ) &&
      !element.classList.contains(
        "is-operation"
      ) &&
      !element.classList.contains(
        "is-section-start"
      )
    );
  }

  function normalizeRoleSectionTitle(
    titleElement
  ) {
    if (!titleElement) {
      return "";
    }

    const storedTitle =
      String(
        titleElement.dataset
          .mobileOriginalTitle ||
        ""
      ).trim();

    if (storedTitle) {
      return storedTitle;
    }

    const originalTitle =
      String(
        titleElement.textContent ||
        ""
      )
        .replace(
          /\s*\(\s*\d+\s*건\s*\)\s*$/,
          ""
        )
        .trim();

    titleElement.dataset
      .mobileOriginalTitle =
      originalTitle;

    return originalTitle;
  }

  function updateElementText(
    element,
    nextText
  ) {
    if (!element) {
      return false;
    }

    if (
      element.textContent ===
      nextText
    ) {
      return false;
    }

    element.textContent =
      nextText;

    return true;
  }

  function updateElementHidden(
    element,
    nextHidden
  ) {
    if (!element) {
      return false;
    }

    if (
      element.hidden ===
      nextHidden
    ) {
      return false;
    }

    element.hidden =
      nextHidden;

    return true;
  }

  function refreshSingleLeaderPreview(
    previewElement
  ) {
    const directChildren =
      getDirectPreviewChildren(
        previewElement
      );

    const roleSections =
      directChildren.filter(
        isRoleSectionElement
      );

    if (!roleSections.length) {
      return;
    }

    roleSections.forEach(
      roleSection => {
        const titleElement =
          roleSection.querySelector(
            ".log-preview__role-divider"
          );

        let nextElement =
          roleSection.nextElementSibling;

        const roleEntryElements = [];

        while (
          nextElement &&
          !isRoleSectionElement(
            nextElement
          )
        ) {
          if (
            isRoleEntryElement(
              nextElement
            )
          ) {
            roleEntryElements.push(
              nextElement
            );
          }

          nextElement =
            nextElement.nextElementSibling;
        }

        roleEntryElements.forEach(
          (
            entryElement,
            entryIndex
          ) => {
            const numberElement =
              entryElement.querySelector(
                ".log-preview__entry-number"
              );

            const nextNumberText =
              `${entryIndex + 1}.`;

            updateElementText(
              numberElement,
              nextNumberText
            );
          }
        );

        if (titleElement) {
          const originalTitle =
            normalizeRoleSectionTitle(
              titleElement
            );

          const nextTitleText =
            `${originalTitle} (${roleEntryElements.length}건)`;

          updateElementText(
            titleElement,
            nextTitleText
          );
        }

        updateElementHidden(
          roleSection,
          roleEntryElements.length === 0
        );
      }
    );
  }

  function refreshMobileLeaderRoleGrouping(
    rootElement = document
  ) {
    if (
      !isMobileShiftLogScreen() ||
      isRefreshing
    ) {
      return;
    }

    isRefreshing = true;

    try {
      rootElement
        .querySelectorAll(
          "#logTableBody .log-preview"
        )
        .forEach(
          refreshSingleLeaderPreview
        );
    } finally {
      isRefreshing = false;
    }
  }

  function scheduleMobileLeaderRoleGrouping(
    rootElement = document
  ) {
    if (refreshFrameId) {
      return;
    }

    refreshFrameId =
      window.requestAnimationFrame(
        () => {
          refreshFrameId = 0;

          refreshMobileLeaderRoleGrouping(
            rootElement
          );
        }
      );
  }

  /*
    기존 renderLogTable 실행 직후
    모바일 보직 구분을 다시 정리한다.
  */
  const originalRenderLogTable =
    window.renderLogTable;

  if (
    typeof originalRenderLogTable ===
      "function"
  ) {
    window.renderLogTable =
      function renderLogTableWithMobileRoleGrouping(
        ...args
      ) {
        const result =
          originalRenderLogTable.apply(
            this,
            args
          );

        scheduleMobileLeaderRoleGrouping();

        return result;
      };
  }

  function initializeObserver() {
    const logTableBody =
      document.getElementById(
        "logTableBody"
      );

    if (
      !logTableBody ||
      typeof MutationObserver !==
        "function"
    ) {
      return;
    }

    const observerOptions = {
      childList: true,
      subtree: true
    };

    const observer =
      new MutationObserver(
        mutationRecords => {
          if (
            isRefreshing ||
            !isMobileShiftLogScreen()
          ) {
            return;
          }

          const hasMeaningfulChange =
            mutationRecords.some(
              mutationRecord => {
                if (
                  mutationRecord.type !==
                  "childList"
                ) {
                  return false;
                }

                return (
                  mutationRecord.addedNodes
                    .length > 0 ||
                  mutationRecord.removedNodes
                    .length > 0
                );
              }
            );

          if (!hasMeaningfulChange) {
            return;
          }

          if (refreshFrameId) {
            return;
          }

          refreshFrameId =
            window.requestAnimationFrame(
              () => {
                refreshFrameId = 0;

                /*
                  번호와 제목을 수정하는 동안에는
                  MutationObserver를 잠시 중지한다.
                */
                observer.disconnect();

                try {
                  refreshMobileLeaderRoleGrouping(
                    logTableBody
                  );
                } finally {
                  observer.observe(
                    logTableBody,
                    observerOptions
                  );
                }
              }
            );
        }
      );

    observer.observe(
      logTableBody,
      observerOptions
    );
  }

  function initializeMobileLeaderGrouping() {
    scheduleMobileLeaderRoleGrouping();
    initializeObserver();
  }

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      initializeMobileLeaderGrouping,
      {
        once: true
      }
    );
  } else {
    initializeMobileLeaderGrouping();
  }

  window.addEventListener(
    "resize",
    () => {
      scheduleMobileLeaderRoleGrouping();
    },
    {
      passive: true
    }
  );
})();

/* =========================================================
  TAG / Facility Navigator 최종본

  - 네비게이터 전용 탭 하나만 사용
  - 해당 탭의 로그인 상태 유지
  - 클릭한 TAG 주소로 같은 탭 이동
========================================================= */

const FACILITY_NAVIGATOR_WINDOW_NAME =
  "GS_FACILITY_NAVIGATOR";


function openFacilityNavigator(
  rawTag
) {
  const tag =
    String(
      rawTag ||
      ""
    )
      .trim()
      .toUpperCase();


  if (!tag) {
    showToast(
      "먼저 TAG를 입력해 주세요."
    );

    return;
  }


  const targetUrl =
    `${FACILITY_NAVIGATOR_URL}?tag=${encodeURIComponent(tag)}`;


  const navigatorWindow =
    window.open(
      targetUrl,
      FACILITY_NAVIGATOR_WINDOW_NAME
    );


  if (!navigatorWindow) {
    showToast(
      "팝업이 차단되었습니다. 브라우저에서 팝업을 허용해 주세요."
    );

    return;
  }


  try {
    navigatorWindow.focus();

  } catch (error) {
    console.warn(
      "네비게이터 탭 포커스 처리:",
      error
    );
  }
}

/* =====================================================
  현재 작성창과 연결된 업무일지 찾기

  대상:
  - 파트장
  - TGO
  - BCO1
  - BCO2
  - TO
  - BO1
  - BO2

  우선순위:
  1. 작성창 editingId
  2. 날짜 + 근무 + 보직
====================================================== */

function getCurrentEditorStoredLog() {
  const editingId =
    String(
      elements?.logEditorForm
        ?.dataset
        ?.editingId ||
      ""
    ).trim();


  /*
    현재 작성창에 저장된 업무일지 ID가 있으면
    해당 업무일지를 가장 먼저 사용한다.
  */
  if (
    editingId &&
    Array.isArray(
      appState?.logs
    )
  ) {
    const editingLog =
      appState.logs.find(
        log => {
          return (
            String(
              log?.id ||
              ""
            ).trim() ===
            editingId
          );
        }
      );


    if (
      editingLog
    ) {
      return editingLog;
    }
  }


  const currentDate =
    String(
      elements?.logDate?.value ||
      ""
    ).trim();


  const currentShift =
    String(
      elements?.logShift?.value ||
      ""
    )
      .trim()
      .toUpperCase();


  const currentRole =
    normalizeMemberLogRole(
      elements?.logRole?.value ||
      ""
    );


  if (
    !currentDate ||
    !currentShift ||
    !currentRole ||
    !Array.isArray(
      appState?.logs
    )
  ) {
    return null;
  }


  const matchedLogs =
    appState.logs
      .filter(
        log => {
          const source =
            String(
              log?.source ||
              ""
            ).trim();


          /*
            읽기 전용 과거 업무일지는
            현재 신규 작성 상태 판단에 사용하지 않는다.
          */
          const isLegacyLog =
            typeof isReadOnlyLegacyShiftLog ===
              "function"
              ? isReadOnlyLegacyShiftLog(
                  log
                )
              : source.startsWith(
                  "legacy"
                );


          if (
            isLegacyLog
          ) {
            return false;
          }


          return (
            String(
              log?.date ||
              ""
            ).trim() ===
              currentDate &&

            String(
              log?.shift ||
              ""
            )
              .trim()
              .toUpperCase() ===
              currentShift &&

            normalizeMemberLogRole(
              log?.role
            ) ===
              currentRole
          );
        }
      )
      .sort(
        (
          firstLog,
          secondLog
        ) => {
          const firstTime =
            new Date(
              firstLog?.updatedAt ||
              firstLog?.createdAt ||
              0
            ).getTime();


          const secondTime =
            new Date(
              secondLog?.updatedAt ||
              secondLog?.createdAt ||
              0
            ).getTime();


          return (
            secondTime -
            firstTime
          );
        }
      );


  return (
    matchedLogs[0] ||
    null
  );
}

/* =========================================================
  업무일지 기준일 직접 선택 달력 최종본

  방식:
  - HTML의 실제 input type="date" 사용
  - showPicker() 강제 호출 사용 안 함
  - PC·모바일 기본 달력 사용
  - 현재 D/S·N/S는 그대로 유지
  - 날짜 변경 후 D1·과거 업무일지 다시 조회
========================================================= */

(function initializeSelectedDatePickerFeature() {

  /* =====================================================
    YYYY-MM-DD → 로컬 Date 변환

    UTC 변환으로 날짜가 하루 달라지는 것을 막기 위해
    연·월·일을 직접 분리한다.
  ====================================================== */

  function parseSelectedDatePickerValue(
    value
  ) {
    const normalizedValue =
      String(
        value ||
        ""
      ).trim();


    const matchedDate =
      normalizedValue.match(
        /^(\d{4})-(\d{2})-(\d{2})$/
      );


    if (
      !matchedDate
    ) {
      return null;
    }


    const year =
      Number(
        matchedDate[1]
      );


    const month =
      Number(
        matchedDate[2]
      );


    const day =
      Number(
        matchedDate[3]
      );


    const parsedDate =
      new Date(
        year,
        month - 1,
        day
      );


    /*
      실제로 존재하지 않는 날짜 방지
    */
    if (
      parsedDate.getFullYear() !==
        year ||
      parsedDate.getMonth() !==
        month - 1 ||
      parsedDate.getDate() !==
        day
    ) {
      return null;
    }


    return parsedDate;
  }


  /* =====================================================
    현재 화면 날짜를 날짜 input에 반영
  ====================================================== */

  function syncSelectedDatePickerValue() {
    const datePicker =
      document.getElementById(
        "selectedDatePicker"
      );


    if (
      !datePicker ||
      !appState?.selectedDate ||
      Number.isNaN(
        appState.selectedDate.getTime()
      )
    ) {
      return;
    }


    datePicker.value =
      formatInputDate(
        appState.selectedDate
      );
  }


  /* =====================================================
    달력에서 선택한 날짜 적용
  ====================================================== */

  async function handleSelectedDatePickerChange(
    event
  ) {
    const datePicker =
      event.currentTarget;


    const selectedDate =
      parseSelectedDatePickerValue(
        datePicker.value
      );


    if (
      !selectedDate
    ) {
      showToast(
        "선택한 날짜를 확인할 수 없습니다."
      );


      syncSelectedDatePickerValue();


      return;
    }


    const currentDateValue =
      formatInputDate(
        appState.selectedDate
      );


    const selectedDateValue =
      formatInputDate(
        selectedDate
      );


    /*
      같은 날짜를 다시 선택한 경우
    */
    if (
      currentDateValue ===
      selectedDateValue
    ) {
      syncSelectedDatePickerValue();

      return;
    }


    const dateButton =
      document.getElementById(
        "selectedDateButton"
      );


    datePicker.disabled =
      true;


    dateButton?.classList.add(
      "is-calendar-loading"
    );


    dateButton?.setAttribute(
      "aria-busy",
      "true"
    );


    /*
      선택한 날짜만 변경한다.

      기존에 선택된 D/S 또는 N/S는
      그대로 유지한다.
    */
    appState.selectedDate =
      selectedDate;


    renderSelectedDate();


    let hasLoadError =
      false;


    /* ===================================================
      공용 D1 업무일지 최신화
    ==================================================== */

    if (
      typeof refreshSharedShiftLogsInState ===
        "function"
    ) {
      try {
        await refreshSharedShiftLogsInState();

      } catch (
        error
      ) {
        hasLoadError =
          true;


        console.error(
          "날짜 직접 선택 후 공용 업무일지 갱신 실패:",
          error
        );
      }
    }


    /* ===================================================
      선택 날짜의 과거 업무일지 다시 불러오기
    ==================================================== */

    if (
      typeof loadLegacyLogsForSelectedDate ===
        "function"
    ) {
      try {
        await loadLegacyLogsForSelectedDate();

      } catch (
        error
      ) {
        hasLoadError =
          true;


        console.error(
          "날짜 직접 선택 후 과거 업무일지 조회 실패:",
          error
        );
      }
    }


    /* ===================================================
      화면 갱신
    ==================================================== */

    if (
      typeof renderLogTable ===
        "function"
    ) {
      renderLogTable();
    }


    if (
      typeof updateShiftMemberCardStates ===
        "function"
    ) {
      updateShiftMemberCardStates();
    }


    syncSelectedDatePickerValue();


    if (
      hasLoadError
    ) {
      showToast(
        "날짜는 변경했지만 일부 업무일지를 불러오지 못했습니다."
      );
    }


    datePicker.disabled =
      false;


    dateButton?.classList.remove(
      "is-calendar-loading"
    );


    dateButton?.removeAttribute(
      "aria-busy"
    );
  }


  /* =====================================================
    날짜 이동 버튼 사용 후에도
    날짜 input 값을 현재 화면과 동기화
  ====================================================== */

  const renderSelectedDateBeforeDatePicker =
    renderSelectedDate;


  renderSelectedDate =
    function renderSelectedDateWithDatePicker(
      ...args
    ) {
      const result =
        renderSelectedDateBeforeDatePicker
          .apply(
            this,
            args
          );


      syncSelectedDatePickerValue();


      return result;
    };


  /* =====================================================
    이벤트 연결
  ====================================================== */

  function bindSelectedDatePickerEvents() {
    const datePicker =
      document.getElementById(
        "selectedDatePicker"
      );


    if (
      !datePicker
    ) {
      console.error(
        "업무일지 기준일 날짜 input을 찾을 수 없습니다."
      );


      return;
    }


    if (
      datePicker.dataset
        .datePickerBound ===
      "true"
    ) {
      return;
    }


    datePicker.addEventListener(
      "change",
      handleSelectedDatePickerChange
    );


    datePicker.dataset
      .datePickerBound =
      "true";


    syncSelectedDatePickerValue();
  }


  /* =====================================================
    초기 실행
  ====================================================== */

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      bindSelectedDatePickerEvents,
      {
        once:
          true
      }
    );

  } else {
    bindSelectedDatePickerEvents();
  }

})();

/* =========================================================
  보조보일러 공사 중 → 정지 상태 자동 표시

  적용 대상:
  - 3호기 보조보일러
  - 4호기 보조보일러
  - Auxiliary Boiler 표기 자료

  적용 문구:
  - 공사 중
  - 개조 공사 중
  - 보수 공사 중
  - 공사 진행 중

  기존 자료가 정상운전 상태로 저장돼 있어도
  내용이 공사 중이면 화면에서는 정지로 보정한다.
========================================================= */

(function applyAuxiliaryBoilerConstructionStatusRule() {
  /*
    기존 함수를 먼저 보관한다.
  */
  const normalizeOperationStatusItemBeforeConstructionRule =
    normalizeOperationStatusItem;


  /* =====================================================
    비교용 문자열 정리
  ====================================================== */

  function normalizeConstructionStatusText(
    value
  ) {
    return String(
      value ||
      ""
    )
      .normalize(
        "NFKC"
      )
      .trim()
      .toLowerCase()
      .replace(
        /\s+/g,
        ""
      )
      .replace(
        /[#_\-]/g,
        ""
      );
  }


  /* =====================================================
    보조보일러 여부 확인
  ====================================================== */

  function isAuxiliaryBoilerStatusItem(
    item
  ) {
    const equipmentName =
      normalizeConstructionStatusText(
        item?.name ||
        item?.equipmentName ||
        item?.title ||
        ""
      );


    return (
      equipmentName.includes(
        "보조보일러"
      ) ||
      equipmentName.includes(
        "auxboiler"
      ) ||
      equipmentName.includes(
        "auxiliaryboiler"
      )
    );
  }


  /* =====================================================
    공사 중 문구 확인
  ====================================================== */

  function isConstructionInProgressStatus(
    item
  ) {
    const statusText =
      normalizeConstructionStatusText(
        [
          item?.name,
          item?.content,
          item?.description
        ]
          .filter(
            Boolean
          )
          .join(
            " "
          )
      );


    return (
      statusText.includes(
        "공사중"
      ) ||
      statusText.includes(
        "공사진행중"
      ) ||
      statusText.includes(
        "개조공사중"
      ) ||
      statusText.includes(
        "보수공사중"
      )
    );
  }


  /* =====================================================
    기존 운전현황 정규화 함수 최종 보정
  ====================================================== */

  normalizeOperationStatusItem =
    function normalizeOperationStatusItem(
      item,
      fallbackIndex = 0
    ) {
      const normalizedItem =
        normalizeOperationStatusItemBeforeConstructionRule(
          item,
          fallbackIndex
        );


      /*
        보조보일러이면서 공사 중인 경우
        저장된 기존 상태가 normal이어도 stopped로 바꾼다.
      */
      if (
        isAuxiliaryBoilerStatusItem(
          normalizedItem
        ) &&
        isConstructionInProgressStatus(
          normalizedItem
        )
      ) {
        return {
          ...normalizedItem,

          type:
            "stopped"
        };
      }


      return normalizedItem;
    };
})();

/* =========================================================
  일반 보직 임시저장 후 결재요청 최종본

  일반 보직 신규 작성:
  - 임시저장만 표시
  - 결재요청 숨김

  임시저장 성공 후:
  - 임시저장 표시
  - 결재요청 표시

  결재요청 후:
  - 작성창 닫기
  - 상태를 결재요청으로 변경

  파트장:
  - 기존 버튼 흐름 유지

  적용 방법:
  - script.js 진짜 맨 마지막에 추가
  - 기존 함수 삭제·교체 없음
========================================================= */

(function initializeMemberDraftBeforeApprovalRequestFlow() {

  const MEMBER_LOG_ROLES =
    new Set([
      "TGO",
      "BCO1",
      "BCO2",
      "TO",
      "BO1",
      "BO2"
    ]);


  /*
    현재 적용 중인 기존 함수를 보관한다.

    파트장 버튼 흐름은 기존 함수에 맡기고,
    일반 보직 부분만 아래에서 다시 보정한다.
  */
  const updateLogEditorActionButtonsBeforeMemberFlow =
    typeof updateLogEditorActionButtons ===
      "function"
      ? updateLogEditorActionButtons
      : null;


  const saveCurrentLogBeforeMemberFlow =
    typeof saveCurrentLog ===
      "function"
      ? saveCurrentLog
      : null;


  /* =====================================================
    상태값 통일

    작성중   → 임시저장
    작성완료 → 결재요청
  ====================================================== */

  function normalizeMemberEditorLogStatus(
    status
  ) {
    if (
      typeof normalizeShiftLogApprovalStatus ===
        "function"
    ) {
      return normalizeShiftLogApprovalStatus(
        status
      );
    }


    const statusMap = {
      작성중:
        "임시저장",

      임시저장:
        "임시저장",

      작성완료:
        "결재요청",

      결재요청:
        "결재요청",

      결재완료:
        "결재완료",

      저장완료:
        "저장완료"
    };


    return (
      statusMap[
        String(
          status ||
          ""
        ).trim()
      ] ||
      ""
    );
  }


  /* =====================================================
    현재 작성 중인 보직
  ====================================================== */

  function getCurrentMemberEditorRole() {
    return normalizeMemberLogRole(
      elements?.logRole?.value ||
      ""
    );
  }


  /* =====================================================
    일반 보직 업무일지 여부
  ====================================================== */

  function isCurrentMemberEditorRole() {
    return MEMBER_LOG_ROLES.has(
      getCurrentMemberEditorRole()
    );
  }


  /* =====================================================
    현재 작성창과 연결된 저장 업무일지 찾기

    우선순위:
    1. editingId
    2. 날짜 + 근무 + 보직

    과거 조회 전용 업무일지는 제외한다.
  ====================================================== */

  function getCurrentMemberEditorStoredLog() {
    const editingId =
      String(
        elements?.logEditorForm
          ?.dataset
          ?.editingId ||
        ""
      ).trim();


    const sourceLogs =
      Array.isArray(
        appState?.logs
      )
        ? appState.logs
        : [];


    /*
      작성창에 실제 업무일지 ID가 연결된 경우
    */
    if (
      editingId
    ) {
      const editingLog =
        sourceLogs.find(
          log => {
            return (
              String(
                log?.id ||
                ""
              ).trim() ===
              editingId
            );
          }
        );


      if (
        editingLog
      ) {
        return editingLog;
      }
    }


    const currentDate =
      String(
        elements?.logDate?.value ||
        ""
      ).trim();


    const currentShift =
      String(
        elements?.logShift?.value ||
        ""
      )
        .trim()
        .toUpperCase()
        .replaceAll(
          "/",
          ""
        );


    const currentRole =
      getCurrentMemberEditorRole();


    if (
      !currentDate ||
      !currentShift ||
      !MEMBER_LOG_ROLES.has(
        currentRole
      )
    ) {
      return null;
    }


    const matchedLogs =
      sourceLogs
        .filter(
          log => {
            /*
              과거 업무일지는 신규 작성 버튼 상태를
              판단하는 자료로 사용하지 않는다.
            */
            const isReadOnlyLegacy =
              typeof isReadOnlyLegacyShiftLog ===
                "function"
                ? isReadOnlyLegacyShiftLog(
                    log
                  )
                : String(
                    log?.source ||
                    ""
                  ).startsWith(
                    "legacy"
                  );


            if (
              isReadOnlyLegacy
            ) {
              return false;
            }


            const logShift =
              String(
                log?.shift ||
                ""
              )
                .trim()
                .toUpperCase()
                .replaceAll(
                  "/",
                  ""
                );


            return (
              String(
                log?.date ||
                ""
              ).trim() ===
                currentDate &&

              logShift ===
                currentShift &&

              normalizeMemberLogRole(
                log?.role
              ) ===
                currentRole
            );
          }
        )
        .sort(
          (
            firstLog,
            secondLog
          ) => {
            const revisionDifference =
              Number(
                secondLog?.serverRevision ||
                0
              ) -
              Number(
                firstLog?.serverRevision ||
                0
              );


            if (
              revisionDifference !==
              0
            ) {
              return revisionDifference;
            }


            const firstTime =
              new Date(
                firstLog?.updatedAt ||
                firstLog?.createdAt ||
                0
              ).getTime();


            const secondTime =
              new Date(
                secondLog?.updatedAt ||
                secondLog?.createdAt ||
                0
              ).getTime();


            return (
              secondTime -
              firstTime
            );
          }
        );


    return (
      matchedLogs[0] ||
      null
    );
  }


  /* =====================================================
    버튼 표시·숨김

    hidden 속성과 기존 인라인 display를
    함께 정리한다.
  ====================================================== */

  function setMemberEditorButtonVisible(
    button,
    visible
  ) {
    if (
      !button
    ) {
      return;
    }


    button.hidden =
      !visible;


    button.disabled =
      !visible;


    if (
      visible
    ) {
      button.removeAttribute(
        "hidden"
      );


      button.style.removeProperty(
        "display"
      );

    } else {
      button.setAttribute(
        "hidden",
        ""
      );


      button.style.setProperty(
        "display",
        "none",
        "important"
      );
    }
  }

  /* =====================================================
  일반 보직 결재요청 상태 입력 잠금

  잠금 대상:
  - 작성일·근무·보직·작성자
  - 운전현황 수정
  - 업무내역 추가·수정·삭제
  - 첨부파일 변경
  - 이전일지 가져오기

  잠금 제외:
  - 결재요청 취소
  - 인쇄
  - 닫기
====================================================== */

function setMemberEditorRequestLock(
  locked
) {
  const form =
    elements?.logEditorForm ||
    document.getElementById(
      "logEditorForm"
    );


  if (
    !form
  ) {
    return;
  }


  const lockExemptIds =
    new Set([
      "requestApprovalButton",
      "printLogButton",
      "cancelLogButton"
    ]);


  const controls = [
    ...form.querySelectorAll(
      "input, select, textarea, button"
    )
  ];


  controls.forEach(
    control => {
      const isLockExempt =
        lockExemptIds.has(
          control.id
        ) ||
        control.dataset
          .memberRequestLockExempt ===
          "true";


      if (
        isLockExempt
      ) {
        return;
      }


      if (
        locked
      ) {
        /*
          잠금 전의 disabled 상태를 기억한다.
        */
        if (
          control.dataset
            .memberRequestPreviousDisabled ===
            undefined
        ) {
          control.dataset
            .memberRequestPreviousDisabled =
            control.disabled
              ? "1"
              : "0";
        }


        control.disabled =
          true;


        control.setAttribute(
          "aria-disabled",
          "true"
        );


        return;
      }


      /*
        결재요청 취소 후 원래 disabled 상태로 복원한다.
      */
      if (
        control.dataset
          .memberRequestPreviousDisabled ===
          undefined
      ) {
        return;
      }


      control.disabled =
        control.dataset
          .memberRequestPreviousDisabled ===
        "1";


      if (
        control.disabled
      ) {
        control.setAttribute(
          "aria-disabled",
          "true"
        );

      } else {
        control.removeAttribute(
          "aria-disabled"
        );
      }


      delete control.dataset
        .memberRequestPreviousDisabled;
    }
  );


  form.classList.toggle(
    "is-approval-requested",
    locked
  );
}

/* =====================================================
  작성창 하단 버튼 최종 표시

  일반 보직 신규:
  - 임시저장

  일반 보직 임시저장:
  - 임시저장
  - 결재요청

  일반 보직 결재요청:
  - 결재요청 취소
  - 입력 영역 잠금

  일반 보직 결재완료:
  - 입력 영역 잠금
  - 취소 버튼 없음

  파트장:
  - 기존 파트장 결재 흐름 유지
====================================================== */

updateLogEditorActionButtons =
  function updateLogEditorActionButtons() {
    updateLogEditorActionButtonsBeforeMemberFlow
      ?.();


    if (
      !isCurrentMemberEditorRole()
    ) {
      setMemberEditorRequestLock(
        false
      );

      return;
    }


    setMemberEditorRequestLock(
      false
    );


    const submitButton =
      typeof getShiftLogEditorSubmitButton ===
        "function"
        ? getShiftLogEditorSubmitButton()
        : elements?.logEditorForm
            ?.querySelector(
              'button[type="submit"]'
            );


    const saveDraftButton =
      elements?.saveDraftButton ||
      document.getElementById(
        "saveDraftButton"
      );


    const requestApprovalButton =
      elements?.requestApprovalButton ||
      document.getElementById(
        "requestApprovalButton"
      );


    const currentLog =
      getCurrentMemberEditorStoredLog();


    const currentStatus =
      normalizeMemberEditorLogStatus(
        currentLog?.status
      );


    const isDraft =
      Boolean(
        currentLog
      ) &&
      [
        "임시저장",
        "저장완료"
      ].includes(
        currentStatus
      );


    const isRequested =
      Boolean(
        currentLog
      ) &&
      currentStatus ===
        "결재요청";


    const isApproved =
      Boolean(
        currentLog
      ) &&
      currentStatus ===
        "결재완료";


    /*
      기존 일반 저장 버튼 숨김
    */
    setMemberEditorButtonVisible(
      submitButton,
      false
    );


    /*
      임시저장 버튼

      신규·임시저장:
      활성

      결재요청:
      표시하되 비활성

      결재완료:
      숨김
    */
    setMemberEditorButtonVisible(
      saveDraftButton,
      !isApproved
    );


    if (
      saveDraftButton
    ) {
      const canSaveDraft =
        !isRequested &&
        !isApproved;


      saveDraftButton.type =
        "button";


      saveDraftButton.disabled =
        !canSaveDraft;


      saveDraftButton.textContent =
        "임시저장";


      saveDraftButton.title =
        canSaveDraft
          ? "현재 작성 내용을 임시저장합니다."
          : "결재취소 후 다시 저장할 수 있습니다.";


      saveDraftButton.setAttribute(
        "aria-disabled",
        String(
          !canSaveDraft
        )
      );
    }


    /*
      결재요청 → 결재취소 전환

      신규:
      결재요청 비활성

      임시저장:
      결재요청 활성

      결재요청:
      결재취소 활성
    */
    setMemberEditorButtonVisible(
      requestApprovalButton,
      !isApproved
    );


    if (
      requestApprovalButton
    ) {
      const canUseApprovalButton =
        isDraft ||
        isRequested;


      requestApprovalButton.type =
        "button";


      requestApprovalButton.disabled =
        !canUseApprovalButton;


      requestApprovalButton.classList.toggle(
        "is-cancel-request",
        isRequested
      );


      requestApprovalButton.dataset
        .memberApprovalAction =
        isRequested
          ? "cancel"
          : "request";


      requestApprovalButton.textContent =
        isRequested
          ? "결재취소"
          : "결재요청";


      requestApprovalButton.title =
        isRequested
          ? "결재요청을 취소하고 임시저장 상태로 되돌립니다."
          : (
              isDraft
                ? "임시저장된 업무일지를 결재요청합니다."
                : "먼저 임시저장해 주세요."
            );


      requestApprovalButton.setAttribute(
        "aria-label",
        isRequested
          ? "업무일지 결재취소"
          : "업무일지 결재요청"
      );


      requestApprovalButton.setAttribute(
        "aria-disabled",
        String(
          !canUseApprovalButton
        )
      );
    }


    /*
      결재요청·결재완료 상태 입력 잠금
    */
    setMemberEditorRequestLock(
      isRequested ||
      isApproved
    );
  };


  /* =====================================================
    모든 저장 성공 후 버튼 상태 재계산

    임시저장 성공:
    → editingId와 appState에 저장본이 생김
    → 결재요청 버튼 표시
  ====================================================== */

  if (
    saveCurrentLogBeforeMemberFlow
  ) {
    saveCurrentLog =
      async function saveCurrentLog(
        requestedStatus,
        options = {}
      ) {
        const savedLog =
          await saveCurrentLogBeforeMemberFlow(
            requestedStatus,
            options
          );


        if (
          savedLog
        ) {
          if (
            elements?.logEditorForm
          ) {
            elements.logEditorForm
              .dataset
              .editingId =
              String(
                savedLog.id ||
                ""
              );
          }


          updateLogEditorActionButtons();
        }


        return savedLog;
      };
  }


  /* =====================================================
    기존 클릭 이벤트 제거용 버튼 교체

    bindEvents()에서 이미 연결한
    즉시 결재요청 이벤트를 제거한다.
  ====================================================== */

  function replaceMemberEditorButtonWithoutEvents(
    buttonId
  ) {
    const oldButton =
      document.getElementById(
        buttonId
      );


    if (
      !oldButton
    ) {
      return null;
    }


    const newButton =
      oldButton.cloneNode(
        true
      );


    oldButton.replaceWith(
      newButton
    );


    return newButton;
  }


  /* =====================================================
    임시저장 클릭
  ====================================================== */

  async function handleMemberDraftButtonClick(
    event
  ) {
    event.preventDefault();

    event.stopPropagation();


    if (
      !isCurrentMemberEditorRole()
    ) {
      return;
    }


    const savedLog =
      await saveDraft();


    if (
      !savedLog
    ) {
      return;
    }


    updateLogEditorActionButtons();
  }

/* =====================================================
  일반 보직 결재요청·결재요청 취소

  임시저장 상태:
  → 결재요청

  결재요청 상태:
  → 결재요청 취소
  → 임시저장으로 복귀
====================================================== */

async function handleMemberApprovalRequestClick(
  event
) {
  event.preventDefault();
  event.stopPropagation();


  if (
    !isCurrentMemberEditorRole()
  ) {
    return;
  }


  const requestApprovalButton =
    elements?.requestApprovalButton ||
    document.getElementById(
      "requestApprovalButton"
    );


  const currentLog =
    getCurrentMemberEditorStoredLog();


  const currentStatus =
    normalizeMemberEditorLogStatus(
      currentLog?.status
    );


  /* =====================================================
    기존 결재요청 취소 호환
  ====================================================== */

  if (
    currentLog &&
    currentStatus ===
      "결재요청"
  ) {
    const canCancel =
      typeof canCurrentUserCancelShiftLogApproval ===
        "function"
        ? canCurrentUserCancelShiftLogApproval(
            currentLog
          )
        : true;


    if (
      !canCancel
    ) {
      showToast(
        "결재요청한 작성자 본인만 요청을 취소할 수 있습니다."
      );

      return;
    }


    const shouldCancel =
      await showCompactConfirm({
        title:
          "결재요청 취소",

        message:
          "결재요청을 취소하고 임시저장 상태로 되돌릴까요?",

        confirmText:
          "요청 취소",

        cancelText:
          "유지"
      });


    if (
      !shouldCancel
    ) {
      return;
    }


    if (
      requestApprovalButton
    ) {
      requestApprovalButton.disabled =
        true;

      requestApprovalButton.textContent =
        "취소 중...";
    }


    try {
      const cancelledLog =
        await changeShiftLogApprovalOnServer(
          currentLog,
          "cancel"
        );


      if (
        !cancelledLog
      ) {
        return;
      }


      if (
        elements?.logEditorForm
      ) {
        elements.logEditorForm
          .dataset
          .editingId =
          String(
            cancelledLog.id ||
            ""
          );

        elements.logEditorForm
          .dataset
          .editorMode =
          "existing-edit";
      }


      renderLogTable();

      updateShiftMemberCardStates();

      updateLogEditorActionButtons();


      if (
        typeof markLogEditorAsSaved ===
          "function"
      ) {
        markLogEditorAsSaved();
      }


      showToast(
        "결재요청을 취소했습니다. 다시 수정할 수 있습니다."
      );

    } catch (
      error
    ) {
      console.error(
        "결재요청 취소 실패:",
        error
      );


      if (
        error?.isConflict ===
          true &&
        typeof handleShiftLogConflict ===
          "function"
      ) {
        handleShiftLogConflict(
          error
        );

      } else {
        showToast(
          error?.message ||
          "결재요청을 취소하지 못했습니다."
        );
      }

    } finally {
      updateLogEditorActionButtons();
    }


    return;
  }


  /* =====================================================
    결재요청은 임시저장 상태에서만 가능
  ====================================================== */

  if (
    !currentLog ||
    currentStatus !==
      "임시저장"
  ) {
    showToast(
      "먼저 임시저장해 주세요."
    );

    updateLogEditorActionButtons();

    return;
  }


  const shouldRequest =
    await showCompactConfirm({
      title:
        "결재요청",

      message:
        "현재 업무일지를 결재요청 상태로 변경할까요?",

      confirmText:
        "결재요청",

      cancelText:
        "취소"
    });


  if (
    !shouldRequest
  ) {
    return;
  }


  const requestedLog =
    await saveCurrentLog(
      "작성완료",
      {
        closeAfterSave:
          false
      }
    );


  if (
    !requestedLog
  ) {
    return;
  }


  /*
    서버가 실제로 결재요청 상태를 반환했을 때만
    성공 처리한다.
  */
  const savedStatus =
    normalizeMemberEditorLogStatus(
      requestedLog.status
    );


  if (
    savedStatus !==
      "결재요청"
  ) {
    updateLogEditorActionButtons();

    showToast(
      "결재요청 상태로 전환되지 않았습니다. shift-logs API 적용 여부를 확인해 주세요."
    );

    return;
  }


  if (
    elements?.logEditorForm
  ) {
    elements.logEditorForm
      .dataset
      .editingId =
      String(
        requestedLog.id ||
        ""
      );

    elements.logEditorForm
      .dataset
      .editorMode =
      "approval-requested";
  }


  updateLogEditorActionButtons();


  if (
    typeof markLogEditorAsSaved ===
      "function"
  ) {
    markLogEditorAsSaved();
  }


  showToast(
    "결재요청했습니다."
  );
}


  /* =====================================================
    버튼 이벤트 최종 연결
  ====================================================== */

  function bindMemberDraftBeforeApprovalRequestFlow() {
    const saveDraftButton =
      replaceMemberEditorButtonWithoutEvents(
        "saveDraftButton"
      );


    const requestApprovalButton =
      replaceMemberEditorButtonWithoutEvents(
        "requestApprovalButton"
      );

      /*
  폼 submit이 함께 실행되지 않도록
  두 버튼을 일반 버튼으로 강제한다.
*/

if (
  saveDraftButton
) {
  saveDraftButton.type =
    "button";
}


if (
  requestApprovalButton
) {
  requestApprovalButton.type =
    "button";
}


    /*
      기존 elements 참조를 새 버튼으로 변경한다.
    */
    if (
      typeof elements ===
        "object" &&
      elements
    ) {
      elements.saveDraftButton =
        saveDraftButton;


      elements.requestApprovalButton =
        requestApprovalButton;
    }


    saveDraftButton
      ?.addEventListener(
        "click",
        handleMemberDraftButtonClick
      );


    requestApprovalButton
      ?.addEventListener(
        "click",
        handleMemberApprovalRequestClick
      );


    /*
      보직·날짜·근무가 변경되면
      현재 저장 상태를 다시 계산한다.
    */
    elements?.logRole
      ?.addEventListener(
        "change",
        updateLogEditorActionButtons
      );


    elements?.logDate
      ?.addEventListener(
        "change",
        updateLogEditorActionButtons
      );


    elements?.logShift
      ?.addEventListener(
        "change",
        updateLogEditorActionButtons
      );


    /*
      작성창이 열릴 때마다 버튼 상태를 다시 적용한다.
    */
    const logEditorModal =
      elements?.logEditorModal ||
      document.getElementById(
        "logEditorModal"
      );


    if (
      logEditorModal &&
      logEditorModal.dataset
        .memberDraftFlowObserved !==
        "true"
    ) {
      const observer =
        new MutationObserver(
          () => {
            const isOpen =
              logEditorModal
                .classList
                .contains(
                  "is-open"
                ) ||

              logEditorModal.getAttribute(
                "aria-hidden"
              ) ===
                "false";


            if (
              !isOpen
            ) {
              return;
            }


            window.requestAnimationFrame(
              updateLogEditorActionButtons
            );
          }
        );


      observer.observe(
        logEditorModal,
        {
          attributes:
            true,

          attributeFilter: [
            "class",
            "aria-hidden"
          ]
        }
      );


      logEditorModal.dataset
        .memberDraftFlowObserved =
        "true";
    }


    updateLogEditorActionButtons();
  }


/* =====================================================
  초기 실행 최종본

  기존 bindEvents()가 결재요청 버튼에
  예전 클릭 이벤트를 먼저 연결한 다음,
  한 박자 뒤 버튼을 복제하여
  기존 이벤트를 완전히 제거한다.

  최종적으로 남는 이벤트:
  - 임시저장 전용 이벤트
  - 결재요청 전용 이벤트
====================================================== */

function scheduleMemberDraftBeforeApprovalRequestFlow() {
  window.setTimeout(
    () => {
      const currentApprovalButton =
        document.getElementById(
          "requestApprovalButton"
        );


      /*
        이미 최종 이벤트가 연결된 경우
        다시 버튼을 교체하지 않는다.
      */
      if (
        currentApprovalButton
          ?.dataset
          ?.memberDraftFlowFinalBound ===
        "true"
      ) {
        return;
      }


      bindMemberDraftBeforeApprovalRequestFlow();


      const finalDraftButton =
        document.getElementById(
          "saveDraftButton"
        );


      const finalApprovalButton =
        document.getElementById(
          "requestApprovalButton"
        );


      /*
        버튼 기본 submit 동작 차단
      */
      if (
        finalDraftButton
      ) {
        finalDraftButton.type =
          "button";


        finalDraftButton.dataset
          .memberDraftFlowFinalBound =
          "true";
      }


      if (
        finalApprovalButton
      ) {
        finalApprovalButton.type =
          "button";


        finalApprovalButton.dataset
          .memberDraftFlowFinalBound =
          "true";
      }
    },
    0
  );
}


if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    scheduleMemberDraftBeforeApprovalRequestFlow,
    {
      once:
        true
    }
  );

} else {
  scheduleMemberDraftBeforeApprovalRequestFlow();
}

})();

/* =========================================================
  파트장 임시저장 → 결재완료 → 결재취소 단일 최종본

  왼쪽  : 인쇄 | 결재취소 | 삭제
  오른쪽: 임시저장 | 결재완료 | 닫기

  핵심:
  - 일반 보직 버튼 흐름은 그대로 유지한다.
  - 파트장 전용 버튼은 각 버튼에 직접 한 번만 연결한다.
  - 결재완료 상태에서는 입력 영역만 잠근다.
  - 결재취소·삭제·인쇄·닫기는 계속 사용할 수 있다.
========================================================= */

(function initializeLeaderEditorApprovalFlow() {
  if (
    window.__leaderEditorApprovalFlowInstalled ===
    true
  ) {
    return;
  }

  window.__leaderEditorApprovalFlowInstalled =
    true;

  let isLeaderActionWorking =
    false;

  let lastSavedLeaderLog =
    null;

  const updateLogEditorActionButtonsBeforeLeaderFlow =
    typeof updateLogEditorActionButtons ===
      "function"
      ? updateLogEditorActionButtons
      : null;


  /* =====================================================
    상태 정규화
  ====================================================== */

  function normalizeLeaderEditorStatus(
    status
  ) {
    const rawStatus =
      String(
        status ||
        ""
      )
        .trim()
        .replace(
          /\s+/g,
          ""
        );

    const statusMap = {
      작성중:
        "임시저장",

      임시:
        "임시저장",

      임시저장:
        "임시저장",

      저장:
        "임시저장",

      저장완료:
        "저장완료",

      작성완료:
        "결재요청",

      결재요청:
        "결재요청",

      승인요청:
        "결재요청",

      결재완료:
        "결재완료",

      승인완료:
        "결재완료",

      승인:
        "결재완료"
    };

    const normalizedBySharedFunction =
      typeof normalizeShiftLogApprovalStatus ===
        "function"
        ? normalizeShiftLogApprovalStatus(
            rawStatus
          )
        : rawStatus;

    return (
      statusMap[
        String(
          normalizedBySharedFunction ||
          rawStatus
        )
          .trim()
          .replace(
            /\s+/g,
            ""
          )
      ] ||
      normalizedBySharedFunction ||
      rawStatus ||
      "임시저장"
    );
  }


  function normalizeLeaderEditorShift(
    shift
  ) {
    return String(
      shift ||
      ""
    )
      .trim()
      .toUpperCase()
      .replace(
        /[\s/]/g,
        ""
      );
  }


  function isLeaderEditorLegacyLog(
    log
  ) {
    if (
      typeof isReadOnlyLegacyShiftLog ===
      "function"
    ) {
      return isReadOnlyLegacyShiftLog(
        log
      );
    }

    return String(
      log?.source ||
      ""
    )
      .trim()
      .toLowerCase()
      .startsWith(
        "legacy"
      );
  }


  /* =====================================================
    현재 수정 중인 파트장 업무일지
  ====================================================== */

  function getLeaderEditorCurrentLog() {
    const form =
      document.getElementById(
        "logEditorForm"
      );

    const editingId =
      String(
        form?.dataset
          ?.editingId ||
        ""
      ).trim();

    const logs = [
      ...(
        Array.isArray(
          appState?.logs
        )
          ? appState.logs
          : []
      ),

      ...(
        typeof currentSearchResultLogs !==
          "undefined" &&
        Array.isArray(
          currentSearchResultLogs
        )
          ? currentSearchResultLogs
          : []
      )
    ];

    if (
      editingId
    ) {
      const idMatches = [
        ...logs.filter(
          log => {
            return (
              String(
                log?.id ||
                ""
              ).trim() ===
                editingId &&

              normalizeMemberLogRole(
                log?.role
              ) ===
                "파트장"
            );
          }
        ),

        String(
          lastSavedLeaderLog?.id ||
          ""
        ).trim() ===
          editingId &&

        normalizeMemberLogRole(
          lastSavedLeaderLog?.role
        ) ===
          "파트장"
          ? lastSavedLeaderLog
          : null
      ].filter(
        Boolean
      );

      if (
        idMatches.length >
        0
      ) {
        return idMatches
          .sort(
            (
              firstLog,
              secondLog
            ) => {
              const revisionDifference =
                Number(
                  secondLog?.serverRevision ||
                  0
                ) -
                Number(
                  firstLog?.serverRevision ||
                  0
                );

              if (
                revisionDifference !==
                0
              ) {
                return revisionDifference;
              }

              return (
                new Date(
                  secondLog?.updatedAt ||
                  secondLog?.createdAt ||
                  0
                ).getTime() -

                new Date(
                  firstLog?.updatedAt ||
                  firstLog?.createdAt ||
                  0
                ).getTime()
              );
            }
          )[0];
      }
    }

    if (
      form?.dataset
        ?.editorMode ===
      "new"
    ) {
      return null;
    }

    const currentDate =
      String(
        document.getElementById(
          "logDate"
        )?.value ||
        ""
      ).trim();

    const currentShift =
      normalizeLeaderEditorShift(
        document.getElementById(
          "logShift"
        )?.value
      );

    if (
      !currentDate ||
      !currentShift
    ) {
      return null;
    }

    return (
      logs
        .filter(
          log => {
            return (
              !isLeaderEditorLegacyLog(
                log
              ) &&

              String(
                log?.date ||
                ""
              ).trim() ===
                currentDate &&

              normalizeLeaderEditorShift(
                log?.shift
              ) ===
                currentShift &&

              normalizeMemberLogRole(
                log?.role
              ) ===
                "파트장"
            );
          }
        )
        .sort(
          (
            firstLog,
            secondLog
          ) => {
            const revisionDifference =
              Number(
                secondLog?.serverRevision ||
                0
              ) -
              Number(
                firstLog?.serverRevision ||
                0
              );

            if (
              revisionDifference !==
              0
            ) {
              return revisionDifference;
            }

            return (
              new Date(
                secondLog?.updatedAt ||
                secondLog?.createdAt ||
                0
              ).getTime() -

              new Date(
                firstLog?.updatedAt ||
                firstLog?.createdAt ||
                0
              ).getTime()
            );
          }
        )[0] ||
      null
    );
  }


  function isLeaderLogEditor() {
    const rawRole =
      String(
        document.getElementById(
          "logRole"
        )?.value ||
        ""
      ).trim();

    if (
      rawRole
    ) {
      return (
        normalizeMemberLogRole(
          rawRole
        ) ===
        "파트장"
      );
    }

    return (
      normalizeMemberLogRole(
        getLeaderEditorCurrentLog()
          ?.role
      ) ===
      "파트장"
    );
  }


  /* =====================================================
    결재완료 상태 입력 잠금
  ====================================================== */

  function setLeaderEditorInputLock(
    locked
  ) {
    const form =
      document.getElementById(
        "logEditorForm"
      );

    if (
      !form
    ) {
      return;
    }

    const isCurrentlyLocked =
      form.dataset
        .leaderApprovedLocked ===
      "true";

    if (
      !locked &&
      !isCurrentlyLocked
    ) {
      return;
    }

    const controls = [
      ...form.querySelectorAll(
        "input, select, textarea, button"
      )
    ];

    if (
      locked
    ) {
      controls.forEach(
        control => {
          if (
            control.dataset
              .leaderPreviousDisabled ===
            undefined
          ) {
            control.dataset
              .leaderPreviousDisabled =
              control.disabled
                ? "1"
                : "0";
          }

          control.disabled =
            true;

          control.setAttribute(
            "aria-disabled",
            "true"
          );
        }
      );

      form.dataset
        .leaderApprovedLocked =
        "true";

      form.classList.add(
        "is-leader-approved"
      );

      return;
    }

    controls.forEach(
      control => {
        const previousDisabled =
          control.dataset
            .leaderPreviousDisabled;

        if (
          previousDisabled ===
          undefined
        ) {
          return;
        }

        control.disabled =
          previousDisabled ===
          "1";

        if (
          control.disabled
        ) {
          control.setAttribute(
            "aria-disabled",
            "true"
          );

        } else {
          control.removeAttribute(
            "aria-disabled"
          );
        }

        delete control.dataset
          .leaderPreviousDisabled;
      }
    );

    delete form.dataset
      .leaderApprovedLocked;

    form.classList.remove(
      "is-leader-approved"
    );
  }


  /* =====================================================
    버튼 표시 및 사용 가능 상태
  ====================================================== */

  function setLeaderFooterButtonState(
    button,
    {
      visible,
      enabled,
      title = ""
    }
  ) {
    if (
      !button
    ) {
      return;
    }

    button.type =
      "button";

    button.hidden =
      !visible;

    button.disabled =
      !enabled;

    button.title =
      title;

    button.setAttribute(
      "aria-disabled",
      String(
        !enabled
      )
    );

    button.style.setProperty(
      "opacity",
      enabled
        ? "1"
        : "0.46",
      "important"
    );

    button.style.setProperty(
      "cursor",
      enabled
        ? "pointer"
        : "not-allowed",
      "important"
    );

    if (
      visible
    ) {
      button.removeAttribute(
        "hidden"
      );

      button.style.setProperty(
        "display",
        "inline-flex",
        "important"
      );

    } else {
      button.setAttribute(
        "hidden",
        ""
      );

      button.style.setProperty(
        "display",
        "none",
        "important"
      );
    }
  }


  function createLeaderFooterButton({
    id,
    className,
    text
  }) {
    let button =
      document.getElementById(
        id
      );

    if (
      !button
    ) {
      button =
        document.createElement(
          "button"
        );

      button.id =
        id;

      button.type =
        "button";

      button.className =
        className;

      button.textContent =
        text;
    }

    return button;
  }


  function bindLeaderFooterButton(
    button,
    action
  ) {
    if (
      !button ||
      button.dataset
        .leaderDirectEventBound ===
        "true"
    ) {
      return;
    }

    button.dataset
      .leaderDirectEventBound =
      "true";

    button.addEventListener(
      "click",
      event => {
        event.preventDefault();

        void runLeaderFooterAction(
          action,
          button
        );
      }
    );
  }


  /* =====================================================
    파트장 버튼 생성 및 위치 정리
  ====================================================== */

function ensureLeaderFooterButtons() {
  const modal =
    document.getElementById(
      "logEditorModal"
    );

  const leftGroup =
    modal?.querySelector(
      ".log-editor-footer__left"
    );

  const rightGroup =
    modal?.querySelector(
      ".log-editor-footer__right"
    );


  if (
    !leftGroup ||
    !rightGroup
  ) {
    return null;
  }


  const printButton =
    document.getElementById(
      "printLogButton"
    );

  const closeButton =
    document.getElementById(
      "cancelLogButton"
    );


  const cancelButton =
    createLeaderFooterButton({
      id:
        "leaderApprovalCancelButton",

      className:
        "secondary-button log-editor-cancel-approval-button",

      text:
        "결재취소"
    });


  const deleteButton =
    createLeaderFooterButton({
      id:
        "leaderLogDeleteButton",

      className:
        "danger-button log-editor-delete-button",

      text:
        "삭제"
    });


  const draftButton =
    createLeaderFooterButton({
      id:
        "leaderDraftSaveButton",

      className:
        "secondary-button log-editor-draft-button",

      text:
        "임시저장"
    });


  const completeButton =
    createLeaderFooterButton({
      id:
        "leaderApprovalCompleteButton",

      className:
        "approval-button log-editor-complete-button",

      text:
        "결재완료"
    });


  if (
    printButton
  ) {
    printButton.type =
      "button";

    printButton.classList.add(
      "secondary-button",
      "log-editor-print-button"
    );
  }


  if (
    closeButton
  ) {
    closeButton.type =
      "button";

    closeButton.classList.add(
      "secondary-button",
      "log-editor-close-button"
    );
  }


  /*
    prepend를 사용해 인쇄를 무조건 제일 왼쪽으로 고정한다.
  */
  leftGroup.prepend(
    ...[
      printButton,
      deleteButton,
      cancelButton
    ].filter(
      Boolean
    )
  );


  rightGroup.append(
    ...[
      draftButton,
      completeButton,
      closeButton
    ].filter(
      Boolean
    )
  );


  bindLeaderFooterButton(
    cancelButton,
    "cancel"
  );

  bindLeaderFooterButton(
    deleteButton,
    "delete"
  );

  bindLeaderFooterButton(
    draftButton,
    "draft"
  );

  bindLeaderFooterButton(
    completeButton,
    "complete"
  );


  return {
    cancelButton,
    deleteButton,
    draftButton,
    completeButton
  };
}


  function hideOriginalLeaderActionButtons() {
    [
      document.getElementById(
        "saveDraftButton"
      ),

      document.getElementById(
        "requestApprovalButton"
      ),

      document.getElementById(
        "cancelLeaderApprovalButton"
      )
    ]
      .filter(
        Boolean
      )
      .forEach(
        button => {
          button.hidden =
            true;

          button.disabled =
            true;

          button.setAttribute(
            "hidden",
            ""
          );

          button.style.setProperty(
            "display",
            "none",
            "important"
          );
        }
      );
  }


  function canDeleteLeaderEditorLog(
    currentLog
  ) {
    if (
      !currentLog ||
      isLeaderEditorLegacyLog(
        currentLog
      )
    ) {
      return false;
    }

    if (
      typeof canCurrentUserDeleteShiftLog ===
        "function" &&
      canCurrentUserDeleteShiftLog(
        currentLog
      )
    ) {
      return true;
    }

    if (
      typeof isCurrentUserSuperAdmin ===
        "function" &&
      isCurrentUserSuperAdmin()
    ) {
      return true;
    }

    const isLeaderAccount =
      typeof isCurrentShiftLogLeader ===
        "function"
        ? isCurrentShiftLogLeader()
        : true;

    const isOwnLog =
      typeof isCurrentUserShiftLogAuthor ===
        "function"
        ? isCurrentUserShiftLogAuthor(
            currentLog
          )
        : true;

    return (
      isLeaderAccount &&
      isOwnLog &&

      normalizeMemberLogRole(
        currentLog.role
      ) ===
        "파트장"
    );
  }


  /* =====================================================
    파트장 버튼 및 입력 잠금 갱신
  ====================================================== */

  function refreshLeaderEditorApprovalFlow() {
    const buttons =
      ensureLeaderFooterButtons();

    if (
      !buttons
    ) {
      return;
    }

    if (
      !isLeaderLogEditor()
    ) {
      setLeaderEditorInputLock(
        false
      );

      Object.values(
        buttons
      ).forEach(
        button => {
          setLeaderFooterButtonState(
            button,
            {
              visible:
                false,

              enabled:
                false
            }
          );
        }
      );

      return;
    }

    hideOriginalLeaderActionButtons();

    const currentLog =
      getLeaderEditorCurrentLog();

    const currentStatus =
      normalizeLeaderEditorStatus(
        currentLog?.status
      );

    const hasCurrentLog =
      Boolean(
        currentLog
      );

    const isApproved =
      hasCurrentLog &&
      currentStatus ===
        "결재완료";

    const canComplete =
      hasCurrentLog &&
      [
        "임시저장",
        "저장완료"
      ].includes(
        currentStatus
      );

    const canDelete =
      canDeleteLeaderEditorLog(
        currentLog
      );

    setLeaderEditorInputLock(
      isApproved
    );

    setLeaderFooterButtonState(
      buttons.cancelButton,
      {
        visible:
          true,

        enabled:
          isApproved &&
          !isLeaderActionWorking,

        title:
          isApproved
            ? "결재를 취소하고 임시저장 상태로 되돌립니다."
            : "결재완료 상태에서 사용할 수 있습니다."
      }
    );

    setLeaderFooterButtonState(
      buttons.deleteButton,
      {
        visible:
          true,

        enabled:
          canDelete &&
          !isLeaderActionWorking,

        title:
          canDelete
            ? "현재 파트장 업무일지를 삭제합니다."
            : "저장된 본인 업무일지만 삭제할 수 있습니다."
      }
    );

    setLeaderFooterButtonState(
      buttons.draftButton,
      {
        visible:
          true,

        enabled:
          !isApproved &&
          !isLeaderActionWorking,

        title:
          isApproved
            ? "결재취소 후 임시저장할 수 있습니다."
            : "파트장 업무일지를 임시저장합니다."
      }
    );

    setLeaderFooterButtonState(
      buttons.completeButton,
      {
        visible:
          true,

        enabled:
          canComplete &&
          !isLeaderActionWorking,

        title:
          canComplete
            ? "파트장 업무일지를 결재완료 처리합니다."
            : "먼저 임시저장해 주세요."
      }
    );
  }


  /* =====================================================
    일반 보직 버튼 처리 후 파트장 상태 적용
  ====================================================== */

  updateLogEditorActionButtons =
    function updateLogEditorActionButtons(
      ...args
    ) {
      const previousResult =
        updateLogEditorActionButtonsBeforeLeaderFlow
          ?.apply(
            this,
            args
          );

      refreshLeaderEditorApprovalFlow();

      return previousResult;
    };


  /* =====================================================
    서버 결과 반영
  ====================================================== */

  function applyLeaderEditorSavedLog(
    savedLog
  ) {
    if (
      !savedLog
    ) {
      return null;
    }

    const appliedLog =
      typeof replaceSharedShiftLogInState ===
        "function"
        ? (
            replaceSharedShiftLogInState(
              savedLog
            ) ||
            savedLog
          )
        : savedLog;

    lastSavedLeaderLog =
      appliedLog;

    const form =
      document.getElementById(
        "logEditorForm"
      );

    if (
      form
    ) {
      form.dataset.editingId =
        String(
          appliedLog.id ||
          ""
        );

      form.dataset.editorMode =
        "existing-edit";
    }

    if (
      typeof renderLogTable ===
      "function"
    ) {
      renderLogTable();
    }

    if (
      typeof updateShiftMemberCardStates ===
      "function"
    ) {
      updateShiftMemberCardStates();
    }

    if (
      typeof markLogEditorAsSaved ===
      "function"
    ) {
      markLogEditorAsSaved();
    }

    updateLogEditorActionButtons();

    return appliedLog;
  }


  async function confirmLeaderEditorAction(
    options
  ) {
    if (
      typeof showCompactConfirm ===
      "function"
    ) {
      return Boolean(
        await showCompactConfirm(
          options
        )
      );
    }

    return window.confirm(
      String(
        options?.message ||
        ""
      )
    );
  }


  function handleLeaderEditorError(
    error,
    fallbackMessage
  ) {
    console.error(
      fallbackMessage,
      error
    );

    if (
      error?.isConflict ===
        true &&
      typeof handleShiftLogConflict ===
        "function"
    ) {
      handleShiftLogConflict(
        error
      );

      return;
    }

    showToast(
      error?.message ||
      fallbackMessage
    );
  }


  /* =====================================================
    임시저장
  ====================================================== */

  async function saveLeaderEditorDraft() {
    const savedLog =
      await saveCurrentLog(
        "작성중",
        {
          closeAfterSave:
            false
        }
      );

    if (
      savedLog
    ) {
      applyLeaderEditorSavedLog(
        savedLog
      );
    }
  }


  /* =====================================================
    결재완료
  ====================================================== */

  async function completeLeaderEditorApproval() {
    const currentLog =
      getLeaderEditorCurrentLog();

    const currentStatus =
      normalizeLeaderEditorStatus(
        currentLog?.status
      );

    if (
      !currentLog ||
      ![
        "임시저장",
        "저장완료"
      ].includes(
        currentStatus
      )
    ) {
      showToast(
        "먼저 파트장 업무일지를 임시저장해 주세요."
      );

      return;
    }

    const shouldComplete =
      await confirmLeaderEditorAction({
        title:
          "결재완료",

        message:
          "파트장 업무일지를 결재완료 처리할까요?",

        confirmText:
          "결재완료",

        cancelText:
          "취소"
      });

    if (
      !shouldComplete
    ) {
      return;
    }

    const latestDraft =
      await saveCurrentLog(
        "작성중",
        {
          closeAfterSave:
            false
        }
      );

    if (
      !latestDraft
    ) {
      return;
    }

    applyLeaderEditorSavedLog(
      latestDraft
    );

    const approvedLog =
      await changeShiftLogApprovalOnServer(
        latestDraft,
        "approve"
      );

    if (
      !approvedLog
    ) {
      throw new Error(
        "결재완료된 업무일지를 확인할 수 없습니다."
      );
    }

    applyLeaderEditorSavedLog(
      approvedLog
    );

    showToast(
      "파트장 업무일지 결재가 완료되었습니다."
    );
  }


  /* =====================================================
    결재취소
  ====================================================== */

  async function cancelLeaderEditorApproval() {
    const currentLog =
      getLeaderEditorCurrentLog();

    if (
      !currentLog ||
      normalizeLeaderEditorStatus(
        currentLog.status
      ) !==
        "결재완료"
    ) {
      showToast(
        "결재취소할 파트장 업무일지를 찾을 수 없습니다."
      );

      return;
    }

    const shouldCancel =
      await confirmLeaderEditorAction({
        title:
          "결재취소",

        message:
          "파트장 업무일지 결재를 취소하고 임시저장 상태로 되돌릴까요?",

        confirmText:
          "결재취소",

        cancelText:
          "유지"
      });

    if (
      !shouldCancel
    ) {
      return;
    }

    const cancelledLog =
      await changeShiftLogApprovalOnServer(
        currentLog,
        "cancel"
      );

    if (
      !cancelledLog
    ) {
      throw new Error(
        "결재취소된 업무일지를 확인할 수 없습니다."
      );
    }

    applyLeaderEditorSavedLog(
      cancelledLog
    );

    setLeaderEditorInputLock(
      false
    );

    showToast(
      "파트장 업무일지 결재를 취소했습니다. 다시 수정할 수 있습니다."
    );
  }


  /* =====================================================
    삭제
  ====================================================== */

  async function deleteLeaderEditorLog() {
    const currentLog =
      getLeaderEditorCurrentLog();

    if (
      !currentLog
    ) {
      showToast(
        "삭제할 파트장 업무일지를 찾을 수 없습니다."
      );

      return;
    }

    if (
      !canDeleteLeaderEditorLog(
        currentLog
      )
    ) {
      showToast(
        "현재 계정으로는 이 업무일지를 삭제할 수 없습니다."
      );

      return;
    }

    const isApproved =
      normalizeLeaderEditorStatus(
        currentLog.status
      ) ===
      "결재완료";

    const shouldDelete =
      await confirmLeaderEditorAction({
        title:
          "업무일지 삭제",

        message:
          isApproved
            ? "결재를 취소한 뒤 현재 파트장 업무일지를 삭제할까요? 삭제한 자료는 복구할 수 없습니다."
            : "현재 파트장 업무일지를 삭제할까요? 삭제한 자료는 복구할 수 없습니다.",

        confirmText:
          "삭제",

        cancelText:
          "취소"
      });

    if (
      !shouldDelete
    ) {
      return;
    }

    let deleteTarget =
      currentLog;

    /*
      결재완료 자료는 직접 삭제하지 않고
      먼저 결재취소 후 최신 revision으로 삭제한다.
    */
    if (
      isApproved
    ) {
      const cancelledLog =
        await changeShiftLogApprovalOnServer(
          currentLog,
          "cancel"
        );

      if (
        !cancelledLog
      ) {
        throw new Error(
          "삭제 전 결재취소 결과를 확인할 수 없습니다."
        );
      }

      deleteTarget =
        applyLeaderEditorSavedLog(
          cancelledLog
        ) ||
        cancelledLog;
    }

    const deletedId =
      await deleteShiftLogFromServer(
        deleteTarget
      );

    if (
      typeof removeSharedShiftLogFromState ===
      "function"
    ) {
      removeSharedShiftLogFromState(
        deletedId ||
        deleteTarget.id
      );

    } else if (
      Array.isArray(
        appState?.logs
      )
    ) {
      appState.logs =
        appState.logs.filter(
          log => {
            return (
              String(
                log?.id ||
                ""
              ) !==
              String(
                deleteTarget.id ||
                ""
              )
            );
          }
        );
    }

    lastSavedLeaderLog =
      null;

    if (
      typeof renderLogTable ===
      "function"
    ) {
      renderLogTable();
    }

    if (
      typeof updateShiftMemberCardStates ===
      "function"
    ) {
      updateShiftMemberCardStates();
    }

    setLeaderEditorInputLock(
      false
    );

    if (
      typeof closeLogEditor ===
      "function"
    ) {
      closeLogEditor();
    }

    showToast(
      "파트장 업무일지를 삭제했습니다."
    );
  }


  /* =====================================================
    버튼 작업 실행
  ====================================================== */

  async function runLeaderFooterAction(
    action,
    button
  ) {
    if (
      !isLeaderLogEditor() ||
      isLeaderActionWorking ||
      button?.disabled
    ) {
      return;
    }

    isLeaderActionWorking =
      true;

    try {
      updateLogEditorActionButtons();

      if (
        action ===
        "draft"
      ) {
        await saveLeaderEditorDraft();

      } else if (
        action ===
        "complete"
      ) {
        await completeLeaderEditorApproval();

      } else if (
        action ===
        "cancel"
      ) {
        await cancelLeaderEditorApproval();

      } else if (
        action ===
        "delete"
      ) {
        await deleteLeaderEditorLog();
      }

    } catch (
      error
    ) {
      handleLeaderEditorError(
        error,
        "파트장 업무일지 작업을 처리하지 못했습니다."
      );

    } finally {
      isLeaderActionWorking =
        false;

      updateLogEditorActionButtons();
    }
  }


  function scheduleLeaderEditorRefresh() {
    [
      0,
      60,
      160
    ].forEach(
      delay => {
        window.setTimeout(
          () => {
            updateLogEditorActionButtons();
          },
          delay
        );
      }
    );
  }


  /* =====================================================
    초기 연결
  ====================================================== */

  function initializeLeaderEditorApprovalBindings() {
    ensureLeaderFooterButtons();

    [
      "logRole",
      "logDate",
      "logShift"
    ].forEach(
      elementId => {
        const field =
          document.getElementById(
            elementId
          );

        if (
          !field ||
          field.dataset
            .leaderRefreshEventBound ===
            "true"
        ) {
          return;
        }

        field.dataset
          .leaderRefreshEventBound =
          "true";

        field.addEventListener(
          "change",
          scheduleLeaderEditorRefresh
        );
      }
    );

    const modal =
      document.getElementById(
        "logEditorModal"
      );

    if (
      modal &&
      modal.dataset
        .leaderApprovalObserved !==
        "true" &&
      typeof MutationObserver ===
        "function"
    ) {
      const observer =
        new MutationObserver(
          () => {
            const isOpen =
              modal.classList.contains(
                "is-open"
              ) ||

              modal.getAttribute(
                "aria-hidden"
              ) ===
                "false";

            if (
              isOpen
            ) {
              scheduleLeaderEditorRefresh();
            }
          }
        );

      observer.observe(
        modal,
        {
          attributes:
            true,

          attributeFilter: [
            "class",
            "aria-hidden"
          ]
        }
      );

      modal.dataset
        .leaderApprovalObserved =
        "true";
    }

    scheduleLeaderEditorRefresh();
  }


  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      initializeLeaderEditorApprovalBindings,
      {
        once:
          true
      }
    );

  } else {
    initializeLeaderEditorApprovalBindings();
  }
})();

/* =========================================================
  일반 보직 수정창 왼쪽 삭제·결재취소 최종본

  왼쪽  : 인쇄 | 삭제 | 결재취소
  오른쪽: 임시저장 | 결재요청 | 닫기

  핵심:
  - 결재요청 버튼은 결재요청 전용으로 유지한다.
  - 결재취소는 결재요청 상태에서만 활성화한다.
  - 결재완료 상태에서는 결재취소를 반드시 비활성화한다.
========================================================= */

(function initializeMemberEditorLeftActions() {
  if (
    window.__memberEditorLeftActionsInstalled ===
    true
  ) {
    return;
  }

  window.__memberEditorLeftActionsInstalled =
    true;

  const MEMBER_ROLES =
    new Set([
      "TGO",
      "BCO1",
      "BCO2",
      "TO",
      "BO1",
      "BO2"
    ]);

  const updateLogEditorActionButtonsBeforeLeftActions =
    typeof updateLogEditorActionButtons ===
      "function"
      ? updateLogEditorActionButtons
      : null;

  let isMemberFooterActionWorking =
    false;


  /* =====================================================
    상태 정규화
  ====================================================== */

  function normalizeMemberFooterStatus(
    status
  ) {
    const normalized =
      typeof normalizeShiftLogApprovalStatus ===
        "function"
        ? normalizeShiftLogApprovalStatus(
            status
          )
        : String(
            status ||
            ""
          ).trim();

    const statusMap = {
      작성중:
        "임시저장",

      임시저장:
        "임시저장",

      저장완료:
        "저장완료",

      작성완료:
        "결재요청",

      결재요청:
        "결재요청",

      결재완료:
        "결재완료"
    };

    return (
      statusMap[
        normalized
      ] ||
      normalized ||
      ""
    );
  }


  function normalizeMemberFooterShift(
    shift
  ) {
    return String(
      shift ||
      ""
    )
      .trim()
      .toUpperCase()
      .replace(
        /[\s/]/g,
        ""
      );
  }


  function getMemberFooterRole() {
    return normalizeMemberLogRole(
      document.getElementById(
        "logRole"
      )?.value ||
      ""
    );
  }


  function isMemberFooterEditor() {
    return MEMBER_ROLES.has(
      getMemberFooterRole()
    );
  }


  /* =====================================================
    현재 수정 중인 일반 보직 업무일지
  ====================================================== */

  function getMemberFooterCurrentLog() {
    const form =
      document.getElementById(
        "logEditorForm"
      );

    const editingId =
      String(
        form?.dataset
          ?.editingId ||
        ""
      ).trim();

    const currentRole =
      getMemberFooterRole();

    const searchLogs =
      typeof currentSearchResultLogs !==
        "undefined" &&
      Array.isArray(
        currentSearchResultLogs
      )
        ? currentSearchResultLogs
        : [];

    const sourceLogs = [
      ...(
        Array.isArray(
          appState?.logs
        )
          ? appState.logs
          : []
      ),

      ...searchLogs
    ];

    if (
      editingId
    ) {
      const editingLog =
        sourceLogs.find(
          log => {
            return (
              String(
                log?.id ||
                ""
              ).trim() ===
                editingId &&

              normalizeMemberLogRole(
                log?.role
              ) ===
                currentRole
            );
          }
        );

      if (
        editingLog
      ) {
        return editingLog;
      }
    }

    if (
      form?.dataset
        ?.editorMode ===
      "new"
    ) {
      return null;
    }

    const currentDate =
      String(
        document.getElementById(
          "logDate"
        )?.value ||
        ""
      ).trim();

    const currentShift =
      normalizeMemberFooterShift(
        document.getElementById(
          "logShift"
        )?.value
      );

    if (
      !currentDate ||
      !currentShift ||
      !MEMBER_ROLES.has(
        currentRole
      )
    ) {
      return null;
    }

    return (
      sourceLogs
        .filter(
          log => {
            const isLegacy =
              typeof isReadOnlyLegacyShiftLog ===
                "function"
                ? isReadOnlyLegacyShiftLog(
                    log
                  )
                : String(
                    log?.source ||
                    ""
                  )
                    .trim()
                    .toLowerCase()
                    .startsWith(
                      "legacy"
                    );

            return (
              !isLegacy &&

              String(
                log?.date ||
                ""
              ).trim() ===
                currentDate &&

              normalizeMemberFooterShift(
                log?.shift
              ) ===
                currentShift &&

              normalizeMemberLogRole(
                log?.role
              ) ===
                currentRole
            );
          }
        )
        .sort(
          (
            firstLog,
            secondLog
          ) => {
            const revisionDifference =
              Number(
                secondLog
                  ?.serverRevision ||
                0
              ) -
              Number(
                firstLog
                  ?.serverRevision ||
                0
              );

            if (
              revisionDifference !==
              0
            ) {
              return revisionDifference;
            }

            return (
              new Date(
                secondLog?.updatedAt ||
                secondLog?.createdAt ||
                0
              ).getTime() -

              new Date(
                firstLog?.updatedAt ||
                firstLog?.createdAt ||
                0
              ).getTime()
            );
          }
        )[0] ||
      null
    );
  }


  /* =====================================================
    버튼 생성
  ====================================================== */

  function createMemberFooterButton({
    id,
    className,
    text
  }) {
    let button =
      document.getElementById(
        id
      );

    if (
      !button
    ) {
      button =
        document.createElement(
          "button"
        );

      button.id =
        id;

      button.type =
        "button";

      button.className =
        className;

      button.textContent =
        text;
    }

    button.type =
      "button";

    return button;
  }


function ensureMemberFooterButtons() {
  const modal =
    document.getElementById(
      "logEditorModal"
    );

  const leftGroup =
    modal?.querySelector(
      ".log-editor-footer__left"
    );

  const rightGroup =
    modal?.querySelector(
      ".log-editor-footer__right"
    );


  if (
    !leftGroup ||
    !rightGroup
  ) {
    return null;
  }


  const printButton =
    document.getElementById(
      "printLogButton"
    );

  const draftButton =
    document.getElementById(
      "saveDraftButton"
    );

  const requestButton =
    document.getElementById(
      "requestApprovalButton"
    );

  const closeButton =
    document.getElementById(
      "cancelLogButton"
    );


  const deleteButton =
    createMemberFooterButton({
      id:
        "memberEditorDeleteButton",

      className:
        "secondary-button log-editor-delete-button",

      text:
        "삭제"
    });


  const cancelButton =
    createMemberFooterButton({
      id:
        "memberEditorApprovalCancelButton",

      className:
        "secondary-button log-editor-cancel-approval-button",

      text:
        "결재취소"
    });


  /*
    중요:
    일반 보직일 때만 공용 버튼을 이동한다.

    파트장 화면에서는 인쇄 버튼을 절대 이동하지 않는다.
  */
  if (
    isMemberFooterEditor()
  ) {
    if (
      printButton
    ) {
      printButton.type =
        "button";

      printButton.classList.add(
        "secondary-button",
        "log-editor-print-button"
      );
    }


    if (
      draftButton
    ) {
      draftButton.classList.add(
        "secondary-button",
        "log-editor-draft-button"
      );
    }


    if (
      requestButton
    ) {
      requestButton.classList.add(
        "approval-button",
        "log-editor-complete-button"
      );
    }


    if (
      closeButton
    ) {
      closeButton.classList.add(
        "secondary-button",
        "log-editor-close-button"
      );
    }


    leftGroup.prepend(
      ...[
        printButton,
        deleteButton,
        cancelButton
      ].filter(
        Boolean
      )
    );


    rightGroup.append(
      ...[
        draftButton,
        requestButton,
        closeButton
      ].filter(
        Boolean
      )
    );

  } else {
    /*
      파트장에서는 일반 보직 전용 버튼만 숨겨서 보관한다.
    */
    deleteButton.hidden =
      true;

    cancelButton.hidden =
      true;

    leftGroup.append(
      deleteButton,
      cancelButton
    );
  }


  return {
    deleteButton,
    cancelButton,
    draftButton,
    requestButton
  };
}


  /* =====================================================
    버튼 상태
  ====================================================== */

  function setMemberFooterButtonState(
    button,
    {
      visible = true,
      enabled = true,
      title = ""
    }
  ) {
    if (
      !button
    ) {
      return;
    }

    button.type =
      "button";

    button.hidden =
      !visible;

    button.disabled =
      !enabled;

    button.title =
      title;

    button.setAttribute(
      "aria-disabled",
      String(
        !enabled
      )
    );

    if (
      visible
    ) {
      button.removeAttribute(
        "hidden"
      );

      button.style.removeProperty(
        "display"
      );

    } else {
      button.setAttribute(
        "hidden",
        ""
      );

      button.style.setProperty(
        "display",
        "none",
        "important"
      );
    }
  }


  /* =====================================================
    일반 보직 버튼 갱신
  ====================================================== */

function refreshMemberFooterButtons() {
  const buttons =
    ensureMemberFooterButtons();


  if (
    !buttons
  ) {
    return;
  }


  if (
    !isMemberFooterEditor()
  ) {
    setMemberFooterButtonState(
      buttons.deleteButton,
      {
        visible:
          false,

        enabled:
          false
      }
    );


    setMemberFooterButtonState(
      buttons.cancelButton,
      {
        visible:
          false,

        enabled:
          false
      }
    );


    return;
  }


  const currentLog =
    getMemberFooterCurrentLog();


  const currentStatus =
    normalizeMemberFooterStatus(
      currentLog?.status
    );


  const hasCurrentLog =
    Boolean(
      currentLog
    );


  /*
    일반 보직의 정식 결재요청 가능 상태는
    임시저장만 사용한다.
  */
  const isDraft =
    hasCurrentLog &&
    currentStatus ===
      "임시저장";


  const isRequested =
    hasCurrentLog &&
    currentStatus ===
      "결재요청";


  const isApproved =
    hasCurrentLog &&
    currentStatus ===
      "결재완료";


  const canSaveDraft =
    !hasCurrentLog ||
    isDraft;


  const isSuperAdmin =
    typeof isCurrentUserSuperAdmin ===
      "function" &&
    isCurrentUserSuperAdmin();


  const hasDeletePermission =
    hasCurrentLog &&
    typeof canCurrentUserDeleteShiftLog ===
      "function" &&
    canCurrentUserDeleteShiftLog(
      currentLog
    );


  const canDelete =
    hasDeletePermission &&
    (
      isDraft ||
      isSuperAdmin
    ) &&
    !isMemberFooterActionWorking;


  const hasCancelPermission =
    isRequested &&
    typeof canCurrentUserCancelShiftLogApproval ===
      "function" &&
    canCurrentUserCancelShiftLogApproval(
      currentLog
    );


  const canCancel =
    isRequested &&
    hasCancelPermission &&
    !isMemberFooterActionWorking;


  setMemberFooterButtonState(
    buttons.deleteButton,
    {
      visible:
        true,

      enabled:
        canDelete,

      title:
        canDelete
          ? "현재 업무일지를 삭제합니다."
          : (
              isRequested
                ? "결재요청을 취소한 뒤 삭제할 수 있습니다."
                : (
                    isApproved
                      ? "결재완료된 업무일지는 삭제할 수 없습니다."
                      : "임시저장된 업무일지만 삭제할 수 있습니다."
                  )
            )
    }
  );


  setMemberFooterButtonState(
    buttons.cancelButton,
    {
      visible:
        true,

      enabled:
        canCancel,

      title:
        canCancel
          ? "결재요청을 취소하고 임시저장 상태로 되돌립니다."
          : (
              isApproved
                ? "파트장이 결재완료한 업무일지는 수정창에서 결재취소할 수 없습니다."
                : "결재요청 상태에서만 사용할 수 있습니다."
            )
    }
  );


  setMemberFooterButtonState(
    buttons.draftButton,
    {
      visible:
        true,

      enabled:
        canSaveDraft &&
        !isMemberFooterActionWorking,

      title:
        canSaveDraft
          ? "현재 작성 내용을 임시저장합니다."
          : "현재 상태에서는 임시저장할 수 없습니다."
    }
  );


  setMemberFooterButtonState(
    buttons.requestButton,
    {
      visible:
        hasCurrentLog,

      enabled:
        isDraft &&
        !isMemberFooterActionWorking,

      title:
        isDraft
          ? "임시저장된 업무일지를 결재요청합니다."
          : (
              isRequested
                ? "이미 결재요청한 업무일지입니다."
                : (
                    isApproved
                      ? "이미 결재완료된 업무일지입니다."
                      : "임시저장 상태에서만 결재요청할 수 있습니다."
                  )
            )
    }
  );


  if (
    buttons.requestButton
  ) {
    buttons.requestButton.textContent =
      "결재요청";

    buttons.requestButton.classList.remove(
      "is-cancel-request"
    );

    buttons.requestButton.dataset
      .memberApprovalAction =
      "request";

    buttons.requestButton.setAttribute(
      "aria-label",
      "업무일지 결재요청"
    );
  }
}


  /* =====================================================
    서버 결과 반영
  ====================================================== */

  function applyMemberFooterSavedLog(
    savedLog
  ) {
    if (
      !savedLog
    ) {
      return null;
    }

    const appliedLog =
      typeof replaceSharedShiftLogInState ===
        "function"
        ? (
            replaceSharedShiftLogInState(
              savedLog
            ) ||
            savedLog
          )
        : savedLog;

    const form =
      document.getElementById(
        "logEditorForm"
      );

    if (
      form
    ) {
      form.dataset.editingId =
        String(
          appliedLog.id ||
          ""
        );

      form.dataset.editorMode =
        "existing-edit";
    }

    if (
      typeof renderLogTable ===
      "function"
    ) {
      renderLogTable();
    }

    if (
      typeof updateShiftMemberCardStates ===
      "function"
    ) {
      updateShiftMemberCardStates();
    }

    if (
      typeof markLogEditorAsSaved ===
      "function"
    ) {
      markLogEditorAsSaved();
    }

    return appliedLog;
  }


  async function confirmMemberFooterAction(
    options
  ) {
    if (
      typeof showCompactConfirm ===
      "function"
    ) {
      return Boolean(
        await showCompactConfirm(
          options
        )
      );
    }

    return window.confirm(
      String(
        options?.message ||
        ""
      )
    );
  }


  function handleMemberFooterError(
    error,
    fallbackMessage
  ) {
    console.error(
      fallbackMessage,
      error
    );

    if (
      error?.isConflict ===
        true &&
      typeof handleShiftLogConflict ===
        "function"
    ) {
      handleShiftLogConflict(
        error
      );

      return;
    }

    showToast(
      error?.message ||
      fallbackMessage
    );
  }


  /* =====================================================
    일반 보직 결재취소
  ====================================================== */

  async function cancelMemberFooterApproval() {
    const currentLog =
      getMemberFooterCurrentLog();

    const currentStatus =
      normalizeMemberFooterStatus(
        currentLog?.status
      );

    /*
      결재완료 상태는 여기서 무조건 차단된다.
    */
    if (
      !currentLog ||
      currentStatus !==
        "결재요청"
    ) {
      showToast(
        "결재요청 상태의 업무일지만 취소할 수 있습니다."
      );

      return;
    }

    const canCancel =
      typeof canCurrentUserCancelShiftLogApproval ===
        "function" &&
      canCurrentUserCancelShiftLogApproval(
        currentLog
      );

    if (
      !canCancel
    ) {
      showToast(
        "결재요청한 작성자 본인만 요청을 취소할 수 있습니다."
      );

      return;
    }

    const shouldCancel =
      await confirmMemberFooterAction({
        title:
          "결재취소",

        message:
          "결재요청을 취소하고 임시저장 상태로 되돌릴까요?",

        confirmText:
          "결재취소",

        cancelText:
          "유지"
      });

    if (
      !shouldCancel
    ) {
      return;
    }

    const cancelledLog =
      await changeShiftLogApprovalOnServer(
        currentLog,
        "cancel"
      );

    if (
      !cancelledLog
    ) {
      throw new Error(
        "결재취소 결과를 확인할 수 없습니다."
      );
    }

    applyMemberFooterSavedLog(
      cancelledLog
    );

    showToast(
      "결재요청을 취소했습니다. 다시 수정할 수 있습니다."
    );
  }


  /* =====================================================
    일반 보직 삭제
  ====================================================== */

  async function deleteMemberFooterLog() {
    const currentLog =
      getMemberFooterCurrentLog();

    if (
      !currentLog
    ) {
      showToast(
        "삭제할 업무일지를 찾을 수 없습니다."
      );

      return;
    }

    const currentStatus =
      normalizeMemberFooterStatus(
        currentLog.status
      );

    const isSuperAdmin =
      typeof isCurrentUserSuperAdmin ===
        "function" &&
      isCurrentUserSuperAdmin();

    const canDelete =
      typeof canCurrentUserDeleteShiftLog ===
        "function" &&
      canCurrentUserDeleteShiftLog(
        currentLog
      ) &&
      (
        [
          "임시저장",
          "저장완료"
        ].includes(
          currentStatus
        ) ||
        isSuperAdmin
      );

    if (
      !canDelete
    ) {
      showToast(
        currentStatus ===
          "결재요청"
          ? "결재요청을 취소한 후 삭제할 수 있습니다."
          : "현재 상태에서는 이 업무일지를 삭제할 수 없습니다."
      );

      return;
    }

    const shouldDelete =
      await confirmMemberFooterAction({
        title:
          "업무일지 삭제",

        message:
          "현재 업무일지를 삭제할까요? 삭제한 자료는 복구할 수 없습니다.",

        confirmText:
          "삭제",

        cancelText:
          "취소"
      });

    if (
      !shouldDelete
    ) {
      return;
    }

    const deletedId =
      await deleteShiftLogFromServer(
        currentLog
      );

    if (
      typeof removeSharedShiftLogFromState ===
      "function"
    ) {
      removeSharedShiftLogFromState(
        deletedId ||
        currentLog.id
      );
    }

    if (
      typeof renderLogTable ===
      "function"
    ) {
      renderLogTable();
    }

    if (
      typeof updateShiftMemberCardStates ===
      "function"
    ) {
      updateShiftMemberCardStates();
    }

    if (
      typeof closeLogEditor ===
      "function"
    ) {
      closeLogEditor();
    }

    showToast(
      "업무일지를 삭제했습니다."
    );
  }


  /* =====================================================
    버튼 작업 실행
  ====================================================== */

  async function runMemberFooterAction(
    action,
    button
  ) {
    if (
      !isMemberFooterEditor() ||
      isMemberFooterActionWorking ||
      button?.disabled
    ) {
      return;
    }

    isMemberFooterActionWorking =
      true;

    try {
      refreshMemberFooterButtons();

      if (
        action ===
        "cancel"
      ) {
        await cancelMemberFooterApproval();

      } else if (
        action ===
        "delete"
      ) {
        await deleteMemberFooterLog();
      }

    } catch (
      error
    ) {
      handleMemberFooterError(
        error,
        "업무일지 작업을 처리하지 못했습니다."
      );

    } finally {
      isMemberFooterActionWorking =
        false;

      updateLogEditorActionButtons();
    }
  }


  /* =====================================================
    버튼 이벤트
  ====================================================== */

  function bindMemberFooterButtons() {
    const buttons =
      ensureMemberFooterButtons();

    if (
      !buttons
    ) {
      return;
    }

    if (
      buttons.deleteButton
        .dataset
        .memberFooterBound !==
      "true"
    ) {
      buttons.deleteButton
        .dataset
        .memberFooterBound =
        "true";

      buttons.deleteButton.addEventListener(
        "click",
        event => {
          event.preventDefault();

          void runMemberFooterAction(
            "delete",
            buttons.deleteButton
          );
        }
      );
    }

    if (
      buttons.cancelButton
        .dataset
        .memberFooterBound !==
      "true"
    ) {
      buttons.cancelButton
        .dataset
        .memberFooterBound =
        "true";

      buttons.cancelButton.addEventListener(
        "click",
        event => {
          event.preventDefault();

          void runMemberFooterAction(
            "cancel",
            buttons.cancelButton
          );
        }
      );
    }
  }


  /* =====================================================
    기존 버튼 갱신 후 왼쪽 버튼 상태 적용
  ====================================================== */

  updateLogEditorActionButtons =
    function updateLogEditorActionButtons(
      ...args
    ) {
      const previousResult =
        updateLogEditorActionButtonsBeforeLeftActions
          ?.apply(
            this,
            args
          );

      bindMemberFooterButtons();

      refreshMemberFooterButtons();

      return previousResult;
    };


  function scheduleMemberFooterRefresh() {
    [
      0,
      60,
      180,
      360
    ].forEach(
      delay => {
        window.setTimeout(
          () => {
            updateLogEditorActionButtons();
          },
          delay
        );
      }
    );
  }


  /* =====================================================
    초기 연결
  ====================================================== */

  function initializeMemberFooterBindings() {
    bindMemberFooterButtons();

    [
      "logRole",
      "logDate",
      "logShift"
    ].forEach(
      elementId => {
        const field =
          document.getElementById(
            elementId
          );

        if (
          !field ||
          field.dataset
            .memberFooterRefreshBound ===
            "true"
        ) {
          return;
        }

        field.dataset
          .memberFooterRefreshBound =
          "true";

        field.addEventListener(
          "change",
          scheduleMemberFooterRefresh
        );
      }
    );

    const modal =
      document.getElementById(
        "logEditorModal"
      );

    if (
      modal &&
      modal.dataset
        .memberFooterObserved !==
        "true" &&
      typeof MutationObserver ===
        "function"
    ) {
      const observer =
        new MutationObserver(
          () => {
            const isOpen =
              modal.classList.contains(
                "is-open"
              ) ||
              modal.getAttribute(
                "aria-hidden"
              ) ===
                "false";

            if (
              isOpen
            ) {
              scheduleMemberFooterRefresh();
            }
          }
        );

      observer.observe(
        modal,
        {
          attributes:
            true,

          attributeFilter: [
            "class",
            "aria-hidden"
          ]
        }
      );

      modal.dataset
        .memberFooterObserved =
        "true";
    }

    scheduleMemberFooterRefresh();
  }


  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      initializeMemberFooterBindings,
      {
        once:
          true
      }
    );

  } else {
    initializeMemberFooterBindings();
  }
})();